  /* Alles, was NUR einem Platz gilt und niemals ueber den ganzen
     Chat regnen darf. Aus LC_EFFEKTE laesst sich das nicht ablesen —
     dort steht zu jedem ein Zeichen, und genau das war der Regen. */
  const LC_NUR_AM_PLATZ = {
    tritt: 1, zherz: 1, eimer: 1, wecker: 1, regenwolke: 1, donnerwolke: 1,
    reichtum: 1, zucker: 1, hammer: 1, heber: 1, lasso: 1,
    schneeball: 1, bumerang: 1, saugpfeil: 1, sahne: 1, sog: 1, trommel: 1,
    paintfleck: 1, ei: 1, fahren: 1, spielzug: 1, pacjagd: 1, stoerung: 1,
    aufessen: 1, lotto: 1, sanduhr: 1, katapult: 1, strohhalm: 1, blubbern: 1,
    knuell: 1, rollo: 1, lamellen: 1, peitsche: 1, gemeinsam: 1, schneekugel: 1,
    flug: 1, maulwurf: 1, portal: 1, boot: 1, kran: 1, brennen: 1, zorro: 1,
    dampfer: 1, lok: 1, liane: 1, feder: 1, beamen: 1, rohr: 1,
    heli: 1, pferd: 1, marsch: 1, greifvogel: 1, turm: 1, aufblasen: 1,
    untertasse: 1, mieze: 1, gotteshand: 1, pranke: 1, frisbee: 1, sonnenbrille: 1,
    neunschwanz: 1,
    bowling: 1, billard: 1, kopfhoerer: 1, luke: 1, platte: 1, ohrfeige: 1, lunte: 1,
    basketball: 1, tennis: 1, krumel: 1, zufall: 1,
    licht: 1, muenze: 1, wischer: 1, zwille: 1, pusterohr: 1, gluehbirne: 1,
    vogelkot: 1, spucken: 1,
    birneraus: 1,
    entbloessung: 1, hut: 1, bombe: 1, streicheln: 1, kuss: 1, klaps: 1
  };

  function lcWirkung(art, anZeile, nachricht) {
    const e = LC_EFFEKTE[art];
    if (!e) return;
    /* MUSIK ZUERST: sie zeichnet nichts, sie klingt nur. Wuerde sie
       weiter unten landen, regnete zu jedem Lied ein Notenschauer
       ueber den Chat — und genau das war bei den Platz-Effekten
       schon einmal der Fehler. */
    if (art === "musik") {
      lcMusikSpielen((nachricht && nachricht.lied) || "",
                     (nachricht && nachricht.liedTitel) || "");
      return;
    }
    if (art === "musikaus") { lcMusikStoppen(); return; }
    /* /noten MIT einem Lied: der Refrain klingt, und die Noten steigen
       trotzdem auf — deshalb faellt es NICHT durch, sondern zeichnet
       gleich hier weiter (kein return). */
    if (art === "notenlied") {
      lcMusikSpielen((nachricht && nachricht.lied) || "",
                     (nachricht && nachricht.liedTitel) || "",
                     (nachricht && nachricht.liedAb) || 0);
      art = "noten";
    }
    /* Das Whiteboard zeichnet auch nichts UEBER den Chat — es nimmt
       den Platz der Sitzreihe ein. Deshalb steht es wie die Musik
       ganz oben und faellt nicht in die Effektschleife. */
    if (art === "tafelauf") {
      lcTafelZeigen(true, (nachricht && nachricht.eigen)
        ? (() => { try { return (LiveChat.lage() || {}).ichName || ""; } catch (e) { return ""; } })()
        : ((nachricht && nachricht.name) || ""));
      return;
    }
    if (art === "tafelzu") { lcTafelZeigen(false); return; }
    if (art === "musikpause") { lcMusikPause(true); return; }
    if (art === "musikweiter") { lcMusikPause(false); return; }
    /* Die Umarmung ist der einzige Effekt, der jemanden MEINT. Sie
       braucht deshalb den Namen aus der Zeile — siehe lcUmarmung(). */
    if (art === "umarmen" && lcUmarmung(nachricht && (nachricht.wen || nachricht.an))) return;
    if (art === "lecken") {
      const wenL = nachricht && (nachricht.wen || nachricht.an);
      let vonL = (nachricht && nachricht.name) || "";
      if (nachricht && nachricht.eigen) {
        try { vonL = (LiveChat.lage() || {}).ichName || vonL; } catch (e) {}
      }
      if (lcLecken(wenL, vonL)) return;
    }
    /* Die Animationen, die einem PLATZ gelten — alle nach demselben
       Muster: Name aus der Zeile, Zeichnung an den Platz. Trifft der
       Name niemanden (die Person ist gegangen), geben sie false
       zurueck und es faellt auf die gewoehnliche Wirkung durch. */
    {
      const wenZ = nachricht && (nachricht.wen || nachricht.an);
      /* WER WIRFT, STEHT IN DER ZEILE — NICHT VOR DEM GERAET.
         GEMELDET: „Schau nach, dass die Effekte auf beiden Seiten
         synchron sind."
         GEFUNDEN: lcWurfRichtung nahm als Werfer IMMER den eigenen
         Platz (.lc-platz-ich). Beim Absender stimmte das; bei allen
         anderen flog derselbe Schneeball aus einer anderen Ecke, und
         wer daneben sass, sah ihn sogar aus sich selbst herauskommen.
         Der Absender steht in jeder Zeile — hier wird er einmal
         gemerkt, und lcWurfRichtung nimmt ihn statt des eigenen
         Platzes. */
      lcWurfVon = (nachricht && nachricht.eigen)
        ? (() => { try { return (LiveChat.lage() || {}).ichName || ""; } catch (e) { return ""; } })()
        : ((nachricht && nachricht.name) || "");
      if (art === "tritt" && lcTritt(wenZ)) return;
      if (art === "zherz" && lcHerzenAufPlatz(wenZ)) return;
      if (art === "eimer" && lcWassereimer(wenZ)) return;
      if (art === "wecker" && lcWecker(wenZ)) return;
      if (art === "regenwolke" && lcWolkeUeber(wenZ, false)) return;
      if (art === "donnerwolke" && lcWolkeUeber(wenZ, true)) return;
      if (art === "reichtum" && lcReichtum(wenZ)) return;
      if (art === "zucker" && lcZuckerregen(wenZ)) return;
      if (art === "hammer" && lcHammer(wenZ)) return;
      if (art === "schneeball" && lcSchneeball(wenZ)) return;
      if (art === "bumerang" && lcBumerang(wenZ)) return;
      if (art === "saugpfeil" && lcSaugpfeil(wenZ)) return;
      if (art === "sahne" && lcSahne(wenZ)) return;
      if (art === "sog" && lcSog(wenZ)) return;
      if (art === "trommel" && lcTrommel(wenZ)) return;
      if (art === "heber" && lcHeber(wenZ, nachricht)) return;
      if (art === "lasso" && lcLasso(wenZ)) return;
      if (art === "aufblasen" && lcAufblasen(wenZ)) return;
      if (art === "paintfleck" && lcPaintfleck(wenZ)) return;
      if (art === "ei" && lcEi(wenZ)) return;
      if (art === "pacjagd" && lcPacJagd(wenZ, (nachricht && nachricht.eigen)
            ? ((LiveChat.lage() || {}).ichName || "") : ((nachricht && nachricht.name) || ""))) return;
      if (art === "stoerung" && lcStoerung(wenZ)) return;
      if (art === "aufessen" && lcAufessen(wenZ)) return;
      if (art === "sanduhr" && lcSanduhrTausch(wenZ, (nachricht && nachricht.eigen)
            ? ((LiveChat.lage() || {}).ichName || "") : ((nachricht && nachricht.name) || ""))) return;
      if (art === "katapult" && lcKatapult(wenZ)) return;
      if (art === "marsch" && lcTrommel(wenZ, true)) return;
      if (art === "gong" && lcGong(wenZ)) return;
      if (art === "bongo" && lcBongo(wenZ)) return;
      if (art === "brennen" && lcBrennen(wenZ)) return;
      if (art === "zorro" && lcZorro(wenZ)) return;
      if (art === "strohhalm" && lcStrohhalm(wenZ)) return;
      if (art === "blubbern" && lcBlubbern(wenZ)) return;
      if (art === "knuell" && lcZerknuellen(wenZ)) return;
      if (art === "schneekugel" && lcSchneekugel(wenZ)) return;
      if (art === "rollo" && lcRollo(wenZ)) return;
      if (art === "lamellen" && lcLamellen(wenZ)) return;
      if (art === "peitsche" && lcPeitsche(wenZ)) return;
      /* Die neunschwaenzige gilt ALLEN und braucht deshalb nicht den
         Getroffenen, sondern den ABSENDER — wie das Fahren. */
      if (art === "neunschwanz" && lcNeunschwanz(lcWurfVon)) return;
      if (art === "bowling" && lcStoss(wenZ, "bowling")) return;
      /* GEWUENSCHT: „wenn ich mit jemandem gemeinsam fahren will, dann
         kriege ich sein Profilbild an und sage dann Fahrrad oder so
         und dann fahren wir einfach weg." — bewegt BEIDE, deshalb
         braucht es wie beim Fahren auch den Absender. */
      if (art === "gemeinsam" && lcGemeinsam(wenZ, (nachricht && nachricht.eigen)
            ? ((LiveChat.lage() || {}).ichName || "") : ((nachricht && nachricht.name) || ""))) return;
      if (art === "billard" && lcBillard(wenZ, (nachricht && nachricht.eigen)
            ? ((LiveChat.lage() || {}).ichName || "") : ((nachricht && nachricht.name) || ""),
            nachricht && nachricht.los)) return;
      if (art === "kopfhoerer" && lcKopfhoerer(wenZ, nachricht)) return;
      if (art === "luke" && lcLuke(wenZ)) return;
      if (art === "platte" && lcPlatte(wenZ)) return;
      if (art === "ohrfeige" && lcOhrfeige(wenZ)) return;
      if (art === "basketball" && lcBall(wenZ, "basketball")) return;
      if (art === "tennis" && lcBall(wenZ, "tennis")) return;
      /* GEMELDET: „Dieser Keks-Effekt — das soll ein einzelner sein.
         Ich glaube, du hast Kekse und Aufessen jeweils einmal, aber
         das, was Aufessen macht, soll eigentlich der Keks-Effekt
         sein."
         Also einer statt zwei: /keks Name macht jetzt dasselbe wie
         /aufessen. lcKrumel bleibt als Rueckfall stehen, falls
         jemand eine alte Zeile aus seinem Verlauf antippt. */
      if (art === "krumel" && (lcAufessen(wenZ) || lcKrumel(wenZ))) return;
      if (art === "licht" && lcLichtAus(wenZ)) return;
      if (art === "muenze" && lcMuenze(wenZ)) return;
      if (art === "wischer" && lcWischer(wenZ)) return;
      if (art === "zwille" && lcZwille(wenZ)) return;
      if (art === "pusterohr" && lcPusterohr(wenZ)) return;
      if (art === "vogelkot" && lcVogelKot(wenZ)) return;
      if (art === "spucken" && lcSpucken(wenZ)) return;
      if (art === "gluehbirne" && lcGluehbirne(wenZ)) return;
      if (art === "birneraus" && lcGluehbirneRaus()) return;
      if (art === "hut" && lcHut(wenZ)) return;
      if (art === "klaps" && lcKlaps(wenZ)) return;
      if (art === "sonnenbrille" && lcSonnenbrille(wenZ)) return;
      if (art === "bombe" && lcBombe(wenZ, false)) return;
      if (art === "granate" && lcGranate(wenZ)) return;
      if (art === "lunte" && lcBombe(wenZ, true)) return;
      if (art === "streicheln" && lcStreicheln(wenZ)) return;
      if (art === "kuss" && lcKuss(wenZ)) return;
      if (art === "entbloessung" && lcEntbloessung(wenZ, (nachricht && nachricht.eigen)
            ? ((LiveChat.lage() || {}).ichName || "") : ((nachricht && nachricht.name) || ""))) return;
      if (art === "zufall" && lcZufall(wenZ, nachricht)) return;
    }
    /* Fahren und Spielzug bewegen den ABSENDER, nicht den
       Genannten — deshalb brauchen sie beide Namen. Bei der
       eigenen Zeile steht der Absender nicht dran (man ist ja
       selbst gemeint), dort kommt er aus der Lage. */
    /* Das Lotto bewegt NUR den Absender — es hat gar kein Ziel. */
    if (art === "lotto") {
      let vonL = (nachricht && nachricht.name) || "";
      if (nachricht && nachricht.eigen) {
        try { vonL = (LiveChat.lage() || {}).ichName || vonL; } catch (e) {}
      }
      if (lcLotto(vonL)) return;
    }
    /* Fliegen, Graben und das Tor bewegen ebenfalls den Absender. */
    if (art === "flug" || art === "maulwurf" || art === "portal"
        || art === "boot" || art === "kran" || art === "dampfer"
        || art === "lok" || art === "liane" || art === "feder"
        || art === "beamen" || art === "rohr"
        || art === "heli" || art === "pferd"
        || art === "greifvogel" || art === "turm"
        /* RUNDE 75 */
        || art === "untertasse" || art === "mieze" || art === "frisbee"
        || art === "gotteshand" || art === "pranke") {
      const wenR = nachricht && (nachricht.wen || nachricht.an);
      let vonR = (nachricht && nachricht.name) || "";
      if (nachricht && nachricht.eigen) {
        try { vonR = (LiveChat.lage() || {}).ichName || vonR; } catch (e) {}
      }
      /* RUNDE 78 — „tausch" reist mit der Nachricht, damit JEDES
         Geraet dieselben zwei Bilder fliegen sieht. Stuende es nur
         beim Absender, saehen die anderen nur eine halbe Reise. */
      if (lcReise(wenR, vonR, art, Boolean(nachricht && nachricht.tausch))) return;
    }
    if (art === "fahren" || art === "spielzug") {
      const wenF = nachricht && (nachricht.wen || nachricht.an);
      let vonF = (nachricht && nachricht.name) || "";
      if (nachricht && nachricht.eigen) {
        try { vonF = (LiveChat.lage() || {}).ichName || vonF; } catch (e) {}
      }
      /* Steht dort eine KETTE („1-5-6-7-8"), ist das der gemalte
         Weg — er wird genau so abgefahren, siehe lcWegMalen. */
      const kette = /^\s*\d+(-\d+)+\s*$/.test(String(wenF || ""))
        ? String(wenF).split("-").map((x) => parseInt(x, 10))
        : null;
      if (lcFahrt(kette ? kette[kette.length - 1] : wenF, vonF, art, kette,
                  Number((nachricht && nachricht.tempo) || 1) || 1)) return;
    }
    /* =========================================================
       HIER IST SCHLUSS FUER ALLES, WAS EINEM PLATZ GILT
       ---------------------------------------------------------
       GEMELDET, und es stimmte: „Wenn ich auf das Auto klicke,
       dann regnet es kleine Autos — die sollen gar nicht kommen …
       Bei der Pac-Man-Animation moechte ich nicht, dass viele
       Pac-Man nach unten fliegen. Bei der Auto-Animation moechte
       ich auch nicht, dass viele Autos nach unten fliegen. Diese
       Animationen sollen das machen, was sie sind, und nicht
       zusaetzlich Autos regnen oder Pac-Men regnen … Bei der
       Sanduhr fliegen Sanduhr-Emojis ueber den Chat. Ueberall da,
       wo diese Emojis ueber den Chat fliegen, wo gar keine Emojis
       regnen sollen, machst du die bitte weg."

       Woher der Regen kam: LC_EFFEKTE haelt zu jedem Platz-Effekt
       ein Zeichen als RUECKFALL — gedacht fuer den Fall, dass die
       gemeinte Person gar nicht mehr im Raum sitzt. Lief die
       Zeichnung am Platz durch, kam der Rueckfall nie dran; lief
       sie NICHT durch (Ziel weg, Weg versperrt, eigener Platz),
       fiel es hier durch bis zum Teilchenregen. Genau das hat er
       gesehen.

       Ein Platz-Effekt, der nicht greift, macht jetzt gar nichts
       mehr — ausser einem stillen Hinweis an den Absender. Der
       Regen bleibt den Raum-Effekten, wo er hingehoert. */
    if (LC_NUR_AM_PLATZ[art]) {
      if (nachricht && nachricht.eigen) {
        const wenX = nachricht && (nachricht.wen || nachricht.an);
        try {
          showToast(wenX ? "\ud83d\udc64 " + wenX + " sitzt gerade nicht im Raum."
                         : "Das geht hier gerade nicht.");
        } catch (err) {}
      }
      return;
    }
    /* Beim Boxen zählt auch, WER geboxt hat — er bekommt den
       Rückschlag ab. Bei der eigenen Zeile steht der Name nicht dran
       (man ist ja selbst gemeint), deshalb wird er dort aus der Lage
       geholt. */
    if (art === "boxen") {
      const wenBox = nachricht && (nachricht.wen || nachricht.an);
      let vonBox = (nachricht && nachricht.name) || "";
      if (nachricht && nachricht.eigen) {
        try { vonBox = (LiveChat.lage() || {}).ichName || vonBox; } catch (e) {}
      }
      if (lcBoxen(wenBox, vonBox)) return;
    }
    /* Konfetti gehört nicht ins Chatkästchen, sondern über die ganze
       Seite — sonst sieht man es kaum. */
    if (e.ganzeSeite) {
      /* ERST DEN RAUM GERADERUECKEN, DANN DIE ANIMATION.
         GEWÜNSCHT: „Weil zur Eingabe die Eingabe immer ein bisschen
         nach oben springt — dass der Chat wieder in die Position
         springt, wo er ursprünglich ist, damit man die Animation
         schön geniessen kann und nicht erst hochscrollen muss."
         Das ist dieselbe Rechnung wie beim Klick auf den Reiter,
         also genau EINE Stelle, und sie rechnet absolut. */
      try { livechatAnSeinenPlatz(true); } catch (err) {}
      /* LIEGT ZU DIESER ANIMATION EIN FILM BEREIT? DANN DER FILM.
         Bisher galt das nur für die grossen Geschenke. Es gilt
         jetzt für JEDE ganzseitige Animation: heisst eine Datei in
         filme/ genauso wie der Effekt, läuft sie statt der
         Zeichnung. So bekommt „/schlitten" den echten
         Weihnachtsschlitten und „/katze" das echte Kätzchen, ohne
         dass es dafür zwei Befehle gäbe — und ohne dass eine
         gezeichnete Animation wegfällt: fehlt der Film, wird
         gezeichnet wie immer. */
      const filmName = lcFilmDa(art) ? art : (lcFilmDa(e.tier) ? e.tier : "");
      if (filmName) {
        lcFilmSpielen(filmName).then((lief) => {
          if (!lief) { lcTonZu(e.wie || art); lcWirkungGezeichnet(e, nachricht); }
        });
        return;
      }
      /* Ein kurzer Ton dazu, wo er passt — nicht länger als eine
         knappe Sekunde, die Animation läuft weiter.

         AUSNAHME, GEMELDET: „Man hoert diesen Geschenk-Jubel im
         Hintergrund von dem, was da vorher drin lag, und man
         hoert nicht den Sound von den Videos." Richtig — der
         Jubel gehoert zur gezeichneten Kiste. Bringt das Geschenk
         einen FILM mit, hat der seine eigene Tonspur, und zwei
         Tonspuren uebereinander sind einfach Krach. */
      if (!(e.wie === "gg" && lcFilmDa(e.tier))) lcTonZu(e.wie || art);
      lcWirkungGezeichnet(e, nachricht);
      return;
    }
    const v = document.getElementById("lcVerlauf");
    if (!v) return;
    const schicht = document.createElement("div");
    schicht.className = "lc-wirkung lc-wirkung-" + e.klasse;
    /* Die Teilchen steigen dort auf, wo die Zeile steht — nicht
       irgendwo im Fenster.

       NACHGEBESSERT: „Schau, wo man sich im Chat befindet und wo der
       Effekt, den man sendet, am besten wirkt."

       Die grossen Effekte liegen alle fest am Fenster und sind deshalb
       immer zu sehen — nachgemessen, bei weit heruntergescrollter
       Seite. Dieser kleine hier klebte dagegen an SEINER Zeile: hatte
       man im Verlauf hochgescrollt, stieg er zweihundert Pixel
       ausserhalb des Sichtbaren auf und niemand sah etwas.

       Jetzt wird er in den sichtbaren Ausschnitt des Verlaufs
       hineingezogen, wenn er sonst daneben läge. Er bleibt an seiner
       Zeile, solange die zu sehen ist — und wird sichtbar, wenn nicht.
       Ein Effekt, den niemand sieht, ist kein Effekt. */
    const HOCH = 190;
    if (anZeile) {
      const r = anZeile.getBoundingClientRect();
      const rv = v.getBoundingClientRect();
      let oben = r.top - rv.top + v.scrollTop - 150;
      const sichtbarVon = v.scrollTop;
      const sichtbarBis = v.scrollTop + v.clientHeight - HOCH;
      if (sichtbarBis > sichtbarVon) {
        oben = Math.min(Math.max(oben, sichtbarVon), sichtbarBis);
      } else {
        oben = sichtbarVon;
      }
      schicht.style.top = Math.max(0, Math.round(oben)) + "px";
      schicht.style.height = HOCH + "px";
    }
    for (let i = 0; i < e.wie; i++) {
      const t = document.createElement("span");
      t.textContent = e.zeichen[i % e.zeichen.length];
      t.style.left = Math.round(4 + Math.random() * 90) + "%";
      /* Herzen stehen verteilt und schlagen an Ort und Stelle; alle
         anderen Zeichen steigen wie bisher vom unteren Rand auf. */
      if (e.schlaegt) t.style.top = Math.round(12 + Math.random() * 64) + "%";
      t.style.animationDelay = (Math.random() * 0.7).toFixed(2) + "s";
      t.style.fontSize = (0.85 + Math.random() * 1.3).toFixed(2) + "rem";
      t.style.opacity = (0.35 + Math.random() * 0.5).toFixed(2);
      t.style.setProperty("--lc-drift", (Math.random() * 60 - 30).toFixed(0) + "px");
      schicht.appendChild(t);
    }
    v.appendChild(schicht);
    setTimeout(() => schicht.remove(), 3400);
  }

  /* =================================================================
     DER CHATHINTERGRUND
     -----------------------------------------------------------------
     GEWÜNSCHT: „Du hast vergessen, einen schönen Chathintergrund
     einzustellen, der ein bisschen animiert ist — also wo die kleinen
     Vorschaubilder sind der Personen, da im Hintergrund für den Chat
     irgendwie so. Ansonsten möchte ich, dass man da alternativ auch
     ein Bild einladen kann als Hintergrundbild."

     Beides ist da. Die Vorschaubilder der Leute treiben ganz schwach
     und sehr langsam hinter dem Text — man erkennt, wer im Raum ist,
     ohne dass es vom Lesen ablenkt. Wer lieber sein eigenes Bild
     hinterlegt, tippt /hintergrund; das Bild wird verkleinert und
     bleibt im Gerät.
     ================================================================= */
  /* Der Hintergrund liegt im Lager (IndexedDB), nicht im localStorage —
     siehe hintergrundSichern() in livechat.js. Hier wird er einmal
     geholt und dann gemerkt, damit das Zeichnen nicht jedes Mal auf
     die Datenbank warten muss. */
  let lcHgGemerkt = null;          // null = noch nicht geholt
  /* IM RAUM GILT DER HINTERGRUND DES RAUMS.
     GEWÜNSCHT: „Wenn ich den Hintergrund einstelle, dass der für alle
     sichtbar ist."

     Damit kann es nicht zwei Wahrheiten geben: solange man in einem
     Raum ist, zählt nur, was der Raum sagt — sonst sähe jeder etwas
     anderes und niemand wüsste, welches das richtige ist. Die eigene
     Einstellung bleibt im Gerät und gilt wieder, sobald man
     hinausgeht; und wer einen leeren Raum betritt, bringt sie mit. */
  function lcImRaum() {
    try { return Boolean(window.LiveChat && LiveChat.lage && LiveChat.lage().lage === "drin"); }
    catch (e) { return false; }
  }
  function lcHintergrundBild() {
    if (lcImRaum() && LiveChat.raumHintergrund) return LiveChat.raumHintergrund() || "";
    return lcHgGemerkt || "";
  }
  function lcHintergrundHolen() {
    if (lcHgGemerkt !== null) return Promise.resolve(lcHgGemerkt);
    if (!(window.LiveChat && LiveChat.hintergrundHolen)) { lcHgGemerkt = ""; return Promise.resolve(""); }
    return LiveChat.hintergrundHolen().then((d) => {
      lcHgGemerkt = d || "";
      if (lcHgGemerkt) renderLiveChat();
      return lcHgGemerkt;
    }).catch(() => { lcHgGemerkt = ""; return ""; });
  }
  function lcHintergrundSetzen(daten) {
    const wert = daten || "";
    /* Im Gerät bleibt er immer stehen — das ist die eigene Vorliebe,
       und sie gilt wieder, sobald man keinen Raum mehr betritt. */
    lcHgGemerkt = wert;
    if (window.LiveChat && LiveChat.hintergrundSichern) {
      LiveChat.hintergrundSichern(wert).catch(() => {});
    }
    /* Und im Raum gilt er für alle. Sagt der Raum nein — weil das Bild
       zu gross ist, um es an alle zu schicken — dann wird das gesagt und
       nicht stillschweigend nur bei mir gesetzt. Genau so ein
       stillschweigendes Halbergebnis wäre nämlich das, was aussieht wie
       „geht nicht", ohne dass jemand erfährt warum. */
    if (lcImRaum() && LiveChat.raumHintergrundSetzen) {
      const antwort = LiveChat.raumHintergrundSetzen(wert);
      if (antwort && antwort.ok === false) {
        showToast("🖼️ " + antwort.warum);
        renderLiveChat();
        return false;
      }
    }
    renderLiveChat();
    return true;
  }

  /* Wer einen leeren Raum betritt, bringt seinen eigenen Hintergrund
     mit — er ist ja allein, es wird niemand überrascht. Ist schon
     jemand da, gilt weiter, was der Raum hat. */
  function lcHintergrundInDenRaumBringen() {
    if (!lcImRaum() || !LiveChat.raumHintergrundSetzen) return;
    if (LiveChat.raumHintergrund && LiveChat.raumHintergrund()) return;
    if (!lcHgGemerkt) return;
    const l = LiveChat.lage();
    const andere = (l.plaetze || []).filter((p) => !p.leer && !p.ich).length;
    if (andere > 0) return;
    LiveChat.raumHintergrundSetzen(lcHgGemerkt);
  }

  /* =================================================================
     FERTIGE HINTERGRÜNDE — OHNE DASS MAN EIN BILD HAT
     -----------------------------------------------------------------
     GEMELDET: „Du solltest grundlegend auch ohne meinen gewählten
     Hintergrund eigene Animationen haben, die finde ich noch nicht.
     Beziehungsweise weiß ich auch nicht, wie ich den Hintergrund
     wieder ausschalten kann und dann auf den Standard zu wechseln.
     Das müsste auch noch da sein."

     Zwei Dinge fehlten also: fertige Hintergründe, und ein Weg zurück.
     Beides steckt jetzt in EINEM Fenster, in dem man sieht, was man
     bekommt — mit dem Standard als erstem Feld.

     Diese Hintergründe sind KEINE Bilder. Sie bestehen aus ein paar
     Formen und Bewegungen im Stylesheet. Das hat drei Vorteile, die
     alle zählen: sie kosten kein Byte Speicher, sie sind auf jedem
     Bildschirm scharf, und sie lassen sich später mit einem einzigen
     kurzen Wort an alle im Raum weitergeben — ein hochgeladenes Foto
     müsste man mit neunhunderttausend Zeichen verschicken.
     ================================================================= */
  const LC_HG_FERTIG = [
    { schl: "sterne",    was: "Sternenhimmel",    hinweis: "Funkelnde Sterne in der Nacht" },
    { schl: "funken",    was: "Glühwürmchen",     hinweis: "Warme Lichter in der Dämmerung" },
    { schl: "wellen",    was: "Weiche Wellen",    hinweis: "Langsam wanderndes Wasserlicht" },
    { schl: "nordlicht", was: "Nordlicht",        hinweis: "Grüne Schleier am Polarhimmel" },
    { schl: "bokeh",     was: "Lichterspiel",     hinweis: "Treibende, unscharfe Lichtpunkte" },
    { schl: "tafel",     was: "Schultafel",       hinweis: "Grüne Tafel mit Kreidestaub" },
  ];
  function lcHgIstFertig(wert) { return String(wert || "").indexOf("animiert:") === 0; }
  function lcHgFertigName(wert) { return String(wert || "").slice("animiert:".length); }

  /* Das Fenster, in dem man den Hintergrund aussucht. Der Standard steht
     an erster Stelle — „ich weiß auch nicht, wie ich den Hintergrund
     wieder ausschalten kann". Er ist jetzt nicht versteckt, sondern das
     erste, was man sieht. */
  function lcHintergrundFenster() {
    document.getElementById("lcHgWaehler")?.remove();
    const jetzt = lcHintergrundBild();
    const kasten = document.createElement("div");
    kasten.id = "lcHgWaehler";
    kasten.className = "lc-waehler-hinter";
    const feld = (schl, titel, hinweis, aktiv, inhalt) => `
      <button type="button" class="lc-hgfeld${aktiv ? " ist-an" : ""}" data-lc-hg="${escapeHtml(schl)}">
        <span class="lc-hgfeld-bild" data-hg="${escapeHtml(schl)}" aria-hidden="true">${inhalt || ""}</span>
        <span class="lc-hgfeld-wort">${escapeHtml(titel)}</span>
        <span class="lc-hgfeld-klein">${escapeHtml(hinweis)}</span>
      </button>`;
    kasten.innerHTML = `
      <div class="lc-waehler" role="dialog" aria-modal="true" aria-label="Hintergrund im Chat">
        <p class="eyebrow">DER HINTERGRUND IM CHAT</p>
        <p class="empty-note" style="margin:0 0 12px; font-size:0.76rem;">
          Such dir einen aus. Das erste Feld ist der Standard — damit ist jeder
          eigene Hintergrund wieder weg.
        </p>
        <div class="lc-hgfelder">
          ${feld("", "Standard", "Die Gesichter aus dem Raum treiben leise", !jetzt, "")}
          ${LC_HG_FERTIG.map((h) => feld("animiert:" + h.schl, h.was, h.hinweis,
              jetzt === "animiert:" + h.schl, "")).join("")}
          ${feld("eigenes", "Eigenes Bild", "Ein Foto vom Gerät hinterlegen",
              Boolean(jetzt) && !lcHgIstFertig(jetzt),
              jetzt && !lcHgIstFertig(jetzt)
                ? `<img src="${escapeHtml(jetzt)}" alt="" class="lc-hgfeld-foto">` : "➕")}
        </div>
        <div class="lc-waehler-reihe" style="margin-top:14px;">
          <button type="button" class="btn btn-coffee" id="lcHgZu">Fertig</button>
        </div>
      </div>`;
    document.body.appendChild(kasten);
    const zu = () => kasten.remove();
    kasten.addEventListener("click", (e) => { if (e.target === kasten) zu(); });
    kasten.querySelector("#lcHgZu")?.addEventListener("click", zu);
    kasten.querySelectorAll("[data-lc-hg]").forEach((b) =>
      b.addEventListener("click", () => {
        const wahl = b.dataset.lcHg;
        if (wahl === "eigenes") { zu(); lcHintergrundDateiWaehlen(); return; }
        lcHintergrundSetzen(wahl);
        showToast(wahl ? "🖼️ Hintergrund gesetzt." : "🖼️ Zurück auf den Standard.");
        zu();
      }));
  }

  /* EIN SCHMALES FENSTER FUER DIE PRUEFUNGEN.
     Alles in dieser Datei liegt in einer geschlossenen Funktion — das
     ist richtig so, sonst kann jedes Skript alles anfassen. Nur: was
     niemand von aussen aufrufen kann, kann auch kein Test messen, und
     dann bleibt mir nur zu BEHAUPTEN, dass etwas geht.

     Deshalb liegen hier genau die paar Sachen, die geprüft werden,
     und nichts weiter. Sie verändern nichts, sie öffnen nur, was ein
     Mensch mit einem Tipp auch öffnen würde. */
  window.DMA_PRUEF = Object.assign(window.DMA_PRUEF || {}, {
    /* GEFRAGT: „Hast du schon das bei der Online-Anzeige gemacht, dass
       wenn jemand sein Land angegeben hat, dort seine Flagge zu sehen
       ist — und auch, ob er gerade im Klassenzimmer ist?"
       Ja. Damit das nicht nur behauptet ist, lässt sich die Liste hier
       mit ausgedachten Leuten zeichnen und nachsehen. */
    /* GEMELDET: „Einige Animationen gehen noch nicht." Damit sich das
       nachsehen laesst und nicht geraten werden muss: jeden Effekt
       einzeln ausloesen und hinterher zaehlen, was im Dokument steht. */
    effektNamen: function () { return Object.keys(LC_EFFEKTE); },
    /* Die Aufgabentafel von Hand zeichnen — sonst muesste die Sonde
       den ganzen Raum aufbauen, nur um zu sehen, ob die Teile da sind. */
    aufgabeZeichnen: function () { return lcAufgabeZeichnen(); },
    /* Wo die Karte LIEGT (ohne Animation) und wo sie gerade GEZEICHNET
       wird — damit sich nachmessen laesst, dass die Buehne dem
       Wackeln nicht folgt. */
    kartenKasten: function () {
      const k = document.getElementById("livechatKarte")
             || document.getElementById("livechatArea");
      if (!k) return null;
      const g = k.getBoundingClientRect();
      return { layout: lcLayoutKasten(k),
               gemalt: { left: g.left, top: g.top, width: g.width, height: g.height } };
    },
    /* GEMELDET: „Einige Aufgaben gehen noch nicht, wie das
       Galgenmaennchen." Damit sich das Ergebnis nachspielen laesst
       und nicht behauptet werden muss: eine Lueckentext-Aufgabe
       aufbauen und danach im Dokument nachsehen, ob die Kaesten
       wirklich da sind und ob das Eintragen bewertet wird. */
    galgenAufgabe: function () {
      Quiz.startSession(["lueckentext"], "leicht", null, "mix", null, "");
      renderQuestion();
      /* Nicht jede Lueckentext-Aufgabe taugt dafuer: „zu", „-" oder
         ein Wort mit Bindestrich bleiben beim Anklicken, und das ist
         richtig so. Die Sonde soll trotzdem nicht am Zufall haengen —
         hier wird deshalb so lange weitergeblaettert, bis eine
         Aufgabe kommt, die Kaesten baut. */
      let versuche = 0;
      while (!document.querySelector(".galgen") && versuche < 40) {
        versuche++;
        if (!Quiz.advance()) break;
        renderQuestion();
      }
      const g = document.querySelector(".galgen");
      return g ? { wort: g.dataset.wort,
                   felder: g.querySelectorAll(".galgen-feld").length,
                   fest: g.querySelectorAll(".galgen-fest").length,
                   tasten: g.querySelectorAll(".galgen-taste").length } : null;
    },
    /* Die beiden Bildfaecher — damit sich nachsehen laesst, ob die
       GIPHY-Bibliothek wirklich gefuellt aufgeht und nachlaedt. */
    haeufigHtml: function () { return lcHaeufigHtml(); },
    /* Die GIPHY-Merkzettel — damit sich nachsehen laesst, dass
       Favoriten und Suchen wirklich im Profil landen. */
    gif: {
      favoriten: () => lcGifFavoriten(),
      umschalten: (u) => lcGifFavoritUmschalten(u),
      genommen: (u) => lcGifGenommen(u),
      suchen: () => lcGifSuchen(),
      sucheMerken: (w) => lcGifSucheMerken(w),
      leeren: () => {
        kzEinstellungSetzen("gifFavoriten", []);
        kzEinstellungSetzen("gifZaehler", {});
        kzEinstellungSetzen("gifSuchen", []);
      }
    },
    tonSchluessel: function () { return LC_TON_SCHLUESSEL; },
    bildWaehler: function () { return livechatBildWaehler(); },
    sendeWaehler: function () { return livechatSendeWaehler(); },
    /* Eine BÜHNE für die Prüfung: ohne Chatverlauf und ohne Plätze
       zeichnen die kleinen Effekte gar nichts — nicht weil sie kaputt
       sind, sondern weil sie sich an die Zeile und an den Platz
       hängen. Genau das hat mich zweimal in die Irre geführt: neun
       Effekte sahen „leer" aus, obwohl sie im echten Chat laufen.
       Wer prüfen will, ob ein Effekt wirkt, muss ihm die Umgebung
       geben, die er im Betrieb hat. */
    /* Die Wegsuche einzeln nachrechenbar — sonst laesst sich „nur
       ueber freie Plaetze" nur am Ergebnis erahnen. Gibt die
       Platznummern des Weges zurueck oder null. */
    wegPruefen: function (vonNr, zuNr, ueberBesetzte) {
      const weg = lcWegSuchen(lcPlatzGitter(), vonNr, zuNr, Boolean(ueberBesetzte));
      return weg ? weg.map((p) => p.nr) : null;
    },
    effektBuehne: function () {
      document.getElementById("lcPruefBuehne")?.remove();
      const b = document.createElement("div");
      b.id = "lcPruefBuehne";
      b.innerHTML = `
        <div class="question-card livechat" id="livechatKarte">
          <div class="lc-plaetze" id="lcPlaetze">
            <!-- FUENF PLAETZE STATT ZWEI, UND EINER BIN ICH.
                 Zwei Plaetze haben gereicht, solange jede Animation nur
                 am Ziel haengt. Angel, Lasso, Fahren und Spielzug gehen
                 aber VON MEINEM PLATZ AUS — ohne einen Platz mit der
                 Klasse „lc-platz-ich" finden sie gar keinen Anfang und
                 zeichnen nichts. Und „egal wo er unten sitzt" laesst
                 sich mit zwei Plaetzen nebeneinander nicht pruefen. -->
            <!-- RUNDE 79 — DAS SCHILD FEHLTE HIER, UND DAS WAR EINE LUECKE.
                 XANDER hat rund zwanzigmal gemeldet, dass Animationen „die
                 Strichlinie und die Platznummer" mitnehmen. Keine Sonde
                 konnte das je finden: in dieser Buehne gab es weder ein
                 „lc-schild" noch eine „lc-nummer", und ohne die Klasse
                 „lc-platz-belegt" greift auch keine einzige Regel, die
                 sich auf einen besetzten Platz bezieht.
                 Eine Pruefbuehne, die anders aussieht als der echte Raum,
                 prueft den echten Raum nicht. Deshalb steht hier jetzt
                 dieselbe Auszeichnung wie in renderLiveChat. -->
            <button class="lc-platz lc-platz-ich lc-platz-belegt" data-lc-platz="1"><span class="lc-kreis"></span><span class="lc-schild" aria-hidden="true"><span class="lc-nummer">1</span></span><span class="lc-platz-name">Alex</span></button>
            <button class="lc-platz lc-platz-belegt" data-lc-platz="2"><span class="lc-kreis"></span><span class="lc-schild" aria-hidden="true"><span class="lc-nummer">2</span></span><span class="lc-platz-name">Bea</span></button>
            <button class="lc-platz lc-platz-belegt" data-lc-platz="3"><span class="lc-kreis"></span><span class="lc-schild" aria-hidden="true"><span class="lc-nummer">3</span></span><span class="lc-platz-name">Cem</span></button>
            <button class="lc-platz lc-platz-belegt" data-lc-platz="4"><span class="lc-kreis"></span><span class="lc-schild" aria-hidden="true"><span class="lc-nummer">4</span></span><span class="lc-platz-name">Dana</span></button>
            <button class="lc-platz lc-platz-belegt" data-lc-platz="5"><span class="lc-kreis"></span><span class="lc-schild" aria-hidden="true"><span class="lc-nummer">5</span></span><span class="lc-platz-name">Emmi</span></button>
            <!-- RUNDE 80 — DREI FREIE PLAETZE, UND DAS WAR DIE NAECHSTE LUECKE.
                 Jede REISE (Schiff, Lok, Flugzeug, Sprungfeder, Kran,
                 Beamen, Roehre, Maulwurf, Helikopter, UFO, Pferd …)
                 bricht sofort ab, wenn das Ziel nicht frei ist. In
                 dieser Buehne waren alle fuenf Plaetze belegt — also
                 konnte keine einzige Sonde je eine Reise sehen.
                 Genau deshalb blieb der Rueckstand am Startplatz so
                 lange unentdeckt, den Xander rund ein Dutzend Mal
                 gemeldet hat („immer wenn man landet, ist das
                 Profilbild kurz noch mal auf der Seite zu sehen, von
                 der aus man startet").
                 Ein freier Platz sieht im echten Raum so aus: die
                 Klasse „lc-platz-frei" und keine Namenszeile. -->
            <button class="lc-platz lc-platz-frei" data-lc-platz="6"><span class="lc-kreis"></span><span class="lc-schild" aria-hidden="true"><span class="lc-nummer">6</span></span><span class="lc-platz-name"></span></button>
            <button class="lc-platz lc-platz-frei" data-lc-platz="7"><span class="lc-kreis"></span><span class="lc-schild" aria-hidden="true"><span class="lc-nummer">7</span></span><span class="lc-platz-name"></span></button>
            <button class="lc-platz lc-platz-frei" data-lc-platz="8"><span class="lc-kreis"></span><span class="lc-schild" aria-hidden="true"><span class="lc-nummer">8</span></span><span class="lc-platz-name"></span></button>
          </div>
          <div class="lc-chat-verlauf" id="lcVerlauf" style="height:220px; overflow:auto;">
            <p class="lc-zeile" id="lcPruefZeile">Alex drückt Emmi</p>
          </div>
        </div>`;
      document.body.appendChild(b);
      /* UND SIE MUSS AUCH ZU SEHEN SEIN.
         Gemessen wird in pruefe-platzmenue, wie viel Prozent einer
         Animation sichtbar bleiben — da zaehlt das Fenster als letzte
         Blende mit. Seit die Buehne fuenf Plaetze hat, ist sie hoeher
         und rutschte unter den unteren Fensterrand; gemeldet wurden
         dann „0 % sichtbar (letzte Blende: HTML)" fuer Hammer, Wecker
         und Wolke — sie waren gezeichnet, nur eben ausserhalb des
         Bildschirms. Deshalb: Luft nach oben und unten (ein Hammer
         kommt von ausserhalb des Bildes) und in die Mitte rollen. */
      b.style.padding = "160px 0";
      /* „instant" ist Absicht: html traegt scroll-behavior: smooth,
         und ein weiches Rollen feuert eine Dreiviertelsekunde lang
         scroll-Ereignisse. Die machen jedes Menue wieder zu, das in
         dieser Zeit aufgeht — das hat die Sonde pruefe-wagenheber
         gemessen: das Umsetz-Menue ging auf und war sofort weg. */
      try { b.scrollIntoView({ block: "center", behavior: "instant" }); }
      catch (e) { try { b.scrollIntoView(); } catch (x) {} }
      return true;
    },
    effekt: function (name, wen, zusatz) {
      /* NACHGEBESSERT, weil die Messung selbst zweimal gelogen hat:
         1. Die Umarmung, das Lecken und das Boxen haengen sich mit
            einer Verzoegerung an die Plaetze — wer sofort nachsieht,
            findet nichts und haelt sie fuer kaputt.
         2. Gezaehlt wurde nur das ZULETZT angehaengte Element. Beim
            Regen ist das der Blitz mit zwei Teilen, waehrend der
            Regenvorhang mit 170 Tropfen daneben haengt.
         3. Erdbeben und Falten legen gar nichts an, sie setzen eine
            KLASSE. Auch das ist eine Wirkung.
         Deshalb merkt sich effekt() nur den Ausgangszustand; gemessen
         wird in effektNachher(), nach einer Wartezeit. */
      const karte = document.getElementById("livechatKarte");
      window.__effektStand = {
        name: name,
        koerper: document.body.childElementCount,
        imChat: karte ? karte.querySelectorAll("*").length : 0,
        klassen: document.body.className + "|" + (karte ? karte.className : "")
      };
      const zeile = document.getElementById("lcPruefZeile");
      /* „zusatz" kam in Runde 29 dazu: das Billard braucht das Los,
         das mit der Nachricht mitfaehrt, sonst laesst sich gar nicht
         messen, ob zwei Geraete denselben verschwinden lassen. */
      const botschaft = wen ? { wen: wen } : {};
      if (zusatz && typeof zusatz === "object") {
        Object.keys(zusatz).forEach((k) => { botschaft[k] = zusatz[k]; });
      }
      try { lcWirkung(name, zeile || null, botschaft); }
      catch (e) { return { name, fehler: String(e && e.message || e) }; }
      return { name };
    },
    effektNachher: function () {
      const v = window.__effektStand || {};
      const karte = document.getElementById("livechatKarte");
      const neu = [...document.body.children].filter(
        (el) => /(^|\s)lc-/.test(el.className || ""));
      let teile = 0, klasse = "";
      neu.forEach((el) => {
        const t = el.querySelectorAll("*").length;
        if (t >= teile) { teile = t; klasse = String(el.className); }
      });
      const jetztKlassen = document.body.className + "|" + (karte ? karte.className : "");
      return {
        name: v.name,
        angelegt: document.body.childElementCount - (v.koerper || 0),
        imChat: (karte ? karte.querySelectorAll("*").length : 0) - (v.imChat || 0),
        klassenNeu: jetztKlassen !== v.klassen,
        teile: teile,
        klasse: klasse
      };
    },
    /* Die eigene Stimme: Name aus dem Wort, Liste nachladen, abspielen. */
    tonStamm: function (w) { return aussprTonStamm(aussprSprechtext(w)); },
    tonLaden: function () { return aussprTonLaden(); },
    tonWeg: function (w) { return aussprTonWeg(w); },
    tonSpielen: async function (w) {
      await aussprTonLaden();
      const weg = aussprTonWeg(w);
      return weg ? aussprTonSpielen(weg, 1) : false;
    },
    /* Ein einzelnes Bilderrätsel-Bild, an einem bestimmten Platz, mit
       fester Figur — damit sich nachsehen lässt, OB die Figur wirklich
       dort steht, wo der Satz behauptet. */
    brBild: async function (platzId) {
      const z = await brNeueAufgabe(platzId);
      if (!z) return null;
      return { html: brBildHtml(z), satz: brRichtigerSatz(z), platz: z.platz };
    },
    brPlaetze: function () { return (window.DMA_PLAETZE || []).map((p) => p.id); },
    /* Nur die Plätze, die das Spiel wirklich benutzt. */
    brSpielPlaetze: function () { return brPlaetze().map((p) => p.id); },
    /* Die Einladungsliste eines noch nicht freigegebenen Spiels —
       mit ausgedachten Leuten, damit sich das Auf- und Zuklappen und
       die Zählung ohne echte Konten nachprüfen lassen. */
    betaEinladung: function (flagKey, spielName, leute) {
      document.getElementById("pruefBetaEinladung")?.remove();
      const d = document.createElement("div");
      d.id = "pruefBetaEinladung";
      d.innerHTML = betaSpielEinladungHtml(flagKey, spielName || "Blitzrunde");
      document.body.appendChild(d);
      betaSpielEinladungBinden(d.querySelector(".beta-spiel-einladung"),
        flagKey, spielName || "Blitzrunde", async (wort) => {
          const alle = leute || [];
          if (!wort) return alle;
          const w = String(wort).toLowerCase();
          return alle.filter((u) => String(u.name || "").toLowerCase().includes(w));
        });
      return true;
    },
    onlineKlappe: function (leute, imKlassenzimmerIds) {
      if (!document.getElementById("onlineJetztBtn")) {
        const b = document.createElement("button");
        b.id = "onlineJetztBtn";
        document.body.appendChild(b);
      }
      onlineListe = leute || [];
      kzDaJetzt = {};
      (imKlassenzimmerIds || []).forEach((id) => { kzDaJetzt[id] = { name: id }; });
      onlineKlappeZeichnen();
      const k = document.getElementById("onlineKlappe");
      return k ? k.innerHTML : "";
    },
    hintergrundFenster: function () { return lcHintergrundFenster(); },
    hintergrundWert: function () { return lcHintergrundBild(); },
    platzZiel: function () { return lcPlatzZiel(); },
    raumFenster: function () { return livechatRaumFenster(); },
    /* Zwei Aufnahmen der Anwesenheit hineingeben, die Meldungen
       herausbekommen — genau das, was das Laufband tut. */
    kzEreignisse: function (aufnahme) { kzEreignisseAbleiten(aufnahme); return kzEreignisText(); },
    kzZeile: function () { return kzTickerHtml(); },
    tor: function (raum, weiter) { return livechatTor(raum, weiter || function () {}); },
    orkan: function () { return lcOrkan(); },
    bonbon: function (sorte, farbe) { return lcBonbonSvg(sorte, farbe); },
    auto: function () { return lcRennautoSvg(); },
    umarmung: function (wen) { return lcUmarmung(wen); },
    lecken: function (wen) { return lcLecken(wen); },
    boxen: function (wen, von) { return lcBoxen(wen, von); },
    ausspracheListe: function () { return buildDictionaryEntries().filter(wortZumUeben).filter(aussprUebbar); },
    ausspracheAlle: function () { return buildDictionaryEntries(); },
    geruest: function () { return livechatGeruestHtml(); },
    wolken: function (n) { return wWolkenbaender(n || 3); },
    wolkenLeben: function () { return wWolkenLeben(); },
    /* Worauf beruht die Himmelsfarbe gerade? Hoehe der Sonne in Grad
       und die daraus gemischte Farbe. */
    himmel: function (datum) {
      const ort = ortFuerLernraum();
      const h = sonnenHoehe(datum ? new Date(datum) : new Date(), ort.breite, ort.laenge);
      return Object.assign({ hoehe: Number(h.toFixed(2)), ort: ort.name }, himmelAusSonne(h));
    },
  });

  /* Der Befehl /hintergrund meldet sich hier — die Oberfläche hat den
     Dateiwähler, livechat.js nicht. */
  let lcHintergrundFeld = null;
  function lcHintergrundWaehlen(weg) {
    if (weg) { lcHintergrundSetzen(""); showToast("🖼️ Zurück auf den Standard."); return; }
    /* Ohne ausdrückliches „weg" wird nicht mehr sofort der Dateiwähler
       aufgerissen, sondern erst gefragt — sonst gab es gar keinen Weg
       zu einem fertigen Hintergrund oder zurück zum Standard. */
    lcHintergrundFenster();
  }
  function lcHintergrundDateiWaehlen() {
    if (!lcHintergrundFeld) {
      lcHintergrundFeld = document.createElement("input");
      lcHintergrundFeld.type = "file";
      lcHintergrundFeld.accept = "image/*";
      lcHintergrundFeld.style.display = "none";
      document.body.appendChild(lcHintergrundFeld);
      lcHintergrundFeld.addEventListener("change", async () => {
        const datei = lcHintergrundFeld.files && lcHintergrundFeld.files[0];
        lcHintergrundFeld.value = "";
        if (!datei) return;
        try {
          /* Kräftig verkleinern: ein Hintergrund darf unscharf sein,
             er liegt ohnehin hinter Text und ist stark abgedunkelt.
             Sein Höchstmass ist eigens grösser als das eines Fotos im
             Chat — genau daran ist es vorher gescheitert. */
          /* 760 Pixel und höchstens 140 000 Zeichen — nicht aus
             Sparsamkeit, sondern weil der Hintergrund jetzt an ALLE im
             Raum geht und ein Rundruf eine Obergrenze hat. Er liegt
             ohnehin weichgezeichnet und halb durchsichtig hinter Text;
             an dieser Stelle sieht man den Unterschied nicht, am
             Ankommen dagegen schon. */
          const daten = await LiveChat.bildVerkleinern(datei, 760, 140000);
          if (lcHintergrundSetzen(daten)) showToast("🖼️ Hintergrund gesetzt — alle im Raum sehen ihn.");
        } catch (x) {
          showToast("🖼️ " + (x && x.message ? x.message : "Das Bild ging nicht."));
        }
      });
    }
    lcHintergrundFeld.click();
  }

  function livechatHintergrundAuffrischen(l) {
    const v = document.getElementById("lcVerlauf");
    if (!v) return;
    if (lcHgGemerkt === null) lcHintergrundHolen();   // einmal aus dem Lager

    /* Ein eigenes Bild schlägt alles andere. Es haengt NICHT nur am
       Verlauf, sondern auch an der ganzen Karte — „der soll sich
       hinter dem Chat und hinter allen Elementen aufziehen, also
       komplett durch das ganze Klassenzimmer". */
    const gewaehlt = lcHintergrundBild();
    const fertig = lcHgIstFertig(gewaehlt);
    const eigenes = fertig ? "" : gewaehlt;
    const karte = document.getElementById("livechatKarte");
    [v, karte].forEach((el) => {
      if (!el) return;
      el.classList.toggle("hat-eigenes-bild", Boolean(eigenes));
      /* Ein fertiger Hintergrund ist kein Bild, sondern ein Name. Er
         steht als data-hg am Element, und das Stylesheet malt ihn —
         siehe LC_HG_FERTIG und den Abschnitt „FERTIGE HINTERGRÜNDE"
         in korrekturen.css. */
      el.classList.toggle("hat-fertigen-hg", fertig);
      if (fertig) el.dataset.hg = lcHgFertigName(gewaehlt);
      else delete el.dataset.hg;
      if (eigenes) el.style.setProperty("--lc-hg-bild", 'url("' + eigenes + '")');
      else el.style.removeProperty("--lc-hg-bild");
    });

    let schicht = v.querySelector(".lc-chat-hg");
    if (!schicht) {
      schicht = document.createElement("div");
      schicht.className = "lc-chat-hg";
      schicht.setAttribute("aria-hidden", "true");
      v.insertBefore(schicht, v.firstChild);
    }
    /* Die Gesichter im Raum — nur die, die wirklich ein Bild haben. */
    const bilder = l.plaetze
      .filter((p) => !p.leer && p.bild)
      .map((p) => lcBildQuelle(p.bild))
      .filter((q) => q && q.indexOf("emoji:") !== 0);
    const marke = bilder.join("|");
    if (schicht.dataset.marke === marke) return;
    schicht.dataset.marke = marke;
    schicht.innerHTML = "";
    bilder.slice(0, 8).forEach((q, i) => {
      const b = document.createElement("img");
      b.src = q;
      b.alt = "";
      b.loading = "lazy";
      b.className = "lc-hg-bild";
      b.style.left = (6 + (i * 13) % 82) + "%";
      b.style.top = (8 + (i * 29) % 74) + "%";
      b.style.animationDelay = (i * 1.7).toFixed(1) + "s";
      b.style.animationDuration = (22 + (i % 4) * 6) + "s";
      schicht.appendChild(b);
    });
  }

  function livechatChatAuffrischen(l) {
    const v = document.getElementById("lcVerlauf");
    if (!v) return;
    /* Die gewählte Schrift (/schrift 1 … 4) hängt am Verlauf selbst —
       so gilt sie für alles darin, ohne dass jede Zeile sie mitträgt. */
    const schrift = l.schrift || (LiveChat.gemerkteSchrift ? LiveChat.gemerkteSchrift() : "1");
    if (v.dataset.schrift !== schrift) v.dataset.schrift = schrift;
    if (!l.nachrichten.length) {
      if (!v.querySelector(".lc-chat-leer")) {
        /* Die Hintergrundschicht bleibt stehen — sie ist keine Zeile. */
        v.querySelectorAll(".lc-zeile, .lc-chat-leer").forEach((x) => x.remove());
        v.insertAdjacentHTML("beforeend", `<p class="lc-chat-leer">Noch nichts geschrieben.<br>
          Schreib einfach unten los — alle im Raum lesen mit.<br>
          <span style="opacity:.7">Tippe <code>/h</code> für die alten Chatbefehle.</span></p>`);
      }
      return;
    }
    const leer = v.querySelector(".lc-chat-leer");
    if (leer) { leer.remove(); livechatGezeigt = new Map(); }

    /* GEWÜNSCHT: „Wenn jemand neu in den Chat kommt, dann darf er die
       Animationen, die vorher da waren, nicht komplett auslösen — das
       ist dann schon Vergangenheit. Er sieht sie nur, wenn er sie
       antippt."

       Alles, was VOR dem Betreten geschrieben wurde, gilt deshalb als
       Vergangenheit: kein Konfetti, keine Ballons, kein aufbauender
       Ruf. Die Zeile bekommt nur die Marke „lc-alt" — antippen spielt
       sie trotzdem ab, aber eben nur für einen selbst. */
    if (!livechatEffekteAb) livechatEffekteAb = Date.now();

    l.nachrichten.forEach((n) => {
      /* GEMELDET: „Jetzt bin ich in den anderen Raum gegangen und bin
         zurück ins Klassenzimmer und sehe bei vielen Nachrichten, die
         ich geschrieben habe, nur noch meinen Namen, aber nicht mehr
         die Nachricht."

         HIER LAG ES. Gemerkt wurde bisher nur die KENNUNG einer
         gezeichneten Zeile — wer einmal gezeichnet war, wurde nie
         wieder angefasst. Das ist richtig, solange sich eine Zeile
         nicht mehr ändert. Bilder ändern sich aber sehr wohl: sie
         liegen im Lager (IndexedDB) und werden NACHGEREICHT, weil das
         Betreten nicht auf die Datenbank warten soll. Beim Zeichnen
         ist bildImChat deshalb oft noch leer.

         Eine Bildnachricht OHNE Bildunterschrift bestand in diesem
         Augenblick aus nichts als dem Namen — und blieb es für immer,
         weil bilderNachreichen() zwar melden() ruft, die Zeile aber
         als „schon gezeichnet" galt. Genau das war zu sehen.

         Jetzt wird nicht die Kennung gemerkt, sondern eine MARKE aus
         allem, was man sieht. Ändert sie sich, wird die Zeile an Ort
         und Stelle ersetzt. */
      const marke = [n.text || "", n.art || "", n.name || "", n.farbe || "",
                     n.bildImChat ? "B" : (n.bildImLager ? "L" : (n.bildWeg ? "W" : "")),
                     n.bild || "", n.wirkung || "",
                     /* Ob die Zeile als Antwort gilt, gehoert mit in die
                        Marke — sonst bekaeme eine Zeile, die erst spaeter
                        als Antwort erkannt wird, nie ihren Knopf. */
                     n.versuch ? "A" : "",
                     /* OB ICH LEHRER BIN, GEHÖRT MIT IN DIE MARKE.
                        Das Profil steht beim Betreten oft noch nicht —
                        Backend lädt es nach. Wurde eine Zeile in genau
                        diesem Augenblick gezeichnet, fehlte ihr der
                        Notenknopf, und sie wurde NIE WIEDER angefasst:
                        eine Zeile wird nur neu gebaut, wenn sich ihre
                        Marke ändert. Genau das kann erklären, warum der
                        Knopf bei ihm ausblieb, obwohl im Prüfstand
                        alles stimmte. */
                     (() => { try { return LiveChat.binLehrer && LiveChat.binLehrer() ? "L" : ""; }
                              catch (e) { return ""; } })(),
                     /* Auch der nachtraeglich erkannte Bezug gehoert in
                        die Marke — sonst behielte eine Zeile ihr altes
                        Aussehen, obwohl gerade eine Aufgabe laeuft. */
                     (() => { try { return LiveChat.aufgabeBezug && LiveChat.aufgabeBezug(n) ? "B" : ""; }
                              catch (e) { return ""; } })()].join("\u0001");
      const schon = livechatGezeigt.get(n.id);
      if (schon === marke) return;
      livechatGezeigt.set(n.id, marke);
      const alteZeile = schon !== undefined
        ? v.querySelector('[data-lc-id="' + CSS.escape(String(n.id)) + '"]')
        : null;
      const art = n.art || "text";
      const z = document.createElement("div");
      z.className = "lc-zeile lc-zeile-" + art;
      z.dataset.lcId = String(n.id);

      /* ACHTUNG, und das ist kein Formalismus: Name und Text kommen
         von einem FREMDEN Gerät im Raum. Würden sie über innerHTML
         eingesetzt, könnte jeder, der den Raumlink hat, den anderen
         beliebiges HTML — und damit beliebiges Javascript — in die
         Seite schreiben. Darum wird Element für Element gebaut und
         der Text über textContent gesetzt. */
      const uhr = document.createElement("span");
      uhr.className = "lc-zeit";
      uhr.textContent = new Date(n.zeit).toLocaleTimeString("de-DE",
        { hour: "2-digit", minute: "2-digit" });
      z.appendChild(uhr);

      const farbe = lcNickFarbe(n);
      if (farbe && art === "ruf") z.style.setProperty("--lc-ruf", farbe);

      /* =============================================================
         DIE ZENSUR DIREKT AN DER NACHRICHT
         -------------------------------------------------------------
         GEWUENSCHT: „Die Note moechte ich direkt an der Nachricht
         geben koennen, und mit der Note, die ich gebe, bekommen die
         anderen diese Punkte gutgeschrieben."

         Also ein kleines Zeichen an jeder fremden Zeile — aber NUR,
         wenn man Lehrer ist. Wer keiner ist, sieht es gar nicht
         erst; ein Knopf, der einem beim Antippen sagt, dass man ihn
         nicht benutzen darf, ist ein schlechter Knopf.

         Ein Tipp klappt die sechs Zahlen auf. Daneben steht ein Feld
         fuer das Fach („Grammatik"), damit im Laufband auch steht,
         WOFUER es die Eins gab. */
      /* NUR AN EINER ANTWORT AUF EINE AUFGABE.
         GEWUENSCHT: „Bei normalen Nachrichten soll dieses Zensieren
         nicht dabeistehen. Das ist nur, wenn Aufgaben geloest werden,
         die ich schicke."
         Der Knopf hing bisher an JEDER fremden Zeile — also auch an
         „hallo" und „bis gleich". Ob eine Zeile eine Antwort ist,
         weiss livechat.js (aufgabeVersuch) und haengt es als Marke an
         die Nachricht; hier wird nur noch gefragt. */
      /* Ob eine Zeile eine Antwort auf die offene Aufgabe ist, wird
         NICHT nur beim Eintreffen entschieden (die Marke ueberlebt
         kein Neuladen), sondern hier noch einmal gefragt — siehe
         aufgabeBezug() in livechat.js. */
      let bezug = null;
      if (!n.versuch && n.von && !n.eigen) {
        try { bezug = LiveChat.aufgabeBezug ? LiveChat.aufgabeBezug(n) : null; } catch (e) { bezug = null; }
      }
      /* =============================================================
         DER KNOPF IST FÜR DEN LEHRER IMMER DA — PUNKT
         -------------------------------------------------------------
         GEMELDET, zum fünften Mal: „Die Benotung zeigt es immer noch
         nicht an, das Mädchen versucht es die ganze Zeit und ist schon
         am Verzweifeln. Mache es möglich, dass ich sie anklicken kann
         als Betreiber."

         Ich habe jetzt dreimal an der ERKENNUNG gebaut — erst die
         freie Aufgabe, dann die „erste Zeile", dann das Gerät. Jedes
         Mal war es richtig und jedes Mal hat es bei ihm trotzdem nicht
         gereicht, weil noch eine Bedingung dahinterlag. Solange der
         Knopf davon abhängt, ob die Seite eine Antwort ERKENNT, kann
         genau das wieder passieren.

         Also hängt er nicht mehr davon ab. Der Lehrer sieht ihn an
         JEDER fremden Chatzeile. Ob eine Zeile zu einer Aufgabe
         gehört, entscheidet nur noch, WIE er aussieht:
           * gehört sie dazu → kräftig, und im Titel steht die Frage
           * gehört sie nicht dazu → blass, bis man mit der Maus
             darüber geht

         Sein früherer Einwand („ich möchte diese Benotung nicht global
         haben") bleibt gewahrt: Es sieht ihn weiterhin AUSSCHLIESSLICH
         der Lehrer, an eigenen Zeilen steht er nicht, und was zur
         Aufgabe gehört, ist auf einen Blick zu unterscheiden. Was
         wegfällt, ist nur die Möglichkeit, dass er gar nicht da ist.
         ============================================================= */
      const gehoertZurAufgabe = Boolean(n.versuch || (bezug && bezug.versuch));
      /* HIER STAND EIN KNOPF „✍️ Darauf antworten" — UND ER HAT ZWEI
         DINGE KAPUTT GEMACHT.

         GEMELDET: „Das ,Darauf antworten' soll dort nicht stehen. Es
         soll logisch sein in dem Moment, wo man das abschickt — das
         musst du in der Klasse regeln und nicht die Leute auf den
         Knopf drücken lassen."
         Und: „Jetzt steht die Frage untereinander unter der Uhrzeit,
         du hast alles total zerstört. Die Frage soll so sein, wie sie
         vorher war — rechts neben der Uhrzeit."

         Beides stimmt, und das Zweite ist mein alter Fehler, zum
         dritten Mal: Eine Chatzeile ist ein GITTER mit drei Spalten
         (Uhrzeit | Name | Inhalt). Ihre Kinder werden der Reihe nach
         hineingesetzt. Mein Knopf war ein VIERTES Kind — und landete
         damit zwangsläufig in einer neuen Gitterzeile, unter der
         Uhrzeit. Genau das hat er gesehen. (Dasselbe ist mir beim
         Notenknopf schon zweimal passiert; der steht deshalb absolut
         positioniert und nicht im Gitter.)

         Der Knopf ist weg, und zwar ersatzlos: Die Zuordnung sitzt
         jetzt dort, wo sie hingehört — im Abschicken selbst (siehe
         schreiben() in livechat.js). Wer bei offener Aufgabe etwas
         abschickt, antwortet damit auf sie; die Nachricht trägt die
         Kennung der Aufgabe mit sich. Niemand muss etwas anklicken,
         beliebig viele können antworten, und die Aufgabenzeile sieht
         wieder aus wie jede andere. */
      const istAntwort = gehoertZurAufgabe;
      const antwortRichtig = Boolean(n.richtig || (bezug && bezug.richtig));
      const antwortFrage = n.aufgabeFrage || (bezug && bezug.frage) || "";
      /* Wofür wird hier benotet? Die Regel steht in livechat.js
         (KLASSE_JE_AUFGABE) — ein Satzpuzzle ist Satzbau, ein
         Wortpuzzle Rechtschreibung. Bei einer Aufgabe in eigenen
         Worten schlägt die Seite nichts vor; das weiss nur er. */
      const antwortKlasse = (bezug && bezug.klasse)
        || (() => { try { const a = LiveChat.offeneAufgabeInfo && LiveChat.offeneAufgabeInfo();
                          return (a && a.klasse) || ""; } catch (e) { return ""; } })();
      const antwortSpaet = Boolean(bezug && bezug.spaet);
      /* ZURÜCKGENOMMEN, und zwar auf seinen Einspruch hin:
         „Jetzt steht die Note überall, das soll nicht so sein. Du
         sollst nicht Trick 17 machen und einfach überall eine Benotung
         dranmachen — es soll die Benotung für die Aufgabe sein, es
         soll dazugehören, und das soll das System verstehen."

         Er hat recht. Überall einen Knopf hinzusetzen hat die Frage
         nicht gelöst, sondern übergangen. Der Knopf steht deshalb
         wieder NUR an einer Antwort — nur weiss die Seite jetzt
         wirklich, welche das ist, statt es zu raten: Die Antwort
         trägt die Kennung ihrer Aufgabe selbst mit sich (siehe
         „Darauf antworten"). */
      const darfBenoten = Boolean(gehoertZurAufgabe && n.von && !n.eigen
        && LiveChat.binLehrer && LiveChat.binLehrer());
      if (darfBenoten) {
        const stift = document.createElement("button");
        stift.type = "button";
        stift.className = "lc-benoten";
        /* GEMELDET: „Ich habe so einen kleinen Notizblock, ich weiss
           nicht, was du damit meinst — soll das ein Zeugnis
           darstellen? Ist das ueberhaupt die Mitschrift?"
           Nein, und das war mein Fehler: ein Klemmbrett sieht aus wie
           ein Notizblock, und niemand raet, dass dahinter die Zensur
           steckt. Jetzt steht es einfach da. */
        stift.title = "Note geben (1 bis 6) für die Antwort auf die Aufgabe"
          + (antwortFrage ? " „" + antwortFrage + "“" : "")
          + (antwortSpaet ? " (nachgereicht)" : "")
          + " — nur du als Lehrer siehst diesen Knopf";
        if (antwortSpaet) stift.classList.add("lc-benoten-spaet");
        stift.setAttribute("aria-label", "Note geben");
        stift.textContent = "Note";
        stift.addEventListener("click", (e) => {
          e.stopPropagation();
          const offen = z.querySelector(".lc-notenwahl");
          if (offen) { offen.remove(); return; }
          document.querySelectorAll(".lc-notenwahl").forEach((x) => x.remove());
          const wahl = document.createElement("span");
          wahl.className = "lc-notenwahl";
          /* =====================================================
             WOFÜR DIE NOTE? ERST DIE KLASSE, DANN DIE ZAHL
             -----------------------------------------------------
             GEWÜNSCHT: „Leg gleich auch einmal eine Klasse fest für
             diese Art von Spiel … dann gib als Vorauswahl mal, für
             was ich die Note gebe. Ist das Satzbau oder ist das
             Grammatik?"

             Es heisst Satzbau — Wortstellung, ein Teil der Syntax.
             „Grammatik" wäre nicht falsch, aber zu grob; darunter
             fallen auch Fälle, Zeiten und Endungen. Eine Note soll
             ja sagen, WORIN jemand gut war.

             Vorher stand hier ein leeres Textfeld „Fach, z. B.
             Grammatik". Ein leeres Feld füllt im Unterricht
             niemand aus — deshalb jetzt Knöpfe, mit der passenden
             Klasse schon angewählt. Tippen geht weiterhin, für
             alles, was nicht in der Liste steht.
             ===================================================== */
          const klassen = (window.LiveChat && LiveChat.notenKlassen)
            ? LiveChat.notenKlassen() : [];
          let gewaehlt = antwortKlasse;
          const fach = document.createElement("input");
          fach.type = "text";
          fach.className = "lc-notenfach";
          fach.placeholder = "oder selbst schreiben";
          fach.maxLength = 30;
          fach.value = gewaehlt;
          if (klassen.length) {
            const reihe = document.createElement("span");
            reihe.className = "lc-notenklassen";
            klassen.forEach((k) => {
              const b = document.createElement("button");
              b.type = "button";
              b.className = "lc-notenklasse";
              b.textContent = k.wert;
              b.title = k.was;
              if (k.wert === gewaehlt) b.classList.add("lc-notenklasse-an");
              b.addEventListener("click", (ev) => {
                ev.stopPropagation();
                /* Noch einmal antippen nimmt die Klasse wieder weg —
                   man soll auch ohne Zuordnung benoten können. */
                gewaehlt = (gewaehlt === k.wert) ? "" : k.wert;
                fach.value = gewaehlt;
                reihe.querySelectorAll(".lc-notenklasse").forEach((x) =>
                  x.classList.toggle("lc-notenklasse-an", x.textContent === gewaehlt));
              });
              reihe.appendChild(b);
            });
            wahl.appendChild(reihe);
          }
          wahl.appendChild(fach);
          [1, 2, 3, 4, 5, 6].forEach((zahl) => {
            const b = document.createElement("button");
            b.type = "button";
            b.className = "lc-notenzahl lc-note-" + zahl;
            b.textContent = String(zahl);
            b.addEventListener("click", (ev) => {
              ev.stopPropagation();
              const erg = LiveChat.noteGeben(n.von, zahl, fach.value.trim());
              wahl.remove();
              if (erg && erg.ok) {
                showToast("📋 " + erg.name + " bekommt eine " + zahl
                  + (erg.punkte ? " — " + erg.punkte + " Punkte gutgeschrieben." : "."));
              }
            });
            wahl.appendChild(b);
          });
          z.appendChild(wahl);
          fach.focus();
        });
        /* WARUM DAS ZWEIMAL SCHIEFGING — beide Male dieselbe Ursache,
           und die habe ich beim ersten Mal falsch geraten.

           Eine Chatzeile ist ein GITTER mit drei Spalten:
               grid-template-columns: 2.6em auto 1fr
           also Uhrzeit | Name | Inhalt. Ihre Kinder werden der Reihe
           nach in diese Spalten gesetzt.

           Erster Versuch: float:right. In einem Gitter wirkt float
           GAR NICHT — der Knopf wurde also einfach das vierte Kind
           und landete in der naechsten Gitterzeile, Spalte 1. Das war
           das „unter der Uhr".

           Zweiter Versuch: als erstes Kind einhaengen, damit der
           Float traegt. Er trug immer noch nicht, und jetzt sass der
           Knopf in Spalte 1 — 2,6 Zeichen breit, daher „N o t e"
           untereinander. Alles andere rutschte eine Spalte weiter,
           bis der Text in einer neuen Gitterzeile in genau dieser
           schmalen Spalte landete: jedes Wort auf einer eigenen
           Zeile, links hinter der Uhrzeit. Genau so gemeldet.

           Die Loesung ist, den Knopf ganz aus dem Gitter zu nehmen:
           position:absolute. Dann bekommt er keine Spalte mehr,
           stoert keine Reihenfolge und sitzt schlicht oben rechts an
           der Zeile. Damit er keinen Text ueberdeckt, bekommt eine
           Zeile mit Knopf rechts etwas Polsterung — dafuer die
           Klasse. */
        z.classList.add("lc-hat-note");
        z.appendChild(stift);
      }
      /* Und die Zeile SIEHT auch aus wie eine Antwort:
         „Ja, derjenige hat die Aufgabe gerade aus dem Aufgabenmodul
         heraus geloest beziehungsweise falsch geloest." */
      if (istAntwort) {
        z.classList.add("lc-versuch", antwortRichtig ? "lc-versuch-gut" : "lc-versuch-offen");
        /* Eine Aufgabe in eigenen Worten hat keine Musterloesung —
           „noch nicht richtig" waere dort schlicht gelogen. */
        z.title = n.aufgabeFrei
          ? "Antwort auf die Aufgabe" + (antwortFrage ? ": " + antwortFrage : "")
          : antwortRichtig ? "Antwort auf die Aufgabe — richtig"
                           : "Antwort auf die Aufgabe — noch nicht richtig";
      }

      if (art === "system" || art === "einladung") {
        const t = document.createElement("span");
        t.className = "lc-zeilentext";
        t.textContent = n.text;
        z.appendChild(t);
        if (art === "einladung" && n.raum) {
          z.classList.add("lc-zeile-klickbar");
          z.addEventListener("click", () => {
            LiveChat.raumWechseln(n.raum, false);
            renderLiveChat();
          });
        }
      } else if (art === "aufgabe" && n.raten) {
        lcRatenTafel(n, z);
      } else if (art === "aufgabe" && n.betonung) {
        lcBetonungsTafel(n, z);
      } else if (art === "aufgabe" && Array.isArray(n.sortieren) && n.sortieren.length > 1) {
        lcSortierTafel(n, z);
      } else if (art === "lesen" && Array.isArray(n.leseZeilen) && n.leseZeilen.length) {
        lcLeseTafel(n, z);
      } else if (art === "aufgabe") {
        /* =========================================================
           DIE AUFGABE IM CHAT
           ---------------------------------------------------------
           GEWUENSCHT: „Dass die Leute das richtigstellen koennen,
           vielleicht sogar aus dem Satz heraus — dass sie ihn also
           einmal schreiben koennen, aber auch die Worte nacheinander
           anklicken koennen von der Satzverwurzelung, die ich
           geschrieben habe, um ihn im Chat richtigzustellen."

           Also beides: man kann tippen wie immer, ODER die Teile der
           Reihe nach antippen — jedes Antippen haengt das Teil an die
           Schreibzeile an. Beim Satz mit Leerzeichen dazwischen, beim
           Wort ohne; sonst baut man das Wort mit Luecken auf und die
           Antwort waere falsch, obwohl sie richtig gemeint war. */
        const t = document.createElement("span");
        t.className = "lc-zeilentext lc-aufgabe";
        const doppel = String(n.text || "").indexOf(":");
        const einleitung = doppel > 0 ? n.text.slice(0, doppel + 1) : "";
        const rest = doppel > 0 ? n.text.slice(doppel + 1) : String(n.text || "");
        if (einleitung) {
          const e = document.createElement("strong");
          e.textContent = einleitung;
          t.appendChild(e);
        }
        const teile = rest.split("·").map((x) => x.trim()).filter(Boolean);
        /* =========================================================
           EINE FREIE AUFGABE IST KEIN PUZZLE
           ---------------------------------------------------------
           GEMELDET: „Hast du auch das /aufgabe geloest? Also dass man
           da nicht einfach nur einen Satz schreibt und dieser Satz
           dann komplett anklickbar dasteht und eigentlich gar keine
           Aufgabenfunktion hat, weil man gar nicht weiss, warum man
           den anklickt und abschickt."

           GEFUNDEN, und es ist genau hier: der Aufgabentext wird an
           „·" in Teile zerlegt, und jedes Teil wird ein Knopf, der
           sich an die Schreibzeile anhaengt. Das ist richtig fuer ein
           WORTPUZZLE („Haus · ist · das") — aber eine freie Aufgabe
           („Schreib einen Satz mit weil") hat gar kein „·". Dann gibt
           es genau EIN Teil: den ganzen Satz. Und der stand als ein
           grosser Knopf da, der sich selbst in die Zeile schrieb.
           Man konnte also die Frage als Antwort abschicken — sinnlos,
           genau wie er sagt.

           Jetzt entscheidet die Zahl der Teile, was es ist:
             · zwei oder mehr → Puzzle wie bisher,
             · genau eins → eine FRAGE. Sie steht als Text da, nicht
               als Knopf, darunter steht, was zu tun ist, und ein
               Knopf setzt den Finger in die Schreibzeile. Und wer
               die Aufgabe gestellt hat, sieht daneben, wie er sie
               wieder beendet. */
        if (teile.length < 2) {
          const frage = document.createElement("span");
          frage.className = "lc-aufgabe-frage";
          frage.textContent = teile[0] || rest;
          t.appendChild(frage);

          const hinweis = document.createElement("span");
          hinweis.className = "lc-aufgabe-hinweis";
          hinweis.textContent = "Schreib deine Antwort unten in den Chat \u2014 "
            + "die Lehrkraft kann sie dann benoten.";
          t.appendChild(hinweis);

          const reihe = document.createElement("span");
          reihe.className = "lc-aufgabe-reihe";
          const los = document.createElement("button");
          los.type = "button";
          los.className = "lc-aufgabe-los";
          los.textContent = "\u270d\ufe0f Antworten";
          los.addEventListener("click", () => {
            const f = document.getElementById("lcFeld");
            if (!f) return;
            f.focus();
            try { f.scrollIntoView({ block: "center", behavior: "smooth" }); } catch (e) {}
          });
          reihe.appendChild(los);
          /* Nur wer die Aufgabe gestellt hat, kann sie beenden — und
             nur der sieht den Knopf. */
          if (n.eigen) {
            const schluss = document.createElement("button");
            schluss.type = "button";
            schluss.className = "lc-aufgabe-los lc-aufgabe-schluss";
            schluss.textContent = "\u2714\ufe0f Aufgabe beenden";
            schluss.addEventListener("click", () => {
              try { LiveChat.schreiben("/aufgabe"); } catch (e) {}
              showToast("\u2714\ufe0f Die Aufgabe ist beendet.");
            });
            reihe.appendChild(schluss);
          }
          t.appendChild(reihe);
          z.appendChild(t);
        } else {
        /* Ein Wortpuzzle besteht aus einzelnen Buchstaben — daran
           erkennt man es, ohne dass es extra mitgeschickt werden
           muss. */
        const ausBuchstaben = teile.length > 1 && teile.every((x) => Array.from(x).length === 1);
        const kasten = document.createElement("span");
        kasten.className = "lc-aufgabe-teile";
        teile.forEach((teil) => {
          const b = document.createElement("button");
          b.type = "button";
          b.className = "lc-aufgabe-teil";
          b.textContent = teil;
          b.title = "Antippen — hängt es an deine Zeile an";
          b.addEventListener("click", () => {
            const f = document.getElementById("lcFeld");
            if (!f) return;
            f.value = f.value + (f.value && !ausBuchstaben ? " " : "") + teil;
            const k = document.getElementById("lcSenden");
            if (k) k.disabled = !f.value.trim();
            b.classList.add("lc-aufgabe-genommen");
            f.focus();
          });
          kasten.appendChild(b);
        });
        t.appendChild(kasten);
        const weg = document.createElement("button");
        weg.type = "button";
        weg.className = "lc-aufgabe-weg";
        weg.textContent = "↺ Zeile leeren";
        weg.addEventListener("click", () => {
          const f = document.getElementById("lcFeld");
          if (f) { f.value = ""; f.focus(); }
          const k = document.getElementById("lcSenden");
          if (k) k.disabled = true;
          kasten.querySelectorAll(".lc-aufgabe-genommen")
                .forEach((x) => x.classList.remove("lc-aufgabe-genommen"));
        });
        t.appendChild(weg);
        z.appendChild(t);
        }
        /* DER LINK INS WOERTERBUCH — GANZ UNTEN, NICHT MITTENDRIN.
           GEWUENSCHT: „dass man im Chat sogar auf den Link im
           Woerterbuch zugreifen kann."
           Traegt die Aufgabe ein Wort (Artikelraten, gesuchter
           Begriff), steht darunter ein Knopf, der genau dieses Wort
           aufschlaegt. Er wird ZULETZT angehaengt — dazwischen saehe
           er aus wie eine Antwortkachel. */
        if (n.wortLink) {
          const nach = document.createElement("button");
          nach.type = "button";
          nach.className = "lc-aufgabe-nachschlagen";
          nach.textContent = "\ud83d\udcd6 " + n.wortLink + " im W\u00f6rterbuch";
          nach.title = "Aufschlagen \u2014 der Chat bleibt, wie er ist";
          nach.addEventListener("click", (e) => {
            e.stopPropagation();
            try { lcWortNachschlagen(n.wortLink); } catch (x) {}
          });
          t.appendChild(nach);
        }
      } else if (art === "note") {
        const t = document.createElement("span");
        /* NICHT „lc-note" — so heisst die fliegende Musiknote der
           Animation, und deren Regeln (opacity:0, position:absolute)
           haben die Zensur unsichtbar gemacht. */
        t.className = "lc-zeilentext lc-zensur";
        t.textContent = n.text;
        z.appendChild(t);
      } else if (art === "kommen") {
        const t = document.createElement("span");
        t.className = "lc-zeilentext";
        t.textContent = (n.kommt ? "\u2192 " : "\u2190 ") + n.text;
        z.appendChild(t);
      } else if (art === "emojibild") {
        /* Ein Bild aus Emojis. Es braucht KEINE Schreibmaschinenschrift
           — Emojis sind ohnehin alle gleich breit —, aber es braucht
           erhaltene Leerzeichen und eine enge Zeilenhöhe, sonst
           zerfällt die Anordnung. */
        const vor = document.createElement("pre");
        vor.className = "lc-emojibild";
        vor.textContent = n.text;
        z.appendChild(vor);
      } else if (art === "ascii") {
        /* Ein Bild aus Buchstaben. Es steht nur dann richtig da, wenn
           jedes Zeichen gleich breit ist und die Leerzeichen erhalten
           bleiben — dafür sorgen <pre> und die CSS-Klasse. Der Text
           kommt über textContent hinein, wie überall hier. */
        const vor = document.createElement("pre");
        vor.className = "lc-ascii";
        vor.textContent = n.text;
        if (farbe) vor.style.color = farbe;
        z.appendChild(vor);
      } else if (art === "aktion") {
        /* GEMELDET, zum dritten Mal — und diesmal steht genau da, was
           fehlte: „Sobald man den /me-Befehl benutzt, funktioniert
           dieses ‚Xander Fox:' nicht mehr … es muss wirklich beginnen
           mit ‚Wusstet ihr, dass …'."

           Also steht hier NICHTS mehr vor dem Satz: kein Name, kein
           Doppelpunkt — und auch kein Sternchen. Das Sternchen war der
           letzte Rest, der übrig war; es hat die Zeile immer noch mit
           einem Vorzeichen anfangen lassen, statt mit dem ersten Wort.
           Jetzt fängt die Zeile mit dem ersten Wort an. Zu erkennen ist
           sie an dem, was drinsteht: der Name, so kräftig gesetzt wie
           ein Nick, an der Stelle, an die man ihn geschoben hat. */
        const t = document.createElement("span");
        t.className = "lc-zeilentext";
        lcTextEinfaerben(t, n.text, n);
        if (farbe) t.style.color = farbe;
        z.appendChild(t);
      } else {
        /* Bild, Name, Text — in einer Zeile, für alle gleich. */
        const kopf = document.createElement("span");
        kopf.className = "lc-nick";
        const namensfarbe = lcNamensFarbe(n);
        if (namensfarbe) kopf.style.color = namensfarbe;
        else if (farbe) kopf.style.color = farbe;
        const emoji = n.bild && n.bild.indexOf("emoji:") === 0 ? n.bild.slice(6) : "";
        if (emoji) {
          const e = document.createElement("span");
          e.className = "lc-zeilenbild lc-zeilenbild-emoji";
          e.textContent = emoji;
          kopf.appendChild(e);
        } else if (n.bild) {
          const i = document.createElement("img");
          i.className = "lc-zeilenbild";
          i.alt = ""; i.loading = "lazy"; i.src = lcBildQuelle(n.bild);
          kopf.appendChild(i);
        }
        const nm = document.createElement("b");
        const nameText = art === "fluester" ? "\u00bb" + n.name + "\u00ab" : String(n.name || "");
        /* Bunt gilt fuer den Namen, wenn es FUER DEN NAMEN gesetzt
           wurde — und sonst weiter, wenn alles bunt ist. */
        if (n.farbeName === "bunt" || (!n.farbeName && n.farbe === "bunt")) {
          /* GEMELDET: „Wenn man die Farbe ändert bei bunt, dann soll der
             Name auch bunt sein." Vorher blieb er in seiner
             Zufallsfarbe stehen — nur die Zeile war bunt. */
          Array.from(nameText).forEach((z, i) => {
            const b = document.createElement("span");
            b.textContent = z;
            if (z.trim()) b.style.color = LC_REGENBOGEN[i % LC_REGENBOGEN.length];
            nm.appendChild(b);
          });
        } else {
          nm.textContent = nameText;
        }
        kopf.appendChild(nm);
        /* Der Name einer Fluesterzeile ist gleichzeitig der Weg
           zurueck — siehe lcZurueckfluestern(). */
        if (art === "fluester") {
          const wem = n.eigen ? (n.wen || "") : (n.name || "");
          if (wem) {
            nm.classList.add("lc-fluester-zurueck");
            nm.title = wem + " zur\u00fcckfl\u00fcstern";
            nm.dataset.lcFluester = wem;
          }
        }
        z.appendChild(kopf);

        const t = document.createElement("span");
        t.className = "lc-zeilentext";
        /* ---- Die Sprachnachricht ----
           GEWUENSCHT: „in dem Moment, wenn man sie schickt, werden sie
           hoerbar. Und wenn man sich spaeter noch mal anklickt und
           noch mal hoeren will, dann hoert man das als einzelner nur
           noch privat."

           Also: beim ERSTEN Zeichnen laeuft sie von selbst — genau
           wie ein Animationston. Danach steht sie als Knopf da. Ist
           sie vergangen (der Verlauf reicht sie nicht durch, das
           Geraet sichert sie nicht), sagt die Zeile das auch. */
        /* GEMELDET, und ich habe es nachgemessen — es stimmte:
           „Bei Personen steht der leere Name, wenn sie eine
           Sprachnachricht schicken", und: „Die Sprachnachrichten sind
           nicht mehr aufzurufen."

           Eine Wortmeldung hat DREI Zustaende, nicht zwei:
             1. der Ton ist da            → Knopf zum Nachhoeren
             2. der Ton liegt im Lager    → er kommt gleich (IndexedDB)
             3. der Ton ist wirklich weg  → das sagt die Zeile
           Zustand 2 kannte diese Stelle nicht. Die Zeile fiel damit
           durch zur gewoehnlichen Textzeile — und eine Wortmeldung hat
           keinen Text. Uebrig blieb genau das Gemeldete: Uhrzeit,
           Name, nichts. Und weil sie nicht als Wortmeldung galt, stand
           sie auch noch offen im Chat statt hinter dem Tipp ins Leere.

           Der Ton wird dabei nicht nur abgewartet, sondern geholt:
           lcTonNachreichen() stoesst das Lager an (siehe unten). */
        const istWortmeldung = Boolean(n.sprach || n.sprachWeg || n.sprachImLager
          || n.art === "sprach" || n.art === "live" || n.art === "quittung");
        if (istWortmeldung) {
          const dauer = Number(n.sprachSek) || 0;
          /* Die Marke gilt fuer alle drei Zustaende. Frueher stand sie
             nur am Knopf — eine Zeile ohne Ton stand deshalb offen im
             Chat, obwohl sie dort gerade nichts zu suchen hat. */
          z.classList.add("lc-stimme");
          if (!n.sprach && n.sprachImLager && !n.sprachWeg) {
            /* Zustand 2: er kommt gleich. Kein Schreckensruf. */
            const w = document.createElement("span");
            w.className = "lc-sprach-laedt";
            w.textContent = "🎤 Sprachnachricht wird geladen …"
              + (dauer ? " (" + dauer + "″)" : "");
            t.appendChild(w);
            lcTonNachreichen();
          } else if (!n.sprach) {
            const w = document.createElement("span");
            w.className = "lc-blase-bildweg";
            w.textContent = "🎤 Sprachnachricht — nicht mehr da";
            t.appendChild(w);
          } else {
            /* Ein <span> mit Knopfrolle statt eines <button>: gleich
               kommt der Herunterladen-Verweis HINEIN, und ein <a> in
               einem <button> ist ungueltig — Browser zerlegen das
               still und der Verweis funktioniert nicht mehr. */
            const knopf = document.createElement("span");
            knopf.setAttribute("role", "button");
            knopf.tabIndex = 0;
            knopf.className = "lc-sprachblase";
            knopf.title = "Antippen — noch einmal hören (nur für dich)";
            const balken = document.createElement("i");
            /* Ein paar Striche, die aussehen wie eine Tonspur. Sie sind
               NICHT gemessen, sondern aus der Kennung der Nachricht
               gewuerfelt — aber immer gleich, damit die Zeile beim
               naechsten Zeichnen nicht anders aussieht. */
            let saat = 0;
            String(n.id || "x").split("").forEach((c) => { saat = (saat * 31 + c.charCodeAt(0)) % 9973; });
            for (let i = 0; i < 18; i++) {
              saat = (saat * 1103515245 + 12345) % 2147483648;
              const h = 22 + (saat % 78);
              const st = document.createElement("s");
              st.style.height = h + "%";
              balken.appendChild(st);
            }
            knopf.appendChild(balken);
            const zeit = document.createElement("em");
            zeit.textContent = dauer ? dauer + "″" : "";
            knopf.appendChild(zeit);
            /* GEWUENSCHT: „Vielleicht kannst du den Download-Knopf
               innerhalb der Sprachnachricht anbringen, dass er nicht
               Platz verschwendet, dass er nicht darunter ist — rechts
               neben der Zeit der Sprachnachricht dieses
               Download-Signal."

               Genau dorthin. Er ist kein eigener Knopf mehr, sondern
               sitzt IN der Blase; der Verweis wird gleich unten
               gebaut und hier eingehaengt. Ein <a> in einem <button>
               waere ungueltiges HTML — deshalb ist die Blase selbst
               ein <span> mit Knopfrolle. */
            /* GEMELDET: „Sie sind nicht automatisch von alleine
               hoerbar … mach eine Programmroutine, die das wie bei den
               Animationen verarbeitet."

               Der Grund lag genau da: ein FRISCH erzeugtes Ton-Element
               darf ohne Beruehrung nicht spielen, egal was drin ist.
               Deshalb laeuft die Sprachnachricht jetzt ueber den
               VORRAT — acht Elemente, die beim Betreten waehrend der
               Beruehrung schon einmal gespielt haben und damit
               freigeschaltet sind. Genau derselbe Weg, ueber den auch
               die Stimmen der anderen kommen. */
            const vorlauf = Number(n.sprachAb) || 0;
            const hoeren = (e) => {
              if (e) e.stopPropagation();
              knopf.classList.add("lc-sprach-spielt");
              const fertig = () => knopf.classList.remove("lc-sprach-spielt");
              /* „ab" ueberspringt die Stille vor dem ersten Wort —
                 beim Freisprechen laeuft der Rekorder ja schon,
                 bevor jemand redet (siehe FREI_LUFT in livechat.js). */
              if (LiveChat.tonAusVorrat && LiveChat.tonAusVorrat(n.sprach, fertig, vorlauf, Number(n.sprachDauer) || 0)) return;
              const a = new Audio(n.sprach);
              if (vorlauf > 0) a.onloadedmetadata = () => { try { a.currentTime = vorlauf; } catch (x) {} };
              a.play().catch(() => {
                fertig();
                showToast("Der Browser lässt den Ton noch nicht durch — tipp einmal auf die Seite.");
              });
              a.onended = fertig;
            };
            knopf.addEventListener("click", hoeren);
            knopf.addEventListener("keydown", (e) => {
              if (e.key === "Enter" || e.key === " ") { e.preventDefault(); hoeren(e); }
            });
            t.appendChild(knopf);
            /* HERUNTERLADEN.
               „Ich moechte auch ganze Geschichten vorlesen koennen,
               dass die Leute sich das runterladen koennen und das
               hoeren koennen, wie ich das vorlese, um das
               nachsprechen zu koennen."

               Die Aufnahme steht als Daten-Adresse schon im Browser —
               fuer den Download braucht es also nichts weiter als
               einen Verweis mit „download". Kein Server, kein
               Hochladen, kein Warten. */
            const holen = document.createElement("a");
            holen.className = "lc-sprach-holen";
            holen.href = n.sprach;
            holen.title = "Diese Aufnahme herunterladen und in Ruhe nachsprechen";
            holen.setAttribute("aria-label", "Aufnahme herunterladen");
            const endung = /audio\/mp4|m4a/.test(String(n.sprach).slice(0, 40)) ? "m4a"
              : /ogg/.test(String(n.sprach).slice(0, 40)) ? "ogg" : "webm";
            const wann = new Date(n.zeit || Date.now());
            holen.download = "Klassenzimmer-" + (n.name || "Aufnahme").replace(/[^\wÄÖÜäöüß-]/g, "")
              + "-" + wann.toISOString().slice(0, 16).replace(/[:T]/g, "-") + "." + endung;
            holen.textContent = "⤓";
            holen.addEventListener("click", (e) => e.stopPropagation());
            /* IN die Blase, rechts neben die Zeit — nicht darunter. */
            knopf.appendChild(holen);

            /* =========================================================
               ZURUECKRUFEN, DIREKT AN DER NACHRICHT
               ---------------------------------------------------------
               GEMELDET: „Es gibt keine Moeglichkeit, die Nachricht
               zurueckzurufen oder zu loeschen."

               Den Befehl /weg gab es — aber einen Befehl findet nur,
               wer ihn kennt. Also steht er jetzt dort, wo man ihn
               braucht: an der eigenen Nachricht, gleich neben dem
               Herunterladen.

               Nur an der EIGENEN. Fremde Wortmeldungen loescht
               niemand — das waere kein Zurueckrufen mehr, sondern
               Zensur. */
            if (n.eigen) {
              const rein = document.createElement("button");
              rein.type = "button";
              rein.className = "lc-sprach-weg";
              rein.title = "Zurückrufen — bei allen entfernen";
              rein.setAttribute("aria-label", "Sprachnachricht zurückrufen");
              rein.textContent = "↩";
              rein.addEventListener("click", (e) => {
                e.stopPropagation();
                const id = String(n.id).replace(/-quittung$/, "").replace(/-selbst$/, "");
                const wars = LiveChat.sprachZurueckrufen
                  ? LiveChat.sprachZurueckrufen(id, true) : null;
                showToast((wars && wars.ungehoert
                  ? "↩️ Zurückgerufen — sie war noch nicht dran und ist jetzt weg."
                  : "↩️ Entfernt. Wer sie schon gehört hat, hat sie gehört — "
                    + "das lässt sich nicht zurückholen.")
                  + (wars && wars.ruecknahmeBis
                      ? " Anderthalb Minuten lang kannst du sie zurückholen."
                      : ""));
                renderLiveChat();
              });
              knopf.appendChild(rein);
            }
            /* Von selbst abspielen — aber nur, wenn die Zeile gerade
               eben entstanden ist. „Alt" heisst hier dasselbe wie bei
               den Animationen: was vor dem Betreten geschrieben wurde,
               ist Vergangenheit und bleibt still. */
            /* DIESELBE FALLE WIE BEI DEN ANIMATIONEN — siehe dort:
               Wird nach der Uhrzeit DES ABSENDERS gerechnet, gilt eine
               Sprachnachricht von jemandem mit nachgehender Uhr als
               Vergangenheit und bleibt stumm. Es zählt deshalb auch
               hier, wann sie ANGEKOMMEN ist. */
            const frisch = (n.angekommen || n.zeit || 0) >= livechatEffekteAb - 1500;
            /* WER SPIELT, SPIELT ALLEIN.
               Seit alle Sprachnachrichten durch die Warteschlange
               laufen (siehe livechat.js), darf die Chatzeile sie
               NICHT auch noch starten — sonst hoert man dieselbe
               Aufnahme zweimal uebereinander. Die Zeile ist ab hier
               nur noch zum Nachhoeren und Herunterladen da. Das gilt
               auch fuer die eigene Quittung. */
            const gehoertDerReihe = (art === "live" || art === "quittung");
            if (gehoertDerReihe) lcSprachGehoert.add(n.id);
            /* =========================================================
               ZUGEKLAPPT, BIS MAN SIE BRAUCHT
               ---------------------------------------------------------
               GEMELDET: „Ich finde immer noch nicht den Modus, wie man
               im Chat die Sprachnachrichten versteckt sieht. Ich sehe
               immer noch alles, was ich schicke … Diese Sachen sollen
               nicht sichtbar sein, wenn man spricht. Das soll nur
               sichtbar sein, wenn man es aufgeklappt hat."

               Er hat recht, und es war meine Zeile: die Quittung
               („Abgeschickt · 2 Sekunden · …") stand mit Tonbalken und
               Herunterladen-Pfeil voll ausgeschrieben da. Jetzt ist sie
               zu — eine schmale Zeile, ein Tipp klappt sie auf. Dann
               erst kommen Abspielen und Herunterladen. */
            /* =========================================================
               GESPROCHENES IST UNSICHTBAR — BIS MAN INS LEERE TIPPT
               ---------------------------------------------------------
               GEWUENSCHT: „Der Chat soll sich an der Stelle nicht
               fuellen, wenn man etwas sagt … Es soll nur irgendwie so
               ein globales Ding sein, wo ich das einblende, was gesagt
               wurde von allen Personen. Und dass man, wenn man etwas
               sagt, nicht immer die Sachen sieht — die sind generell
               versteckt. Erst wenn ich intuitiv wie bei Apple in das
               Leere klicke, sehe ich, was dahinter ist; wenn ich
               wieder in das Leere klicke, schliesst sich das wieder."

               Also nicht Zeile fuer Zeile aufklappen, sondern EIN
               Griff fuer alles: ein Tipp in den leeren Teil des
               Chats blendet ALLE gesprochenen Sachen ein, ein
               zweiter blendet sie wieder aus. Die Zeilen tragen
               dafuer nur eine Marke; das Ein- und Ausblenden macht
               eine einzige Klasse am Verlauf (siehe
               lcStimmenUmschalten weiter unten).

               Waehrend man spricht, sieht man also gar nichts — oben
               im Kopf steht ja, wer gerade dran ist, und das reicht. */
            if (frisch && !lcSprachGehoert.has(n.id)) {
              lcSprachGehoert.add(n.id);
              /* Eine Sprachnachricht ist kein Effektgeraeusch: sie
                 spielt auch dann, wenn die Aufkleber-Toene ausgestellt
                 sind. Wer die Toene abstellt, will keine Glocke — er
                 will trotzdem hoeren, was jemand sagt. */
              setTimeout(() => hoeren(null), 60);
            }
          }
        } else if (n.bildImChat) {
          const bild = document.createElement("img");
          bild.className = "lc-zeilenfoto";
          bild.alt = n.text || "Bild im Chat";
          bild.loading = "lazy";
          const quelle = lcBildQuelle(n.bildImChat);
          bild.src = quelle;
          if (LiveChat.aufkleberPfad && LiveChat.aufkleberPfad(n.bildImChat)) {
            bild.classList.add("lc-zeilenfoto-aufkleber");
          }
          /* GEWÜNSCHT: „Bei der Glocke zum Beispiel — aber wenn man
             die dann noch mal anklickt, dass sie quasi den Ton
             ausschaltet." Also: erstes Antippen klingt, zweites
             Antippen desselben Aufklebers schaltet die Töne ab. Das
             gilt dann für alle, bis man einen Aufkleber mit Ton
             wieder antippt. */
          const klebername = (String(n.bildImChat).match(/^aufkleber:([a-z]+)$/) || [])[1] || "";
          const hatTon = klebername && LC_AUFKLEBER_TON[klebername];
          bild.title = hatTon
            ? (lcToeneAn() ? "Antippen — größer ansehen und hören (nochmal: Ton aus)"
                           : "Antippen — größer ansehen (Ton ist aus, nochmal: an)")
            : "Antippen — größer ansehen";
          if (hatTon) bild.classList.add("lc-klingt");
          bild.addEventListener("click", (e) => {
            e.stopPropagation();          // nicht den Zeileneffekt auslösen
            if (hatTon) {
              if (bild.dataset.lcGehoert === "1") {
                /* Zweites Antippen: aus. */
                lcToeneSetzen(false);
                bild.dataset.lcGehoert = "";
                showToast("🔇 Töne sind aus. Noch einmal antippen schaltet sie wieder an.");
              } else {
                if (!lcToeneAn()) {
                  lcToeneSetzen(true);
                  showToast("🔊 Töne sind wieder an.");
                }
                lcTonZu(klebername);
                bild.dataset.lcGehoert = "1";
                /* Nach kurzer Zeit zählt der nächste Tipp wieder als
                   „einmal" — sonst müsste man sich merken, ob man vor
                   zehn Minuten schon einmal getippt hat. */
                setTimeout(() => { bild.dataset.lcGehoert = ""; }, 4000);
              }
              return;
            }
            lcBildGross(quelle, n.text || "");
          });
          t.appendChild(bild);
        } else if (n.bildWeg) {
          const w = document.createElement("span");
          w.className = "lc-blase-bildweg";
          w.textContent = "🖼️ Bild — nicht mehr gespeichert";
          t.appendChild(w);
        }
        if (n.text) {
          if (art === "ruf") lcRufSetzen(t, n.text, n);
          else lcTextEinfaerben(t, n.text, n);
        }
        /* Die ganze ZEILE trägt die Farbe — nicht nur der Name.
           Beim Rufen steht die Farbe schon an jedem Wort (siehe
           lcRufSetzen), deshalb hier nicht noch einmal darüber. */
        if (farbe && art !== "ruf") t.style.color = farbe;
        if (art === "fluester" && n.woher) {
          const q = document.createElement("i");
          q.className = "lc-woher";
          q.textContent = " (aus " + n.woher + ")";
          t.appendChild(q);
        }
        z.appendChild(t);
      }
      /* Eine bekannte Zeile wird ERSETZT, keine zweite angehängt —
         sonst stünde dieselbe Nachricht doppelt da, sobald ihr Bild
         nachkommt. */
      if (alteZeile) alteZeile.replaceWith(z);
      else v.appendChild(z);

      /* Welcher Effekt gehört zu dieser Zeile? */
      /* Vergangenheit? Dann still — siehe oben. */
      /* =============================================================
         WANN EINE ZEILE „GERADE EBEN" IST — UND WARUM SEINE
         ANIMATIONEN NIE KAMEN
         -------------------------------------------------------------
         SEIN BEFUND, und der hat es entschieden:
           „Die Uhr von Emmy geht 5 Sekunden nach."
           „Emmi boxt alle … Knopf nein" — und keine Animation, weder
           beim Boxen noch beim Umarmen noch beim Lecken.

         Hier stand  n.zeit  — die Uhrzeit DES ABSENDERS. Verglichen
         wurde sie mit dem Augenblick, in dem ich den Raum betreten
         habe. Geht ihre Uhr fünf Sekunden nach, sieht JEDE ihrer
         Nachrichten aus, als wäre sie fünf Sekunden VOR meinem
         Betreten geschrieben worden. Damit galt sie als
         Vergangenheit — und Vergangenheit bleibt absichtlich still,
         damit einen Neuankömmling nicht das halbe Archiv anspringt.

         Das Ergebnis: Bei ihm kam von ihr NIE eine Animation. Nicht
         weil eine kaputt war — alle waren in Ordnung, deshalb lief im
         Prüfstand auch alles grün —, sondern weil ihre Uhr nachging.
         Sechs Runden lang habe ich an den Animationen gesucht.

         Jetzt zählt, wann die Zeile ANGEKOMMEN ist, nicht wann sie
         geschrieben wurde. Das ist meine eigene Uhr, und die kann
         keine fremde Einstellung verschieben. Nur wo es keine
         Ankunftszeit gibt (alte Zeilen aus dem Gerät, aus der
         Tabelle), zählt weiterhin die geschriebene Zeit — und das ist
         dort auch richtig, denn die sind wirklich Vergangenheit. */
      const alt = (n.angekommen || n.zeit || 0) < livechatEffekteAb - 1500;
      if (alt) z.classList.add("lc-alt");

      /* =========================================================
         EIN FILM AN DER ZEILE — DIE ECHTE ANIMATION
         ---------------------------------------------------------
         GEWUENSCHT: „Wie bei TikTok, wo ploetzlich ein Loewe
         herumlaeuft … das liegt einfach nur ueber dem Chat."

         Verschickt wird nur der Name. Die Datei holt sich jedes
         Geraet selbst — und der Abspieler faehrt beim Start NICHT
         mit, er wird erst geholt, wenn wirklich ein Film kommt.
         Genau wie bei „alt" gilt: was vor dem Betreten geschrieben
         wurde, laeuft nicht von selbst los. Sonst wuerde jeder, der
         hereinkommt, von den Filmen der letzten Stunde erschlagen. */
      if (n.film && !alt && !livechatEffektGespielt.has("film" + n.id)) {
        livechatEffektGespielt.add("film" + n.id);
        lcFilmSpielen(n.film);
      }
      const eff = n.wirkung || (art === "fluester" ? "fluester" : "");
      if (art === "ruf" && !n.wirkung) {
        z.classList.add("lc-zeile-wirkt");
        z.title = "Antippen — noch einmal";
        /* Das Geschlecht des Absenders bleibt AN DER ZEILE haengen —
           sonst klaenge derselbe Ruf beim zweiten Antippen anders. */
        if (n.geschlecht) z.dataset.lcGeschlecht = n.geschlecht;
        /* Nur der INHALT wiederholt den Ruf. Der Platz daneben und
           die Uhrzeit sind Leere und gehoeren den Sprachnachrichten
           (siehe lcIstLeere). */
        z.addEventListener("click", (e) => {
          if (lcIstLeere(e.target, null)) return;
          lcRufNochmal(z);
        });
        /* GEWUENSCHT: „Wenn man schreit und das abschickt und die
           Animation kommt, dann soll es auch den Chat ein bisschen
           beeinflussen, dass man merkt: der Schall hat einen Effekt
           auf den Chatraum. Und vielleicht ein Sound-Effekt, der
           neutral dazu passt, egal was man schreit."

           Beides nur, wenn die Zeile GERADE eben entstanden ist —
           was vor dem Betreten geschrieben wurde, ist Vergangenheit
           und bleibt still. Angetippt kommt es wieder. */
        if (!alt && !livechatEffektGespielt.has(n.id)) {
          livechatEffektGespielt.add(n.id);
          lcSchallStoss(n.text, n.geschlecht || "", z);
        }
      }
      if (eff) {
        z.dataset.wirkung = eff;
        z.classList.add("lc-zeile-wirkt");
        /* Bei einer Fluesterzeile ist das Antippen zum Antworten da,
           nicht zum Wiederholen der Animation — so war es gewuenscht.
           Die Animation laeuft weiterhin einmal, wenn die Zeile
           ankommt. */
        const fluesterZu = eff === "fluester"
          ? (n.eigen ? (n.wen || "") : (n.name || "")) : "";
        z.title = fluesterZu ? "Antippen — " + fluesterZu + " zurückflüstern"
                             : "Antippen — noch einmal";
        z.addEventListener("click", (e) => {
          /* Genau wie beim Ruf: die Leere gehoert nicht der Animation. */
          if (lcIstLeere(e.target, null)) return;
          if (fluesterZu) { lcZurueckfluestern(fluesterZu); return; }
          lcWirkung(eff, z, n);
          z.classList.remove("lc-neu");
          void z.offsetWidth;
          z.classList.add("lc-neu");
        });
        /* NUR wenn die Zeile gerade eben entstanden ist. Alles Ältere
           ist Vergangenheit und wartet darauf, angetippt zu werden —
           und nur EINMAL je Nachricht, nicht bei jedem Neuzeichnen
           (siehe livechatEffektGespielt). */
        if (!alt && !livechatEffektGespielt.has(n.id)) {
          livechatEffektGespielt.add(n.id);
          lcWirkung(eff, z, n);
        }
      }
    });
    /* GEMELDET, mehrfach: „Wenn man in den Raum kommt, wird immer oben
       zuerst angezeigt, und da muss man immer ganz runterscrollen. Er
       soll aber unten angezeigt werden, da wo man aktuell schreibt."

       Hier stand vorher „beim ERSTEN Zeichnen ganz nach unten", und
       genau das reichte nicht. Zum Zeitpunkt des ersten Zeichnens ist
       der Kasten nämlich noch nicht so hoch, wie er gleich sein wird:
       die Bilder sind noch nicht geladen, die Bilder aus dem Lager
       noch nicht nachgereicht, die Schrift womöglich noch nicht da.
       Jedes dieser Dinge macht den Inhalt hinterher länger — und der
       einmal gesetzte Stand steht dann wieder mitten drin.

       Statt EINMAL zu springen, wird jetzt so lange unten
       FESTGEHALTEN, bis der Mensch selbst hochscrollt. Wer liest,
       bleibt dabei ungestört: sobald er sich vom unteren Rand
       entfernt, lässt der Griff los und kommt erst wieder, wenn er
       von selbst zurückkehrt. */
    lcAmEndeHalten(v);
  }

  /* WARUM MAN NICHT MEHR HOCHSCROLLEN KONNTE.
     -----------------------------------------------------------------
     GEMELDET: „Man kann im Chatverlauf nicht mehr nach oben scrollen,
     um das alte Raetsel zu lesen, wenn man den Chat verlassen oder
     aktualisiert hat. Man soll durch den ganzen Chatverlauf scrollen
     koennen."

     Der Griff, der den Chat unten haelt, war richtig gedacht und an
     einer Stelle falsch gebaut. Er sprang ans Ende und zog den Stand
     im naechsten Bildaufbau (requestAnimationFrame) noch einmal nach,
     weil sich die Hoehe bis dahin aendern kann. Dieser zweite Sprung
     fragte aber NICHT nach, ob der Mensch inzwischen selbst gescrollt
     hat. Und weil ein Sprung seinerseits ein scroll-Ereignis
     ausloest, setzte der Horcher „ich bin unten" gleich wieder auf
     wahr — der Griff rastete neu ein.

     Frueher fiel das kaum auf, weil der Chat selten neu gezeichnet
     wurde. Seit jede Empfangsbestaetigung und jedes „ich hoere
     gerade zu" ein Auffrischen ausloest, passiert es im Sekundentakt,
     und damit wird jedes Hochscrollen sofort wieder eingefangen.

     Jetzt zaehlt eine ABSICHT, keine Position: Wer mit Finger, Rad
     oder Taste scrollt, hat sich entschieden. Der Griff laesst dann
     los und kommt erst zurueck, wenn der Mensch selbst wieder ganz
     unten ankommt — oder den Knopf „↓ Neueste" antippt. Und der
     nachgezogene Sprung prueft vorher, ob seitdem gescrollt wurde. */
  let lcHaeltUnten = true;
  let lcScrollZaehler = 0;        // steigt bei jeder eigenen Bewegung
  function lcAmEndeHalten(v) {
    if (!v) return;
    if (!v.dataset.lcHorcht) {
      v.dataset.lcHorcht = "1";
      const selbst = () => { lcScrollZaehler++; lcHaeltUnten = false; lcSprungKnopf(v); };
      ["wheel", "touchmove"].forEach((art) => {
        v.addEventListener(art, selbst, { passive: true });
      });
      v.addEventListener("keydown", (e) => {
        if (/^(Arrow|Page|Home|End)/.test(e.key)) selbst();
      });
      /* ERST WENN DIE BEWEGUNG ZUR RUHE GEKOMMEN IST.
         Der Verlauf rollt weich (scroll-behavior: smooth). Eine
         Wischbewegung nach oben erzeugt deshalb eine ganze Kette von
         scroll-Ereignissen, und die ERSTEN davon liegen noch dicht
         am unteren Rand — dort sagte die Regel „du bist ja unten"
         und rastete den Griff sofort wieder ein. Gemessen: nach dem
         Wisch stand der Griff wieder auf „haelt", und die naechste
         Auffrischung riss den Chat nach unten.
         Deshalb wird erst geurteilt, wenn 160 ms lang nichts mehr
         passiert ist — also da, wo der Finger wirklich hinwollte. */
      let ruhe = 0;
      v.addEventListener("scroll", () => {
        clearTimeout(ruhe);
        ruhe = setTimeout(() => {
          /* 70 Pixel Spielraum: kleine Stoesse beim Tippen sollen den
             Griff nicht loesen. Ganz unten angekommen heisst: ich
             will wieder mitlaufen. */
          if (v.scrollHeight - v.scrollTop - v.clientHeight < 70) lcHaeltUnten = true;
          lcSprungKnopf(v);
        }, 160);
        lcSprungKnopf(v);
      }, { passive: true });
      /* Jedes Bild, das fertig laedt, macht den Inhalt laenger — danach
         muss der Stand nachgezogen werden, sonst rutscht das Neueste
         wieder aus dem Bild. */
      v.addEventListener("load", () => { if (lcHaeltUnten) lcNachUnten(v); }, true);
    }
    if (lcHaeltUnten) lcNachUnten(v);
    lcSprungKnopf(v);
  }
  function lcNachUnten(v) {
    const stand = lcScrollZaehler;
    const altesRollen = v.style.scrollBehavior;
    v.style.scrollBehavior = "auto";
    v.scrollTop = v.scrollHeight;
    /* Zweimal: einmal sofort, einmal nach dem naechsten Bildaufbau —
       dazwischen kann sich die Hoehe noch aendern. Hat der Mensch in
       der Zwischenzeit selbst gescrollt, unterbleibt der zweite
       Sprung: sonst reisst er ihn wieder nach unten. */
    requestAnimationFrame(() => {
      if (lcScrollZaehler !== stand || !lcHaeltUnten) {
        v.style.scrollBehavior = altesRollen;
        return;
      }
      v.scrollTop = v.scrollHeight;
      v.style.scrollBehavior = altesRollen;
    });
  }
  /* Wer oben liest, soll mit einem Tipp zurueckkommen — und sehen,
     dass es ueberhaupt einen Weg zurueck gibt. */
  function lcSprungKnopf(v) {
    if (!v || !v.parentNode) return;
    const weit = v.scrollHeight - v.scrollTop - v.clientHeight;
    let k = document.getElementById("lcNachUnten");
    if (weit < 120) { if (k) k.remove(); return; }
    if (!k) {
      k = document.createElement("button");
      k.type = "button";
      k.id = "lcNachUnten";
      k.className = "lc-nach-unten";
      k.textContent = "↓ Neueste";
      k.title = "Zurück zum Ende des Chats";
      k.addEventListener("click", (e) => {
        e.stopPropagation();
        lcHaeltUnten = true;
        lcNachUnten(v);
      });
      v.parentNode.insertBefore(k, v.nextSibling);
    }
  }

  /* --- Das Pop-up: ein Gesicht gross ---
     Es bekommt seinen EIGENEN Videostrom-Anschluss; das kleine
     Bild bleibt dabei bestehen. Zwei <video> am selben Strom sind
     erlaubt und kosten nichts. */
  /* =================================================================
     MEHRERE GESICHTER GROSS — RECHTS GESTAPELT
     -----------------------------------------------------------------
     GEWÜNSCHT: „Man soll sich rechts am Rand auch mehrere Videos
     übereinander stapeln können."

     Vorher ging genau EINES. Wer ein zweites gross machte, verlor das
     erste — und in einem Gespräch zu dritt will man nun einmal beide
     sehen, mit denen man redet.

     Drei Entscheidungen stecken darin:

       1. GESTAPELT, NICHT GESCHICHTET. Sie liegen untereinander am
          rechten Rand, nicht übereinander. „Stapeln" heißt hier: man
          sieht alle gleichzeitig.
       2. SIE SCHRUMPFEN GEMEINSAM. Bei einem ist die Kachel gross,
          bei vier sind alle kleiner. Würde jede ihre Grösse behalten,
          liefe der Stapel unten aus dem Bild.
       3. JEDE KACHEL SCHLIESST SICH SELBST. Ein Tipp darauf nimmt
          genau diese heraus — dasselbe Antippen, das sie geholt hat.
          Kein Schliessen-Knopf: „man klickt es einfach wieder an."

     Der Strom wird an jedes <video> eigens gehängt. Mehrere <video>
     am selben Strom sind erlaubt und kosten nichts — es wird nichts
     zweimal übertragen.
     ================================================================= */
  function livechatGrossAuffrischen(l) {
    const halter = document.getElementById("lcGross");
    if (!halter) return;
    const ids = (l.grosse && l.grosse.length ? l.grosse
                 : (l.gross ? [l.gross] : []));
    /* Nur die, die es wirklich noch gibt. */
    const leute = ids.map((id) => l.plaetze.find((x) => x.id === id))
                     .filter((p) => p && !p.leer);
    if (!leute.length) { halter.innerHTML = ""; halter.dataset.fuer = ""; return; }

    /* Neu bauen nur, wenn sich die Zusammenstellung ändert — sonst
       reisst jedes Auffrischen die laufenden Videos ab. */
    const marke = leute.map((p) => p.id).join("|");
    if (halter.dataset.fuer === marke) return;
    halter.dataset.fuer = marke;

    const stapel = document.createElement("div");
    stapel.className = "lc-gross-stapel";
    stapel.dataset.wieviele = String(leute.length);
    stapel.setAttribute("role", "group");
    stapel.setAttribute("aria-label", "Teilnehmer gross");

    leute.forEach((p) => {
      const hatVideo = Boolean(p.strom && p.strom.getVideoTracks
        && p.strom.getVideoTracks().length && p.bildAn !== false);
      const emoji = p.bild && p.bild.indexOf("emoji:") === 0 ? p.bild.slice(6) : "";
      const kachel = document.createElement("div");
      kachel.className = "lc-gross-hinter lc-gross-schwebt";
      /* Der Kreis bleibt ein KREIS — nur grösser.
         GEMELDET: „wenn ich ein Bild grossklicke, versucht er immer
         noch eine Ellipse zu machen." Ursache war, dass das Bild
         position: absolute trug und sich am nächsten positionierten
         Vorfahren aufgehängt hat: dem Überzug über den ganzen
         Bildschirm. Deshalb ein eigenes Element mit eigener Klasse,
         das den Kreis genau ausfüllt — und der Kreis hat eine feste,
         quadratische Grösse. */
      kachel.innerHTML = `
        <div class="lc-gross-kasten">
          <div class="lc-gross-kreis">
            <!-- STUMM, IMMER: ein Bild macht keinen Ton. Sonst liefe
                 dieselbe Stimme ein zweites Mal, hier sogar ein
                 drittes — siehe die Begruendung bei den Plaetzen. -->
            <video autoplay playsinline muted
                   style="${hatVideo ? "" : "display:none;"} ${p.ich ? "transform:scaleX(-1);" : ""}"></video>
            ${hatVideo ? "" : (emoji
              ? `<span class="lc-gross-emoji">${escapeHtml(emoji)}</span>`
              : p.bild
              ? `<img class="lc-gross-bild" alt="">`
              : `<span class="lc-initial"></span>`)}
          </div>
          <span class="lc-gross-name"></span>
        </div>`;
      /* Der Name kommt vom anderen Gerät — er wird deshalb NICHT in
         die Zeichenkette gesetzt, sondern danach über textContent
         eingetragen. Fremder Text ist Text, nie Auszeichnung. */
      const nameFeld = kachel.querySelector(".lc-gross-name");
      if (nameFeld) nameFeld.textContent = p.ich ? p.name + " (du)" : p.name;
      const initial = kachel.querySelector(".lc-initial");
      if (initial) initial.textContent = (p.name || "?").trim().charAt(0).toUpperCase();
      const avatar = kachel.querySelector(".lc-gross-bild");
      if (avatar && p.bild) avatar.setAttribute("src", lcBildQuelle(p.bild));
      const v = kachel.querySelector("video");
      if (v && p.strom) {
        v.muted = true;                 /* siehe oben: ein Bild macht keinen Ton */
        v.srcObject = p.strom;
        const sp = v.play(); if (sp && sp.catch) sp.catch(() => {});
      }
      kachel.title = "Antippen — wieder klein";
      kachel.addEventListener("click", () => LiveChat.grossZeigen(p.id));
      stapel.appendChild(kachel);
    });

    halter.innerHTML = "";
    halter.appendChild(stapel);
  }

  function renderLiveChat() {
    /* STEHT EIN SONDENBRETT, GEHOERT DIE BUEHNE IHM.
       -----------------------------------------------------------
       Seit „wer ankommt, nimmt den Platz auch wirklich ein" (Runde
       22) ruft die Fahrt am Ende renderLiveChat. In den Sonden baut
       sich damit die ECHTE Sitzreihe auf — und die traegt dieselbe
       Kennung „livechatKarte" wie das Sondenbrett. getElementById
       nimmt dann die erste im Dokument, also die echte, auf der
       niemand sitzt: gemessen wurden daraufhin lauter Nullen, in
       pruefe-runde15 und pruefe-runde16 zusammen elf Stueck.

       Im Betrieb gibt es dieses Brett nie — es entsteht nur durch
       DMA_PRUEF.effektBuehne(). Diese eine Zeile haelt die Messung
       sauber und aendert an der Seite selbst nichts. */
    if (document.getElementById("lcPruefBuehne")) return;
    const area = document.getElementById("livechatArea");
    if (!area) return;
    if (!window.LiveChat) {
      area.innerHTML = '<p class="empty-note">Der Live-Chat ist auf diesem Gerät nicht geladen.</p>';
      return;
    }
    const l = LiveChat.lage();

    /* Draussen: Startschirm. Das Gerüst wird dabei vergessen,
       damit es beim nächsten Betreten frisch gebaut wird. */
    if (l.lage === "aus" || l.lage === "fehler") {
      livechatGeruest = false;
      livechatGezeigt = new Map();
      livechatEffekteAb = 0;          // beim nächsten Betreten neu stellen
      livechatEffektGespielt.clear();
      livechatSchonUnten = false;
      lcHaeltUnten = true;
      area.innerHTML = livechatStartHtml(l);
      /* NACHGEBESSERT, und es ist eine Kehrtwende gegenüber früher:
         Vorher stand hier ausdrücklich mitBild: false, mit der
         Begründung „dass das nicht sofort zum Video springt, dass man
         sich entscheiden kann, ob man das Video anschalten will."
         Jetzt gilt: „dass diese Video- und Tonabfrage immer erzwungen
         kommt, dass die Leute, bevor sie den Chat betreten, auch
         wirklich das anschalten müssen, damit es überall klappt und
         niemand den anderen nicht hört." Das Tor macht genau das —
         siehe livechatTor(). */
      const hinein = (raum) => livechatHinein(raum);
      area.querySelector("#lcBetreten")?.addEventListener("click", () => {
        /* Ein Link schlägt alles — wer eingeladen wurde, will dorthin.
           Sonst IMMER der Hauptraum: „Der Hauptraum soll für jeden
           direkt zugänglich sein." Der zuletzt benutzte Raum wird
           ausdrücklich NICHT mehr genommen; sonst landete man nach
           einem privaten Gespräch wieder dort und wunderte sich,
           warum niemand da ist. */
        hinein(LiveChat.raumAusAdresse() || LiveChat.HAUPTRAUM);
      });
      /* GEWÜNSCHT: „Der Raum, den man selber anlegt — wenn man zum
         ersten Mal reingeht, soll man ihn auch mit einem Namen
         benennen können, nicht dass da nur so ein Buchstabenwurm
         steht."

         Der Buchstabenwurm kam aus neuerRaumName(): vierzehn
         zufällige Zeichen, damit niemand den Raum errät. Als
         Adresse ist das richtig, als Überschrift unbrauchbar.
         Jetzt wird zuerst gefragt. Wer einen Namen eingibt, bekommt
         ihn auch als Adresse (raumSchluessel) — dann können Freunde
         mit /j <name> dazukommen, ohne einen Link zu brauchen. Wer
         abbricht, bekommt wie bisher den zufälligen Namen; der Raum
         ist dann privat und nur über den Link erreichbar. */
      area.querySelector("#lcEigenerRaum")?.addEventListener("click", () => {
        livechatRaumTaufen().then((raum) => { if (raum) hinein(raum); });
      });
      area.querySelector("#lcArchivStart")?.addEventListener("click", () => livechatArchiv());
      area.querySelector("#lcZumKlassenzimmer")?.addEventListener("click", () => {
        document.querySelector('#knowledgeSubnav [data-sub="sub-klassenzimmer"]')?.click();
      });
      /* Die Räume, die gerade offen sind — mit Schloss bei den
         abgeschlossenen. Sie kommen aus dem Präsenzkanal, den die
         Seite ohnehin mithört; man muss dafür nirgends hineingehen. */
      livechatRaumListe();
      return;
    }

    /* Drinnen: Gerüst einmal bauen, danach nur noch auffrischen. */
    if (!livechatGeruest || !document.getElementById("livechatKarte")) {
      area.innerHTML = livechatGeruestHtml();
      livechatGeruest = true;
      livechatGezeigt = new Map();
      /* Ab JETZT ist etwas „gerade eben" — alles Ältere ist
         Vergangenheit und bleibt still. */
      livechatEffekteAb = Date.now();
      livechatSchonUnten = false;
      lcHaeltUnten = true;
      /* Und der Chat steht mit seinem unteren Ende im Bild, nicht mit
         seinem Anfang — dort steht das Neueste. */
      setTimeout(() => livechatInsBild(), 220);
      /* Nach der Begrüssungsrunde: ist der Raum leer und ich habe einen
         eigenen Hintergrund, bringe ich ihn mit. Vorher wäre es falsch —
         da weiß man noch nicht, ob jemand da ist. */
      setTimeout(lcHintergrundInDenRaumBringen, 1800);

      /* =============================================================
         EIN TIPP AUF EINEN PLATZ: HINSETZEN ODER TAUSCHEN
         -------------------------------------------------------------
         GEMELDET, zum zweiten Mal: „Man kann die Sitzplaetze durch
         Klicken auf die anderen Sitzplaetze immer noch nicht wechseln
         oder tauschen."

         Vorher tat ein Tipp auf einen freien Platz nur eines: einen
         irgendwohin auf die Buehne setzen — nicht auf DIESEN Platz.
         Und ein Tipp auf einen besetzten Platz vergroesserte nur das
         Bild. Jetzt:

           freier Platz          → du setzt dich genau dorthin
           Platz eines anderen   → ihr tauscht die Plaetze
           dein eigener Platz    → dein Bild gross (wie bisher)
           LANG druecken         → das Bild gross (fuer alle Plaetze)

         Das Vergroessern ist also nicht weg, es ist nur einen langen
         Druck weiter — und der eigene Platz macht es weiterhin mit
         einem Tipp. Ein Hinweis sagt das beim ersten Mal, sonst
         sucht man es. */
      /* HIER LAG DER FEHLER, UND ER WAR HANDFEST.
         XANDER, mehrfach gemeldet: „wenn man einen Effekt auf jemand
         anderen anwendet, passiert es immer noch, dass er im Grossbild
         angezeigt wird. Das soll nicht so sein."

         Nachgesehen: auf JEDEM Platz lagen ZWEI Uhren fuer den langen
         Druck. Die eine (lcPlatzMenueBinden, 480 ms) oeffnet das
         Platzmenue, die andere (hier, 620 ms) zog das Bild gross. Wer
         das Menue aufmacht, um einen Effekt zu waehlen, haelt den
         Finger laenger als 620 ms — und loeste damit IMMER beides aus.
         Genau das hat er gesehen.

         Die zweite Uhr ist deshalb weg. Gross zeigen macht jetzt nur
         noch die Lupe im Menue — „man soll die anderen gross zeigen
         koennen und dafuer die Lupe haben". */
      area.querySelectorAll("[data-lc-platz]").forEach((k) => {
        k.addEventListener("click", () => {
          const nr = Number(k.dataset.lcPlatz);
          const p = LiveChat.lage().plaetze.find((x) => x.nummer === nr);

          /* Ein freier Platz: genau dorthin. Wer noch nicht auf der
             Buehne ist, geht zuerst hinauf — sonst gaebe es nichts zu
             setzen. */
          if (!p || p.leer) {
            const warOben = LiveChat.aufDerBuehne && LiveChat.aufDerBuehne();
            if (!warOben) {
              LiveChat.buehneSetzen(true);
              const erg = LiveChat.platzNehmen ? LiveChat.platzNehmen(nr) : null;
              renderLiveChat();
              showToast(erg && erg.ok ? "🪑 " + erg.text
                : "🎤 Du bist auf der Bühne." + (erg && erg.warum ? " " + erg.warum : ""));
              return;
            }
            /* ZURUECKGENOMMEN — und zwar auf seine ausdrueckliche Ansage:
               „Standard soll so sein, dass man immer auf die Plaetze
               klickt und dann auf einen Platz seiner Wahl einfach kommt
               durch das Klicken auf den Platz, so wie es vorher auch
               war. Das Fahren soll nur stattfinden, wenn man das Fahren
               auch anwaehlt."

               In Fassung 359 fuhr ein Tipp los. Das war eine Anmassung:
               der kurze Weg auf einen freien Platz ist der haeufigste
               Griff ueberhaupt, und der darf nicht drei Sekunden
               dauern. Ein Tipp setzt also wieder SOFORT um.

               Wie man ankommt, waehlt man dort, wo es hingehoert:
               „Ich faende das auch sinnvoller, das Ziel anzuklicken, wo
               man hin will, und auf diesem Ziel auszuwaehlen, wie man
               da hinkommen will. Entweder fahren oder springen."
               Das ist das Anreise-Menue — langer Druck auf den freien
               Platz, siehe lcPlatzMenue. */
            const erg = LiveChat.platzNehmen ? LiveChat.platzNehmen(nr) : null;
            renderLiveChat();
            if (erg && erg.ok) showToast("\ud83e\ude91 " + erg.text
              + "  (lang dr\u00fccken: fahren oder laufen)");
            else if (erg && erg.warum) showToast(erg.warum);
            return;
          }

          /* =========================================================
             EIN TIPP ZIEHT NICHTS MEHR GROSS AUF
             ---------------------------------------------------------
             GEMELDET: „Beim Anklicken eines Profilbilds gehen die
             anderen immer noch auf — das soll nicht mehr aufgehen …
             das stoert immer ein bisschen."

             Frueher war das die einzige Art, an das eigene Bild und
             an die Sprech-Animation zu kommen. Seit Fassung 352
             steht beides im Platzmenue (langer Druck), und das grosse
             Bild war damit nur noch im Weg: ein Tipp daneben, und es
             ging ungefragt auf.

             Der eigene Platz tut auf einen kurzen Tipp jetzt nichts.
             Wer sein Bild gross sehen will, haelt gedrueckt — dort
             steht es weiterhin. */
          if (p.ich) return;

          /* Und der Platz eines anderen: tauschen. */
          const erg = LiveChat.platzTauschenMit ? LiveChat.platzTauschenMit(p.id) : null;
          if (erg && erg.ok) {
            renderLiveChat();
            showToast("🔄 " + erg.text + "  (lang drücken öffnet das Menü)");
            return;
          }
          /* Geht der Tausch nicht — etwa weil man noch nicht sitzt —,
             passiert nichts weiter. Frueher zog sich hier das grosse
             Bild auf; genau das war gemeldet („das soll nicht mehr
             aufgehen"). Es bleibt beim langen Druck. */
          if (erg && erg.warum) showToast(erg.warum);
        });
      });
      area.querySelector('[data-lc="ton"]')?.addEventListener("click", () => LiveChat.tonUmschalten());
      area.querySelector('[data-lc="bild"]')?.addEventListener("click", () => LiveChat.bildUmschalten());
      /* GEWÜNSCHT: „Es soll auch eine Möglichkeit geben, wieder von der
         Bühne runterzugehen, wenn man lieber nur im Chat bleiben will." */
      area.querySelector('[data-lc="buehne"]')?.addEventListener("click", () => {
        const drauf = LiveChat.buehneSetzen(!LiveChat.aufDerBuehne());
        /* GEMELDET: „Das Zeichen zum Runtergehen und Hochgehen kann auch
           ein Mikrofon sein — wenn das Mikrofonzeichen schon vergeben
           ist, musst du dann zwei Pfeile im Wechsel nehmen."
           Das Mikrofon IST schon vergeben (Ton an/aus). Also zwei
           Pfeile: der Knopf zeigt, wohin es geht. */
        renderLiveChat();
        showToast(drauf
          ? "🎤 Du bist auf der Bühne — Ton und Bild gehen wieder hinaus."
          : "💬 Du bist von der Bühne herunter. Mitschreiben geht weiter.");
      });
      /* GEWÜNSCHT: „Wenn man auf das Schliessen des Raumes geht, soll
         man in die allgemeine Raumübersicht kommen." */
      area.querySelector('[data-lc="weg"]')?.addEventListener("click", () => {
        LiveChat.verlassen();
        renderLiveChat();
        setTimeout(() => {
          document.getElementById("lcRaumListe")
            ?.scrollIntoView({ behavior: "smooth", block: "center" });
        }, 120);
      });
      /* LANGES DRÜCKEN auf einen Platz öffnet jetzt das Platzmenü —
         auf dem eigenen mit der Bildauswahl obenan, auf einem fremden
         nur mit dem, was man mit dem Profilbild anstellen kann. Der
         alte Sonderweg „nur Platz 1, nur Bildauswahl" ist damit
         überholt; das Menü kann beides. */
      lcPlatzMenueBinden(area);
      area.querySelector('[data-lc="profilbild"]')?.addEventListener("click", () => livechatBildWaehler());
      /* Der Schalter fuer die Buehnenansicht — klassisch oder
         Gegenueber (siehe lcAnsicht weiter oben). */
      area.querySelector("#lcAnsicht")?.addEventListener("click", (e) => {
        e.stopPropagation();
        const neu = lcAnsicht() === "gegenueber" ? "klassisch" : "gegenueber";
        lcAnsichtSetzen(neu);
        const l = LiveChat.lage();
        lcAnsichtZeichnen(l);
        showToast(neu === "gegenueber"
          ? "👥 Gegenüber — du siehst nur noch, wer wirklich auf der Bühne sitzt, dafür gross."
          : "🪑 Klassenzimmer — alle acht Plätze, auch die freien.");
      });
      /* DER PANIK-KNOPF. Er sagt auch, was er gefunden hat — sonst
         drueckt man ihn und weiss nicht, ob etwas passiert ist. */
      area.querySelector("#lcLeseKnopf")?.addEventListener("click", (e) => {
        e.stopPropagation();
        lcLeseWaehler();
      });
      /* Aufgeklappte Sektion = gleich kommt etwas daraus. Der
         toggle-Ruf steigt nicht von selbst auf, deshalb wird er in
         der Fangphase abgeholt. */
      area.addEventListener("toggle", (e) => {
        const d = e.target;
        if (!d || !d.classList || !d.classList.contains("lc-befehlsgruppe") || !d.open) return;
        const g = d.dataset ? d.dataset.gr : "";
        if (g) { try { lcFilmeHolenJetzt(lcFilmeZuGruppe(g)); } catch (x) {} }
      }, true);
      area.querySelector("#lcMusikKnopf")?.addEventListener("click", (e) => {
        e.stopPropagation();
        lcMusikWaehler();
      });
      area.querySelector("#lcTonNeu")?.addEventListener("click", (e) => {
        e.stopPropagation();
        let erg = null;
        try { erg = LiveChat.tonNeuAufbauen ? LiveChat.tonNeuAufbauen() : null; } catch (x) {}
        if (!erg) { showToast("Der Ton liess sich gerade nicht zurücksetzen."); return; }
        /* GEWUENSCHT: „dass ich mich selber niemals hören kann …
           vielleicht kannst du das in diesen Tonschalter mit einbauen."
           Der Schalter sagt deshalb auch, ob er ein eigenes Echo
           gefunden und abgeklemmt hat. */
        if (erg.selbst) {
          showToast("🔊 Dein eigenes Echo ist abgeklemmt — du hörst dich nie selbst. "
            + erg.wieder + " andere Stimme" + (erg.wieder === 1 ? "" : "n") + " stehen.");
          return;
        }
        if (erg.leitungen) {
          showToast("\ud83d\udd0a " + erg.leitungen + " Leitung"
            + (erg.leitungen === 1 ? "" : "en") + " neu aufgebaut"
            + (erg.doppelt ? ", " + erg.doppelt + " doppelte Spur angehalten" : "")
            + " \u2014 du bleibst im Klassenzimmer, es l\u00e4dt nichts neu.");
          return;
        }
        showToast(erg.doppelt
          ? "🔊 " + erg.doppelt + " doppelte Tonspur" + (erg.doppelt === 1 ? "" : "en")
            + " angehalten — jetzt hörst du jeden einmal."
          : "🔊 Ton neu aufgebaut (" + erg.wieder + " Stimmen). Es war nichts doppelt — "
            + "hörst du trotzdem doppelt, ist noch ein zweites Fenster offen.");
      });
      /* Die Aufgabe beenden — dasselbe wie  /aufgabe  ohne Text, nur
         zum Antippen. Danach steht an keiner Zeile mehr ein
         Notenknopf, und genau das soll sichtbar entschieden sein. */
      area.querySelector("#lcAufgabeSchluss")?.addEventListener("click", () => {
        LiveChat.schreiben("/aufgabe");
        lcAufgabeZeichnen();
        showToast("✔️ Die Aufgabe ist beendet.");
      });
      area.querySelector("#lcRaeume")?.addEventListener("click", () => livechatRaumFenster());
      const fotoFeld = area.querySelector("#lcFoto");
      /* Der Anhang oeffnet jetzt den WAEHLER, nicht mehr direkt den
         Dateikasten. „Im Anhang koennen wir das Bildsymbol mit
         unterbringen, dass man sowohl die Dateien auswaehlen kann,
         die auf dem System sind, als auch ein Bild von den GIFs und
         die ganzen Sachen, die zum System gehoeren." Im Waehler
         stehen beide Wege nebeneinander: „Foto vom Geraet" und
         Aufkleber, Fuechse, zuletzt benutzte Bilder, GIPHY. */
      area.querySelector("#lcFotoKnopf")?.addEventListener("click", () => livechatSendeWaehler());
      fotoFeld?.addEventListener("change", async () => {
        const datei = fotoFeld.files && fotoFeld.files[0];
        fotoFeld.value = "";
        if (!datei) return;
        const feld = document.getElementById("lcFeld");
        const text = feld ? feld.value.trim() : "";
        try {
          await LiveChat.fotoSenden(datei, text);
          if (feld) { feld.value = ""; document.getElementById("lcSenden").disabled = true; }
        } catch (e) {
          showToast("📎 " + (e && e.message ? e.message : "Das Bild ging nicht."));
        }
      });
      /* Früher stand hier ein window.prompt(), das nach einer
         GIF-Adresse gefragt hat. Auf dem Telefon gibt es keinen
         Rechtsklick und damit keine Adresse zum Kopieren — genau
         deshalb „gingen die GIFs nicht". Jetzt öffnet der Knopf den
         Wähler mit Suche, Sammelfüchsen und der Liste „zuletzt
         benutzt". */

      area.querySelector("#lcSofortKnopf")?.addEventListener("click", (e) => {
        const an = !kzEinstellung("sofortSenden", false);
        kzEinstellungSetzen("sofortSenden", an);
        e.currentTarget.setAttribute("aria-pressed", String(an));
        e.currentTarget.textContent = an ? "an" : "aus";
        showToast(an
          ? "⚡ Ein Befehl aus der Liste geht jetzt sofort hinaus."
          : "Befehle landen wieder erst im Schreibfeld.");
      });
      area.querySelector("#lcBefehle")?.addEventListener("click", () => {
        const k = document.getElementById("lcBefehleKasten");
        if (k) k.open = !k.open;
      });
      /* Die Schrift steht jetzt IM Befehlskasten und wird direkt
         angetippt, nicht mehr durchgeschaltet — man sieht dabei auch,
         welche gerade steht. GEMELDET: „Die Schrift ist ja eigentlich
         Teil von den Befehlen mit."

         Wichtig: renderLiveChat() zeichnet den Kasten neu und würde ihn
         dabei zuklappen. Deshalb wird gemerkt, dass er offen war, und
         er wird danach wieder aufgemacht — sonst fällt einem die
         Auswahl unter den Fingern weg. */
      /* Ein Favorit legt den Befehl ins Feld. Befehle, die einen Namen
         oder einen Text brauchen, bekommen gleich das Leerzeichen
         dahinter — sonst müsste man es selbst tippen. */
      area.querySelectorAll("[data-lc-haeufig]").forEach((b) =>
        b.addEventListener("click", () => {
          const wort = b.dataset.lcHaeufig;
          const feld = document.getElementById("lcFeld");
          if (!feld) return;
          const liste = (window.LiveChat && LiveChat.befehlsliste) ? LiveChat.befehlsliste() : [];
          const eintrag = liste.filter((x) => x.w === wort)[0];
          const brauchtMehr = Boolean(eintrag && /<[^>]+>/.test(eintrag.nutzt));
          feld.value = "/" + wort + (brauchtMehr ? " " : "");
          feld.focus();
          try { feld.setSelectionRange(feld.value.length, feld.value.length); } catch (e) {}
        }));
      area.querySelectorAll("[data-lc-sprechbild]").forEach((b) =>
        b.addEventListener("click", () => {
          if (!LiveChat.sprechbildSetzen || !LiveChat.sprechbildSetzen(b.dataset.lcSprechbild)) return;
          area.querySelectorAll("[data-lc-sprechbild]").forEach((x) =>
            x.setAttribute("aria-pressed", String(x === b)));
          showToast("🗣️ " + LiveChat.sprechbilder()[b.dataset.lcSprechbild]);
          renderLiveChat();
        }));
      area.querySelectorAll("[data-lc-schrift]").forEach((b) =>
        b.addEventListener("click", () => {
          const war = document.getElementById("lcBefehleKasten")?.open;
          const offeneGruppen = [...area.querySelectorAll(".lc-befehlsgruppe[open] > summary")]
            .map((x) => x.textContent.trim());
          LiveChat.schriftSetzen(b.dataset.lcSchrift);
          renderLiveChat();
          const k = document.getElementById("lcBefehleKasten");
          if (k && war) {
            k.open = true;
            k.querySelectorAll(".lc-befehlsgruppe").forEach((g) => {
              if (offeneGruppen.includes(g.querySelector("summary").textContent.trim())) g.open = true;
            });
          }
          showToast("🔤 Schrift: " + b.textContent.trim());
        }));
      livechatTippsBinden(area);
      lcRuecknahmenZeichnen(area);
      /* Die Kopfzeile schaltet die Sprachnachrichten — derselbe Weg
         wie ein Tipp ins Leere, nur findbar. */
      area.querySelector("#lcKopfStimmen")?.addEventListener("click", (e) => {
        e.stopPropagation();
        const v = area.querySelector("#lcVerlauf");
        if (v) lcStimmenUmschalten(v);
      });
      /* Der Fokusschalter wird bei JEDEM Zeichnen nachgezogen — nicht
         nur dann, wenn die Sprachleiste gerade gebaut wird. Sonst
         fehlte er ueberall dort, wo es keine Sprachnachrichten gibt,
         und genau so war er „weg". */
      lcFokusSchalterZeichnen();
      if (LiveChat.beiHintergrund) LiveChat.beiHintergrund(lcHintergrundWaehlen);
      /* Wechselt jemand anders den Hintergrund des Raums, wird hier neu
         gezeichnet — sonst sähe man es erst beim nächsten Anlass. */
      if (LiveChat.beiRaumHintergrund) LiveChat.beiRaumHintergrund(() => renderLiveChat());
      /* GEMELDET: „Man soll den Hintergrund nicht nur durch den Code
         ändern, sondern auch als Bild einladen können." Also ein
         Knopf, nicht nur der Befehl /hintergrund. Ist schon eines
         gesetzt, fragt er, ob es weg soll. */
      /* Der Hintergrund-Knopf steht nicht mehr hier, sondern im Bildmenü
         oben (🖼️-Rundknopf) — GEMELDET: „Hintergrund könnte man doch in
         dieses normale Bildpanel mit einbauen … dass man einmal das
         Profilbild wechseln kann, aber in dem Menü auch das
         Hintergrundbild festlegen." Die Arbeit selbst steht deshalb in
         lcHintergrundUmschalten(), damit beide Wege dasselbe tun. */

      /* GEWÜNSCHT: „Wenn man ein bisschen scrollt — nicht innerhalb des
         Chats, sondern auf der Hauptseite nach oben und unten — und
         will dann wieder zurück zum Chat, dann springt ja nichts.
         Man zentriert sich das dann so zurecht. Hier könnte man zum
         Beispiel in den Rahmen von dem allgemeinen Chatpanel klicken,
         und es zentriert sich wieder, wie es vorher war."

         Also: ein Tipp auf den RAHMEN — nicht auf eine Zeile, nicht auf
         das Eingabefeld, nicht auf einen Knopf — rückt das Klassen-
         zimmer wieder in die Mitte des Bildschirms. */
      const karte = area.querySelector("#livechatKarte") || area.firstElementChild;
      area.querySelector(".lc-chat")?.addEventListener("click", (e) => {
        if (e.target.closest(".lc-zeile, .lc-chat-fuss, button, input, a, details, pre, img")) return;
        livechatAnSeinenPlatz();
      });
      /* Auch ein Tipp ins Leere DANEBEN — neben den Plätzen, unter der
         Leiste — rückt alles wieder an seinen Ort. GEWÜNSCHT: „dass man
         einfach nur in den leeren Bereich des Chatpanels klickt und
         dann positioniert sich das wieder so ein." */
      area.addEventListener("click", (e) => {
        if (e.target.closest("button, input, a, details, pre, img, .lc-zeile, .lc-platz, .lc-chat")) return;
        livechatAnSeinenPlatz();
      });
      /* Auch „Verlauf löschen" ist ins Bildmenü gezogen — siehe
         lcVerlaufLeerenFragen(). */

      /* ---- Die Sprachnachricht: gedrueckt halten und sprechen ----
         GEWUENSCHT: „dass sie dort kurz was aufnehmen koennten … und
         wenn man sie schickt, werden sie sofort hoerbar."

         Gedrueckt halten nimmt auf, loslassen schickt. Das ist die
         Geste, die jeder vom Telefon kennt, und sie hat einen zweiten
         Vorteil: Aufnehmen beginnt WAEHREND einer Beruehrung — genau
         dann laesst ein Telefon den Ton ueberhaupt erst zu.

         Wer wegzieht, statt loszulassen, bricht ab. So kommt keine
         Aufnahme heraus, die man gar nicht schicken wollte. */
      const sprachKnopf = area.querySelector("#lcSprachKnopf");
      if (sprachKnopf) {
        if (!LiveChat.sprachGehtDas || !LiveChat.sprachGehtDas()) {
          sprachKnopf.disabled = true;
          sprachKnopf.title = "Dieser Browser kann keine Sprachnachrichten aufnehmen.";
        } else {
          let laeuft = false, abgebrochen = false, takt = 0;
          /* NUR eine Klasse umlegen. Frueher wurde hier der Text des
             Knopfes getauscht — und weil ein Emoji Text ist, hat das
             lange Druecken auf dem Telefon die Markierung aufgerufen
             statt aufzunehmen. Die Zeichnung im Knopf bleibt jetzt
             stehen, die Farbe sagt, was los ist. */
          /* GEWUENSCHT: „Wenn ich spreche, moechte ich auch sehen, dass
             ich gerade spreche."
             Der Knopf allein reicht nicht — den hat man unter dem
             Finger und sieht ihn nicht. Deshalb bekommt die ganze
             Seite eine Marke, und die Kopfzeile des Chats zeigt gut
             sichtbar „🔴 Du sprichst". */
          let vonX = 0, vonY = 0;
          /* ZWEI PAAR SCHUHE, UND BEIDE BLEIBEN.
             GEMELDET: „Es gab zwei Zustaende. Der allererste war,
             dass wir diese gruene Bubble hatten … Danach hast du aus
             einem Missverstaendnis heraus — was mir aber sehr gut
             gefallen hat — da, wo Chat steht, bei der Aufnahme das
             so pulsieren lassen, und da stand etwas. Genau diese
             erste Version davon soll auch wieder uebernommen werden,
             naemlich fuer die Aufnahme."

             Also: waehrend der AUFNAHME pulst die Kopfzeile und es
             steht „du sprichst" daneben (dazu weiterhin der rote
             Knopf). Sobald losgelassen und abgeschickt ist, uebernimmt
             die gruene Pille ueber dem Verlauf mit „… spricht
             gerade". Zwei Zustaende, zwei Anzeigen, keine vermischt. */
          const anzeigen = (an) => {
            sprachKnopf.classList.toggle("lc-sprach-an", an);
            document.body.classList.toggle("lc-ich-spreche", an);
          };
          const los = async (e) => {
            e.preventDefault();
            if (laeuft) return;
            /* Derselbe Griff wie beim Betreten: die Beruehrung nutzen,
               um die Tonausgabe freizuschalten. */
            if (LiveChat.tonFreischalten) { try { LiveChat.tonFreischalten(); } catch (x) {} }
            abgebrochen = false;
            /* DER FINGER DARF DEN KNOPF NICHT VERLIEREN.
               ---------------------------------------------------
               GEMELDET: „Sobald ich die Hand gedrueckt halte,
               verschiebt sich der Chat nach unten, weil diese
               zusaetzliche Zeile ihn verlaengert — dadurch rutsche
               ich von der Sprechtaste ab und meine Aufnahme wird
               immer abgebrochen."

               Der Abbruch hing an „pointerleave": verlaesst der
               Zeiger den Knopf, gilt das als Zuruecknehmen. Nur
               verlaesst er ihn auch dann, wenn nicht der Finger
               wandert, sondern der KNOPF — und genau das passiert
               bei jeder Aenderung der Hoehe.

               setPointerCapture bindet den Zeiger an den Knopf:
               von da an gehen alle seine Ereignisse hierher, ganz
               gleich, was sich unter dem Finger verschiebt. Das
               absichtliche Wegziehen bleibt moeglich — es haengt
               jetzt an der zurueckgelegten STRECKE (siehe bewegt),
               nicht daran, wer sich bewegt hat. */
            try { if (e.pointerId != null) sprachKnopf.setPointerCapture(e.pointerId); } catch (x) {}
            vonX = e.clientX || 0; vonY = e.clientY || 0;
            laeuft = await LiveChat.sprachAufnahmeStarten();
            if (!laeuft) { try { sprachKnopf.releasePointerCapture(e.pointerId); } catch (x) {} return; }
            anzeigen(true);
            const start = Date.now();
            clearInterval(takt);
            takt = setInterval(() => {
              const sek = Math.floor((Date.now() - start) / 1000);
              sprachKnopf.setAttribute("aria-label", "Aufnahme läuft, " + sek + " Sekunden");
              if (sek >= (LiveChat.sprachHoechstdauer ? LiveChat.sprachHoechstdauer() : 20)) fertig();
            }, 250);
          };
          const loslassen = (e) => {
            try { if (e && e.pointerId != null) sprachKnopf.releasePointerCapture(e.pointerId); } catch (x) {}
          };
          const fertig = async (e) => {
            if (e) e.preventDefault();
            loslassen(e);
            clearInterval(takt);
            if (!laeuft) return;
            laeuft = false;
            anzeigen(false);
            if (abgebrochen) { LiveChat.sprachAbbrechen(); return; }
            await LiveChat.sprachAufnahmeStoppen();
          };
          const weg = (e) => {
            loslassen(e);
            if (!laeuft) return;
            abgebrochen = true;
            clearInterval(takt);
            laeuft = false;
            anzeigen(false);
            LiveChat.sprachAbbrechen();
            showToast("Aufnahme abgebrochen — zum Schicken den Finger auf dem Knopf lassen.");
          };
          /* Absichtlich wegziehen: erst ab elf Millimetern Strecke.
             Ein Wackeln der Hand oder ein Ruck im Bild sind weniger. */
          const bewegt = (e) => {
            if (!laeuft) return;
            const dx = (e.clientX || 0) - vonX, dy = (e.clientY || 0) - vonY;
            if (Math.sqrt(dx * dx + dy * dy) > 110) weg(e);
          };
          sprachKnopf.addEventListener("pointerdown", los);
          sprachKnopf.addEventListener("pointerup", fertig);
          sprachKnopf.addEventListener("pointercancel", weg);
          sprachKnopf.addEventListener("pointermove", bewegt);
          /* KEIN pointerleave mehr — siehe oben: es hat abgebrochen,
             wenn sich der Knopf bewegt hat, nicht der Finger. */
          /* Und das Markieren/Kopieren-Menue endgueltig abstellen: die
             CSS-Regeln halten das Meiste ab, dieses hier den Rest. */
          sprachKnopf.addEventListener("contextmenu", (e) => e.preventDefault());
          sprachKnopf.addEventListener("selectstart", (e) => e.preventDefault());
        }
      }

      /* ---- Freisprechen ----
         „Oder es ist staendig aktiv und hat einen Schwellwert … sobald
         die Person spricht, wird auch aufgenommen. Das wird sofort
         abgeschickt." Ein Schalter, kein Halten. */
      /* =============================================================
         DAS HAEKCHEN „DAUERND"
         -------------------------------------------------------------
         GEWUENSCHT: „Als kleines Haekchen mit einbringen, und zwar
         fuer den normalen Mikrofonmodus: sobald das Haekchen
         aktiviert ist, ist es immer an, und was durchkommt, bleibt.
         Aber wie gesagt immer in der zeitlichen Reihenfolge."

         Es ist derselbe Weg wie beim Halten — nur ohne Halten. Die
         Warteschlange, das Kappen, die Reihenfolge: alles gleich.
         Das Symbol wechselt dabei von der Melden-Hand zum
         sprechenden Mund, damit man auf einen Blick sieht, in
         welchem Zustand man ist.
         ============================================================= */
      const dauerSchalter = area.querySelector("#lcDauerSchalter");
      const sprachKnopfEl = area.querySelector("#lcSprachKnopf");
      function dauerZeichnen(an) {
        if (sprachKnopfEl) {
          sprachKnopfEl.classList.toggle("lc-spricht-dauernd", Boolean(an));
          sprachKnopfEl.title = an
            ? "Dauernd an — sprich einfach los, du kommst der Reihe nach dran"
            : "Melden: gedrückt halten und sprechen — du wirst gehört, sobald die Person vor dir fertig ist";
          sprachKnopfEl.setAttribute("aria-label", an ? "Dauerhaft sprechen ist an" : "Melden und sprechen");
        }
      }
      if (dauerSchalter) {
        if (!LiveChat.sprachGehtDas || !LiveChat.sprachGehtDas()) {
          dauerSchalter.disabled = true;
          const h = area.querySelector("#lcDauerHaken");
          if (h) h.title = "Dieser Browser kann keine Sprachnachrichten aufnehmen.";
        } else {
          dauerSchalter.checked = Boolean(LiveChat.freisprechenAn && LiveChat.freisprechenAn());
          dauerZeichnen(dauerSchalter.checked);
          dauerSchalter.addEventListener("change", async () => {
            if (!dauerSchalter.checked) {
              LiveChat.freisprechenBeenden();
              dauerZeichnen(false);
              showToast("✋ Wieder melden: halte den Knopf, wenn du etwas sagen willst.");
              return;
            }
            if (LiveChat.tonFreischalten) { try { LiveChat.tonFreischalten(); } catch (x) {} }
            const ok = await LiveChat.freisprechenStarten();
            dauerSchalter.checked = Boolean(ok);
            dauerZeichnen(ok);
            if (ok) showToast("🗣️ Dauernd an — sprich einfach los. Du kommst der Reihe nach dran.");
          });
        }
      }

      /* =============================================================
         DER OHR-KNOPF IST WEG — WAS ER KONNTE, KANN JETZT DAS SCHLOSS
         -------------------------------------------------------------
         GEMELDET: „Das eine Symbol ist ueberfluessig mit dem
         Kopfhoerer, weil das ja vorher dieselbe Funktion gehabt hat —
         das kannst du rausnehmen."

         Er hatte recht: Ohr-Knopf und Haken schalteten dasselbe.
         Geblieben ist der Haken, jetzt als Schloss. Und das eine, was
         nur der Ohr-Knopf konnte, sitzt jetzt auf dem Schloss: ein
         LANGER Druck schaltet den Mitschrieb um — also ob das
         Gesprochene auch im Chat steht, zum Nachlesen und
         Herunterladen.
         ============================================================= */
      const haltZeichen = area.querySelector("#lcDauerHaken");
      if (dauerSchalter && LiveChat.sprachGehtDas && LiveChat.sprachGehtDas()) {
        /* Angemeldet ist die Warteschlange laengst (weiter oben) —
           hier wird nur noch der Balken einmal nachgezogen. */
        lcLiveBalkenZeichnen();
        LiveChat.freisprechenMelden((was) => {
          /* Zwei Anzeigen fuer denselben Zustand, die auseinander
             laufen, sind schlimmer als eine: Haken und Symbol ziehen
             immer mit, egal worueber geschaltet wurde. */
          dauerSchalter.checked = (was !== "aus");
          dauerZeichnen(was !== "aus");
          if (haltZeichen) haltZeichen.classList.toggle("lc-halt-nimmt", was === "nimmt");
          if (was === "eicht") showToast("🎚️ Halten an — ich höre kurz zu, wie laut es bei dir ist.");
        });
        if (haltZeichen) {
          let mitTakt = 0;
          let lang = false;
          const mitschriebUmschalten = () => {
            lang = true;
            const neu = !lcMitschriebAn();
            lcMitschriebSetzen(neu);
            showToast(neu
              ? "📝 Sichtbar — was gesprochen wird, steht jetzt auch im Chat zum Nachhören und Herunterladen."
              : "📝 Unsichtbar — gesprochen wird nur noch gehört, der Chat bleibt lesbar.");
          };
          haltZeichen.addEventListener("pointerdown", () => {
            lang = false;
            mitTakt = setTimeout(mitschriebUmschalten, 650);
          });
          ["pointerup", "pointerleave", "pointercancel"].forEach((art) =>
            haltZeichen.addEventListener(art, () => { clearTimeout(mitTakt); }));
          /* Ein langer Druck darf den Haken NICHT mitschalten — sonst
             taete ein Druck zwei Dinge auf einmal. Das Klick-Ereignis
             kommt erst nach dem Loslassen, also greift die Sperre. */
          haltZeichen.addEventListener("click", (e) => {
            if (lang) { e.preventDefault(); lang = false; }
          });
        }
      }

      const feld = area.querySelector("#lcFeld");
      const senden = area.querySelector("#lcSenden");
      feld?.addEventListener("input", () => { senden.disabled = !feld.value.trim(); });
      area.querySelector("#lcForm")?.addEventListener("submit", (e) => {
        e.preventDefault();
        const t = feld.value.trim();
        if (!t) return;
        LiveChat.schreiben(t);
        feld.value = "";
        senden.disabled = true;
        lcNachDemSenden(t);
      });
      area.querySelector("#lcLinkKopieren")?.addEventListener("click", async (e) => {
        const link = LiveChat.lage().link;
        try { await navigator.clipboard.writeText(link); e.target.textContent = "✅ Kopiert"; }
        catch (x) { document.getElementById("lcLink")?.select(); e.target.textContent = "Markiert — jetzt kopieren"; }
        setTimeout(() => { e.target.textContent = "🔗 Link kopieren"; }, 2200);
      });
    }

    livechatKopfAuffrischen(l);
    livechatPlaetzeAuffrischen(l);
    livechatHintergrundAuffrischen(l);
    livechatChatAuffrischen(l);
    livechatGrossAuffrischen(l);
    /* „Die Zeile, wenn sie angewaehlt ist, die soll immer den Text an
       Platz halten" — also nach JEDEM Neuzeichnen die festgehaltene
       Lesetafel wieder ans Ende schieben, dorthin, wo der Chat
       gerade steht. */
    try { lcLeseTafelNachziehen(); } catch (e) {}
  }

  /* ============================================================
     DER STREIFEN: „DU BIST NOCH IM KLASSENZIMMER"
     ------------------------------------------------------------
     „Wie können wir wissen, dass wir noch im Klassenzimmer sind,
      wenn man sich weiterführende Inhalte anguckt?"

     Der Streifen hängt an <body>, nicht in einer Ansicht — er
     muss jeden Ansichtswechsel überleben. Gezeichnet wird er nur,
     wenn sich die Lage ändert; er hört auf denselben Zuhörer wie
     die Bilder im Raum.
     ============================================================ */
  let kzStreifen = null;
  function klassenzimmerStreifen() {
    if (!window.LiveChat) return;
    const l = LiveChat.lage();
    const drin = l.lage === "drin" || l.lage === "verbindet";
    document.body.classList.toggle("im-klassenzimmer", drin);

    if (!kzStreifen) {
      kzStreifen = document.createElement("div");
      kzStreifen.className = "kz-streifen";
      /* GEWUENSCHT: „Zwischen der kleinen Schrift ‚du bist allein da'
         und dem Zurück soll so ein ganz kleiner Mini-Knopf sein fuer
         das, wenn man was sagen will … und das Haekchen soll da
         sein, falls der Lehrer erlaubt, dass man frei spricht. Und
         rechts daneben bleibt dieser Zurückknopf und das
         Schliessen-Symbol."

         Genau diese Reihenfolge: Punkt, Text, Melden-Knopf, Haken,
         Zurück, Schliessen. Am Aufbau aendert sich sonst nichts. */
      kzStreifen.innerHTML =
        '<span class="kz-streifen-punkt" aria-hidden="true"></span>' +
        '<span class="kz-streifen-text" id="kzStreifenText"></span>' +
        '<button type="button" class="kz-melden" id="kzMelden"' +
        '  title="Gedrückt halten und sprechen — auch von hier aus"' +
        '  aria-label="Melden und sprechen">' +
        '  <svg class="kz-melden-hand" viewBox="0 0 24 24" width="15" height="15" aria-hidden="true">' +
        '    <path d="M10.2 11.4V4.6a1.35 1.35 0 0 1 2.7 0v6.1" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/>' +
        '    <path d="M12.9 10.9V6.9a1.3 1.3 0 0 1 2.6 0v4.6" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/>' +
        '    <path d="M15.5 11.5V8.6a1.3 1.3 0 0 1 2.6 0v5.2c0 3.6-2.3 6.2-5.6 6.2-2.4 0-3.9-1-5.1-2.9L5 13.4a1.35 1.35 0 0 1 2.2-1.6l1.2 1.6" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/>' +
        '    <path d="M8.4 13.4V9.5a1.3 1.3 0 0 1 2.6 0v2" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/>' +
        '  </svg>' +
        '  <svg class="kz-melden-mund" viewBox="0 0 24 24" width="15" height="15" aria-hidden="true">' +
        '    <path d="M3.4 10.2h12c0 4.3-2.7 7.1-6 7.1s-6-2.8-6-7.1z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>' +
        '    <path d="M3.4 10.2c1.8-1 3.8-1.5 6-1.5s4.2.5 6 1.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>' +
        '    <path d="M17.6 10.2a3.4 3.4 0 0 1 0 4.4" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>' +
        '    <path d="M20.4 8.6a6.4 6.4 0 0 1 0 7.6" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>' +
        '  </svg>' +
        '</button>' +
        '<label class="kz-dauer" id="kzDauer" title="Halten: das Mikrofon bleibt an">' +
        '  <input type="checkbox" id="kzDauerSchalter"><span aria-hidden="true"></span>' +
        '</label>' +
        '<button type="button" class="kz-streifen-zurueck" id="kzStreifenZurueck">Zurück</button>' +
        '<button type="button" class="kz-streifen-weg" id="kzStreifenWeg" aria-label="Klassenzimmer verlassen" title="Klassenzimmer verlassen">✕</button>';
      document.body.appendChild(kzStreifen);
      /* EIN Tipp bringt zurück — nicht zwei, nicht über ein Menü. */
      kzStreifen.querySelector("#kzStreifenZurueck").addEventListener("click", () => {
        document.querySelector('[data-target="view-knowledge"]')?.click();
        setTimeout(() => {
          document.querySelector('#knowledgeSubnav [data-sub="sub-livechat"]')?.click();
          livechatInsBild();
        }, 80);
      });
      kzStreifen.querySelector("#kzStreifenWeg").addEventListener("click", () => {
        LiveChat.verlassen();
        renderLiveChat();
        klassenzimmerStreifen();
      });
      /* Melden von unterwegs: halten und sprechen, genau wie im
         Klassenzimmer. Man muss also nicht erst zurueckspringen,
         nur um einen Satz zu sagen. */
      const kzM = kzStreifen.querySelector("#kzMelden");
      let kzLaeuft = false;
      const kzAn = async (e) => {
        if (e) e.preventDefault();
        if (kzLaeuft || !LiveChat.sprachAufnahmeStarten) return;
        if (LiveChat.binStumm && LiveChat.binStumm()) {
          showToast("🤐 Deine Stimme ist gerade stummgeschaltet — schreib im Chat Bescheid.");
          return;
        }
        kzLaeuft = await LiveChat.sprachAufnahmeStarten();
        kzM.classList.toggle("kz-melden-an", kzLaeuft);
      };
      const kzAus = (e) => {
        if (e) e.preventDefault();
        if (!kzLaeuft) return;
        kzLaeuft = false;
        kzM.classList.remove("kz-melden-an");
        LiveChat.sprachAufnahmeStoppen({ live: true });
      };
      kzM.addEventListener("pointerdown", kzAn);
      ["pointerup", "pointercancel", "pointerleave"].forEach((a) => kzM.addEventListener(a, kzAus));
      kzM.addEventListener("contextmenu", (e) => e.preventDefault());
      const kzD = kzStreifen.querySelector("#kzDauerSchalter");
      kzD.addEventListener("change", async () => {
        if (!kzD.checked) { LiveChat.freisprechenBeenden(); return; }
        if (LiveChat.tonFreischalten) { try { LiveChat.tonFreischalten(); } catch (x) {} }
        const ok = await LiveChat.freisprechenStarten();
        kzD.checked = Boolean(ok);
      });
    }

    kzStreifen.classList.toggle("kz-an", drin);
    if (!drin) return;
    /* Nicht anzeigen, während man ohnehin darin steht — sonst
       verdeckt der Streifen das Chatfeld, in das man gerade
       schreibt. */
    const offen = document.getElementById("sub-livechat")?.dataset.active === "true"
               && document.getElementById("view-knowledge")?.dataset.active === "true";
    kzStreifen.classList.toggle("kz-an", drin && !offen);

    const da = LiveChat.PLAETZE - l.frei;
    /* GEMELDET: „Wenn ich einen eigenen Raum aufgemacht habe, steht
       unten in der Miniaturpille nicht der Name von meinem eigenen
       Raum, sondern immer noch, dass ich im Klassenzimmer bin."

       Hier stand der Text fest im Code. Jetzt steht da, wo man
       wirklich ist: im Hauptraum „Im Klassenzimmer", sonst der Name
       des Raums.

       NACHGEBESSERT: „Da soll nicht stehen ‚im Raum‘, weil es bei
       Klassenzimmer ja auch nicht steht — sondern ‚im‘ und der Name
       des Raums. Und je nach Wort: nennt man den Raum Weihnachten,
       soll der richtige Artikel erkannt werden, dass man nicht ‚im
       Weihnachten‘ sagt, sondern ‚in Weihnachten‘."

       Das Wort „Raum" und die Anführungszeichen sind also weg, und
       ob „im", „in der" oder ein blosses „in" davorsteht, entscheidet
       lcRaumOrt() am Artikel des Namens. */
    const wo = lcRaumOrt(l.raum, l.raumName);
    const kopf = document.getElementById("kzStreifenText");
    kopf.textContent = "";
    const fett = document.createElement("strong");
    fett.textContent = wo;
    const klein = document.createElement("small");
    klein.textContent = l.lage === "verbindet" ? "verbindet \u2026"
      : da === 1 ? "du bist allein da" : da + " Leute da";
    kopf.appendChild(fett);
    kopf.appendChild(klein);

    /* Melden-Knopf und Haken mitziehen: dauernd an = sprechender
       Mund, stummgeschaltet = Knopf gesperrt. */
    const dauerAn = Boolean(LiveChat.freisprechenAn && LiveChat.freisprechenAn());
    const stumm = Boolean(LiveChat.binStumm && LiveChat.binStumm());
    const mKnopf = document.getElementById("kzMelden");
    const mHaken = document.getElementById("kzDauerSchalter");
    if (mKnopf) {
      mKnopf.classList.toggle("kz-melden-dauernd", dauerAn);
      mKnopf.disabled = stumm;
      mKnopf.title = stumm ? "Deine Stimme ist stummgeschaltet"
        : dauerAn ? "Halten ist an — sprich einfach los"
        : "Gedrückt halten und sprechen — auch von hier aus";
    }
    if (mHaken && mHaken.checked !== dauerAn) mHaken.checked = dauerAn;
  }

  /* Ein einziger Zuhörer für das ganze Leben der Seite. Die
     Anzeige wird nur aufgefrischt, wenn der Bereich auch offen
     ist — sonst rechnet die Seite im Hintergrund an einer
     Ansicht, die niemand sieht. Die VERBINDUNG bleibt bestehen:
     wer weiterblättert, bleibt im Raum. */
  if (window.LiveChat && !livechatAbmelden) {
    livechatAbmelden = LiveChat.beiAenderung(() => {
      if (document.getElementById("sub-livechat")?.dataset.active === "true") renderLiveChat();
      klassenzimmerStreifen();
    });
    /* Jeder Ansichtswechsel entscheidet neu, ob der Streifen zu
       sehen ist: im Klassenzimmer selbst wäre er nur im Weg. */
    document.addEventListener("click", (e) => {
      if (e.target.closest(".subnav-pill, .tape-tab")) setTimeout(klassenzimmerStreifen, 60);
    }, true);
    klassenzimmerStreifen();

    /* Nach dem Neuladen zurück in den Raum — ohne Nachfrage, weil
       der Browser die Kameraerlaubnis noch hat und weil genau das
       gewünscht war: „bleibt man dann auch im Klassenzimmer?" */
    const zurueck = LiveChat.rueckkehrOffen && LiveChat.rueckkehrOffen();
    if (zurueck) {
      LiveChat.betreten(zurueck.raum, { name: zurueck.name || livechatName(),
        betreiber: Boolean(Backend.canModerate && Backend.canModerate()),
        geschlecht: livechatGeschlecht(),
        mitBild: zurueck.mitBild !== false })
        .then(() => { klassenzimmerStreifen(); renderLiveChat(); });
    }
  }
  /* GEWÜNSCHT: „wenn man oben auf Klassenzimmer klickt … der Chat mit
     seinem unteren Ende soll in einem Bild auf dem Bildschirm zu sehen
     sein." */
  document.querySelector('#knowledgeSubnav [data-sub="sub-livechat"]')?.addEventListener("click", () => {
    renderLiveChat();
    /* Das Ausrichten der Karte macht wireSubnav — EINE Stelle, ein
       Ergebnis. Hier wird nur noch der Verlauf selbst ans Ende
       gezogen, damit man beim Hereinkommen das Neueste sieht. */
    lcHaeltUnten = true;
    lcEndeNachziehen();
  });


  /* ============================================================
     LOGIK-TRAINER
     ------------------------------------------------------------
     Der Anlass war eine genaue Beobachtung: Leute antworten im
     Gespräch mit „ja, ja“ und „genau“ und haben nichts verstanden.
     Sie lesen Wörter als Ganzes und raten aus dem Zusammenhang.

     Hier wird das Gegenteil geübt — ein Wort auseinandernehmen:
       · Welches bekannte Wort steckt in „Verkäuferin“?
       · Welches Glied bestimmt bei „Krankenhaus“ Artikel und
         Grundbedeutung?
       · Was sagt die Vorsilbe von „abholen“ über die Richtung?

     Wer das einmal sieht, muss viel weniger auswendig lernen: aus
     einem Wortstamm und sechs Vorsilben werden Dutzende Wörter,
     deren Bedeutung man sich herleiten kann.
     ============================================================ */
  const LOGIK_RUNDEN = 10;
  let logikSitzung = null;
  let logikArt = "gemischt";   // gemischt | stamm | kompositum | richtung
  let logikGeladen = null;
  function logikLaden() {
    if (window.DMA_DATEN && window.DMA_DATEN.LOGIK_STAMM) return Promise.resolve(true);
    if (logikGeladen) return logikGeladen;
    logikGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-logik.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { logikGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return logikGeladen;
  }
  const LOGIK_ARTEN = {
    gemischt: "🎲 Gemischt", stamm: "🌱 Welches Wort steckt drin?",
    kompositum: "🧱 Zusammengesetzte Wörter", richtung: "🧭 Vorsilben & Richtung",
  };
  /* Aus den Rohdaten werden die Aufgaben hier gebaut — bei den
     Zusammensetzungen aus dem Muster, bei den anderen beiden direkt
     aus den kuratierten Zeilen. */
  function logikAufgaben() {
    const D = window.DMA_DATEN || {};
    const raus = [];
    (D.LOGIK_STAMM || []).forEach(([wort, stamm, falsch, erkl, level]) => {
      raus.push({ art: "stamm", frage: `Welches Wort steckt in „${wort}“?`, richtig: stamm, falsch, erkl, level });
    });
    (D.LOGIK_KOMPOSITA || []).forEach(([wort, bestimmung, grund, artikel, sagt, level]) => {
      const rein = wort.replace(/^(der|die|das)\s+/, "");
      raus.push({ art: "kompositum",
        frage: `Welches Glied bestimmt bei „${rein}“ den Artikel und die Grundbedeutung?`,
        richtig: grund,
        falsch: [bestimmung, rein, artikel + " " + bestimmung],
        erkl: `Bei zusammengesetzten Wörtern entscheidet IMMER das letzte Glied: „${rein}“ ist ${artikel === "der" ? "ein" : artikel === "die" ? "eine" : "ein"} ${grund}. Das erste Glied „${bestimmung}“ sagt nur, ${sagt}.`,
        level });
      raus.push({ art: "kompositum",
        frage: `Was sagt das erste Glied „${bestimmung}“ bei „${rein}“?`,
        richtig: sagt,
        falsch: ["Es bestimmt den Artikel des ganzen Wortes.",
          "Es hat keine eigene Bedeutung.",
          "Es macht das Wort zur Mehrzahl."],
        erkl: `Das erste Glied beschreibt genauer — es sagt ${sagt}. Den Artikel bestimmt dagegen das letzte Glied „${grund}“: ${artikel} ${rein}.`,
        level });
    });
    (D.LOGIK_RICHTUNG || []).forEach(([verb, richtig, falsch, erkl, level]) => {
      raus.push({ art: "richtung", frage: `Was bedeutet „${verb}“ genau — welche Richtung steckt darin?`, richtig, falsch, erkl, level });
    });
    return raus;
  }
  function neueLogikSitzung() {
    let pool = logikAufgaben();
    if (logikArt !== "gemischt") pool = pool.filter((a) => a.art === logikArt);
    /* Nach Niveau vorsortieren, aber nicht hart abschneiden: sonst
       bliebe für A1 fast nichts übrig. Passende zuerst, der Rest
       füllt auf. */
    const stufen = ["A1", "A2", "B1", "B2", "C1", "C2"];
    const meins = stufen.indexOf(logikNiveau);
    const passend = pool.filter((a) => stufen.indexOf(a.level) <= meins);
    const quelle = passend.length >= LOGIK_RUNDEN ? passend : pool;
    logikSitzung = {
      aufgaben: Core.shuffle(quelle).slice(0, LOGIK_RUNDEN),
      index: 0, richtig: 0, beantwortet: null,
    };
  }
  let logikNiveau = null;
  async function renderLogik() {
    autoWeiterAbbrechen();
    const area = document.getElementById("logikArea");
    if (!area) return;
    if (!(window.DMA_DATEN && window.DMA_DATEN.LOGIK_STAMM)) {
      area.innerHTML = '<p class="empty-note">Der Logik-Trainer wird geladen …</p>';
      const ok = await logikLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Der Logik-Trainer konnte nicht geladen werden.</p>'; return; }
    }
    logikNiveau = applyDefaultCefrLevel(logikNiveau, (v) => { logikNiveau = v; }, "logik");
    if (!logikSitzung) {
      const anzahl = logikAufgaben().filter((a) => logikArt === "gemischt" || a.art === logikArt).length;
      area.innerHTML = `
        <div class="question-card">
          <p class="eyebrow">🧠 LOGIK-TRAINER</p>
          <p class="empty-note" style="margin-bottom:12px;">
            Nicht auswendig lernen, sondern sehen, wie ein Wort gebaut ist. Wer erkennt, dass in
            „Verkäuferin“ das Verb „verkaufen“ steckt, dass beim „Krankenhaus“ das <strong>Haus</strong>
            das Grundwort ist und dass „ab-“ in „abholen“ eine Richtung angibt, muss die Hälfte
            nicht mehr auswendig können — er kann sie sich herleiten.
          </p>
          <p class="eyebrow">WAS MÖCHTEST DU ÜBEN?</p>
          <div class="trophy-case" style="margin-bottom:12px;">
            ${Object.entries(LOGIK_ARTEN).map(([k, name]) => `<button type="button" class="trophy-chip logik-art-btn ${logikArt === k ? "selected" : ""}" data-logik-art="${k}">${name}</button>`).join("")}
          </div>
          <p class="eyebrow">SPRACHNIVEAU</p>
          <div class="trophy-case" style="margin-bottom:12px;">
            ${["A1", "A2", "B1", "B2", "C1", "C2"].map((l) => `<button type="button" class="trophy-chip logik-level-btn ${logikNiveau === l ? "selected" : ""}" data-logik-level="${l}">${l}</button>`).join("")}
          </div>
          <p class="empty-note" style="margin-bottom:12px;">${anzahl} Aufgaben stehen bereit — eine Runde geht über ${LOGIK_RUNDEN}.</p>
          <button type="button" class="btn btn-coffee" id="logikStart">▶ Runde starten</button>
        </div>`;
      area.querySelectorAll(".logik-art-btn").forEach((b) => b.addEventListener("click", () => { logikArt = b.dataset.logikArt; renderLogik(); }));
      area.querySelectorAll(".logik-level-btn").forEach((b) => b.addEventListener("click", () => { logikNiveau = b.dataset.logikLevel; autoCefrLevel.logik = null; renderLogik(); }));
      document.getElementById("logikStart").addEventListener("click", () => { neueLogikSitzung(); renderLogik(); });
      return;
    }
    const s = logikSitzung;
    if (s.index >= s.aufgaben.length) { renderLogikErgebnis(); return; }
    const a = s.aufgaben[s.index];
    const optionen = s.beantwortet ? s.beantwortet.optionen : Core.shuffle([a.richtig, ...a.falsch]);
    if (!s.beantwortet) s.optionen = optionen;
    area.innerHTML = `
      <div class="question-card">
        <p class="eyebrow">🧠 LOGIK-TRAINER · RUNDE ${s.index + 1} / ${s.aufgaben.length} · ${LOGIK_ARTEN[a.art] || ""}</p>
        ${fortschrittHtml(s.index, s.aufgaben.length)}
        <p class="question-prompt" style="margin:10px 0 14px;">${a.frage}</p>
        <div class="option-list">
          ${(s.optionen || optionen).map((opt, i) => {
            const gewaehlt = s.beantwortet && s.beantwortet.gewaehlt === opt;
            const istRichtig = opt === a.richtig;
            const zustand = !s.beantwortet ? "" : istRichtig ? " option-correct" : gewaehlt ? " option-wrong" : "";
            return `<button type="button" class="option-btn logik-opt${zustand}" data-logik-opt="${i}" ${s.beantwortet ? "disabled" : ""}><span>${opt}</span></button>`;
          }).join("")}
        </div>
        ${s.beantwortet ? `
          <div class="witz-erklaerung" style="margin-top:12px;">
            <p style="margin:0;">${s.beantwortet.gewaehlt === a.richtig ? "✅ " : "❌ "}${a.erkl}</p>
          </div>
          <div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="logikWeiter">Weiter ▸</button>
          </div>` : ""}
        ${miniBugReportBtnHtml("Logik-Trainer: " + a.frage)}
      </div>`;
    area.querySelectorAll(".logik-opt").forEach((b) => b.addEventListener("click", () => {
      const opt = (s.optionen || optionen)[Number(b.dataset.logikOpt)];
      const stimmt = opt === a.richtig;
      if (stimmt) { s.richtig += 1; Core.sound.correct(); } else Core.sound.wrong();
      spielNotiz(stimmt, `${a.frage} → ${a.richtig}`);
      s.beantwortet = { gewaehlt: opt, optionen: s.optionen || optionen };
      renderLogik();
    }));
    const logikNaechste = () => { s.index += 1; s.beantwortet = null; s.optionen = null; renderLogik(); };
    document.getElementById("logikWeiter")?.addEventListener("click", () => { autoWeiterAbbrechen(); logikNaechste(); });
    if (s.beantwortet) autoWeiter(s.beantwortet.gewaehlt === a.richtig, logikNaechste);
  }
  function renderLogikErgebnis() {
    const area = document.getElementById("logikArea");
    const s = logikSitzung;
    const prozent = Math.round((s.richtig / s.aufgaben.length) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.richtig, prozent: prozent, tier: "Wortdetektiv:in",
      charakter: "Logik-Trainer", zeilen: [{ name: "🧠 Richtig erkannt", anteil: prozent, wert: s.richtig + "/" + s.aufgaben.length }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="logikNochmal">🔄 Noch eine Runde</button><button type="button" class="btn btn-ghost" id="logikZurueck">Andere Art wählen</button>`,
    });
    saveResultAndCheck({
      categories: ["logik"], titelText: "Logik-Trainer",
      points: s.richtig, bonus: prozent === 100 ? 3 : 0, percent: prozent,
      character: "Wortdetektiv:in", badges: [], playedAt: new Date().toISOString(),
    });
    document.getElementById("logikNochmal").addEventListener("click", () => { neueLogikSitzung(); renderLogik(); });
    document.getElementById("logikZurueck").addEventListener("click", () => { logikSitzung = null; renderLogik(); });
  }
  document.querySelector('#learnSubnav [data-sub="sub-logik"]')?.addEventListener("click", () => renderLogik());

  /* ============================================================
     AUSSPRACHE-KURS
     ------------------------------------------------------------
     GEWÜNSCHT: „Das Alphabet wurde auch noch nicht behandelt …
     mit den Umlauten und den Regeln, das mit dem Dehnungs-h und
     dem E nach dem I … wenn ein Konsonant nach einem Vokal steht,
     dass der Vokal lang gesprochen wird … die Ausnahmen davon …
     dass sie nicht SETR sagen, sondern Straße … Tricks, wie man
     ein sauberes Ü nachfüllen kann, vom I, indem man einen
     Kussmund macht … das mit dem NG richtig erklärt, mit einer
     grafischen Darstellung."

     Sechs Teile, jeder für sich benutzbar:
       Alphabet      — jeder Buchstabe einzeln, antippen = hören
       Buchstabenpaare — ch, sch, ie, ng … zwei Zeichen, ein Laut
       Regeln        — Vokallänge, Dehnungs-h, ie, ß/ss, Betonung
       Bündel        — Konsonanten am Stück, ohne Zwischenvokal
       Tricks        — wie man einen Laut körperlich herstellt
       Test          — zählt auf das Punktekonto

     Alles gibt es auf Deutsch UND auf Italienisch, jeweils mit
     den Regeln, die für diese Sprache wirklich gelten.
     ============================================================ */
  let ausspracheKursGeladen = null;
  function ausspracheKursLaden() {
    /* Die Sprachtabelle gleich mitholen: die kleine Übersetzungszeile
       unter den Beispielwörtern zieht ihre acht Sprachen daraus. Ohne
       das stünde dort nur Englisch. */
    wortSprachenLaden();
    if (window.DMA_AUSSPRACHE) return Promise.resolve(true);
    if (ausspracheKursGeladen) return ausspracheKursGeladen;
    ausspracheKursGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-aussprache.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { ausspracheKursGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return ausspracheKursGeladen;
  }

  const AK_TEILE = {
    alphabet: "🔤 Alphabet",
    verbindungen: "🔗 Zwei Zeichen, ein Laut",
    regeln: "📏 Regeln",
    buendel: "🧱 Konsonanten am Stück",
    tricks: "🎯 Tricks",
    test: "✅ Test",
  };
  let akTeil = "alphabet";
  let akSprache = null;        // null = die Sprache des Raums
  let akTest = null;

  function akAktuelleSprache() {
    /* Kein Umschalter mehr im Kurs selbst — der Raum entscheidet. */
    return imItalienischraum() ? "it" : "de";
  }
  function akDaten(feld) {
    const A = window.DMA_AUSSPRACHE || {};
    return (A[feld] && A[feld][akAktuelleSprache()]) || [];
  }
  /* Ein Wort anzeigen: mit Betonungsmarke, wenn eine Silbenangabe
     dabei ist, sonst schlicht. Die Marke folgt derselben Stelle wie
     überall sonst auf der Seite — im Italienisch-Raum also ohne
     Längsstrich, den es dort nicht gibt. */
  /* Den ersten echten Buchstaben (also nicht innerhalb eines Tags)
     wieder kleinschreiben. Die Betonungsanzeige schreibt die erste
     Silbe immer groß — im Wörterbuch stimmt das, weil dort Nomen
     stehen. Hier stehen auch Verben und Adjektive: „singen“, „lang“,
     „früh“ dürfen kein großes S, L oder F bekommen. */
  function akErsteKlein(html) {
    let imTag = false;
    for (let i = 0; i < html.length; i++) {
      const c = html[i];
      if (c === "<") { imTag = true; continue; }
      if (c === ">") { imTag = false; continue; }
      if (imTag) continue;
      if (/[A-Za-zÄÖÜäöüß]/.test(c)) {
        return html.slice(0, i) + c.toLowerCase() + html.slice(i + 1);
      }
    }
    return html;
  }
  function akWort(wort, syl) {
    const text = String(wort);
    if (!syl) return text;
    let gezeigt = akAktuelleSprache() === "it" ? Core.formatStressIt(syl) : Core.formatStress(syl);
    /* Der Artikel steht im Wort, nicht in der Silbenangabe — er kommt
       davor zurück. Das Leerzeichen ist Pflicht: sonst hätte „lang“
       als Artikel „la“ gegolten und wäre zu „la Lang“ geworden. */
    const artikel = text.match(/^(?:(?:der|die|das|il|lo|la|i|gli|le)\s|l['’])/i);
    const rest = artikel ? text.slice(artikel[0].length) : text;
    if (rest && rest[0] === rest[0].toLowerCase() && rest[0] !== rest[0].toUpperCase()) {
      gezeigt = akErsteKlein(gezeigt);
    }
    return (artikel ? artikel[0] : "") + gezeigt;
  }
  /* Ein Lautsprecher-Knopf. Die Sprache steht am Knopf selbst — sonst
     läse die deutsche Stimme die italienischen Sätze vor. */
  function sprichKnopfHtml(text, sprache, titel) {
    return `<button type="button" class="btn btn-ghost ak-hoer"
      data-ak-sprich="${String(text).replace(/"/g, "&quot;")}" data-ak-lang="${sprache || "de"}"
      aria-label="${titel || "anhören"}" title="${titel || "anhören"}">🔊</button>`;
  }
  function akHoerKnopf(text, titel) {
    return sprichKnopfHtml(text, akAktuelleSprache(), titel);
  }

  function akKopfHtml() {
    const spr = akAktuelleSprache();
    return `
      <div class="question-card ak-kopf">
        <p class="eyebrow">🗣️ AUSSPRACHE-KURS</p>
        <p class="empty-note" style="margin-bottom:10px;">
          Lesen kann man erst, wenn man weiß, wie die Buchstaben klingen. Hier steht das komplette
          Alphabet, dazu die Regeln, die einem sagen, ob ein Vokal lang oder kurz ist — und die
          Tricks für die Laute, die es in der eigenen Muttersprache nicht gibt.
          Jedes Wort lässt sich antippen und anhören.
        </p>
        ${/* GEWÜNSCHT: „achte darauf, dass da nicht mehr steht ‚Italienisch'
              zum Umschalten — das ist ein deutscher Kurs. Im Italienischkurs
              kannst du die Sachen machen, die zum Italienischkurs gehören, aber
              im Deutsch-Aussprachekurs hat diese italienische Schaltfläche
              nichts zu suchen."

              Der Umschalter ist deshalb ganz weg. Welche Sprache der Kurs
              zeigt, entscheidet allein der Raum, in dem man sich befindet —
              und den wählt Alex für sich selbst in den Einstellungen. */ ""}
        <div class="trophy-case">
          ${Object.entries(AK_TEILE).map(([k, name]) =>
            `<button type="button" class="trophy-chip ak-teil-btn ${akTeil === k ? "selected" : ""}" data-ak-teil="${k}">${name}</button>`).join("")}
        </div>
        ${/* GEMELDET: „Die eingebaute Stimme spricht manches falsch —
              ‚Bonbons‘, das Z.“ Hier ist die richtige Stelle dafür: wer
              gerade Aussprache lernt, muss wissen, dass die Maschine, die
              ihm vorliest, selbst raten muss. Die ausführliche Fassung —
              eingeklappt, damit sie den Kurs nicht zudeckt. */ ""}
        ${stimmenHinweisHtml(false)}
      </div>`;
  }

  function akAlphabetHtml() {
    const spr = akAktuelleSprache();
    const zeilen = akDaten("ALPHABET");
    const einleitung = spr === "it"
      ? "Das italienische Alphabet hat nur 21 Buchstaben. j, k, w, x und y stehen nur in Fremdwörtern. Tippe einen Buchstaben an, dann hörst du seinen Namen und das Beispielwort."
      : "26 Buchstaben, dazu die drei Umlaute und das ß. Tippe einen Buchstaben an, dann hörst du seinen Namen und das Beispielwort.";
    return `
      <div class="question-card">
        <p class="eyebrow">${spr === "it" ? "L’ALFABETO" : "DAS ALPHABET"}</p>
        <p class="empty-note" style="margin-bottom:12px;">${einleitung}</p>
        <div class="ak-gitter">
          ${zeilen.map((z, i) => `
            <div class="ak-buchstabe" data-ak-buchstabe="${i}">
              <div class="ak-b-kopf">
                <span class="ak-b-zeichen">${z.b}</span>
                <span class="ak-b-name">${z.name}</span>
              </div>
              <p class="ak-b-ipa">[${z.ipa}]</p>
              <p class="ak-b-laut">${z.laut}</p>
              <p class="ak-b-bsp">${akWort(z.bsp, z.syl)} ${akHoerKnopf(z.bsp, "„" + z.bsp + "“ anhören")}</p>
              ${spr === "de" ? kleineUebersetzung(z.bsp) : ""}
              ${z.hinweis ? `<p class="ak-b-hinweis">${z.hinweis}</p>` : ""}
            </div>`).join("")}
        </div>
      </div>`;
  }

  function akVerbindungenHtml() {
    const zeilen = akDaten("VERBINDUNGEN");
    return `
      <div class="question-card">
        <p class="eyebrow">ZWEI ZEICHEN, EIN LAUT</p>
        <p class="empty-note" style="margin-bottom:12px;">
          Manche Buchstaben stehen nie allein. Erst zusammen ergeben sie einen einzigen Laut —
          und der hat oft nichts mit den einzelnen Buchstaben zu tun.
        </p>
        <div class="ak-liste">
          ${zeilen.map((z) => `
            <div class="ak-verb">
              <div class="ak-verb-kopf">
                <span class="ak-verb-schrift">${z.schrift}</span>
                <span class="ak-verb-pfeil">→</span>
                <span class="ak-verb-laut">${z.gesprochen}</span>
              </div>
              <p class="ak-verb-wann">${z.wann}</p>
              <p class="ak-verb-bsp">${z.bsp.map((w) => `<span class="ak-chip">${w} ${akHoerKnopf(w)}</span>`).join("")}</p>
              ${akAktuelleSprache() === "de" ? kleineSatzHilfeHtml(z.bsp.join(" ")) : ""}
              ${z.hinweis ? `<p class="ak-b-hinweis">${z.hinweis}</p>` : ""}
            </div>`).join("")}
        </div>
      </div>`;
  }

  function akRegelnHtml() {
    const zeilen = akDaten("REGELN");
    return zeilen.map((r) => `
      <div class="question-card ak-regel">
        <p class="eyebrow">${r.titel}</p>
        ${r.svg || ""}
        <p class="empty-note" style="margin:10px 0 12px;">${r.text}</p>
        <div class="ak-bsp-gitter">
          ${(r.beispiele || []).map((b) => `
            <div class="ak-bsp">
              <span class="ak-bsp-wort">${akWort(b.wort, b.syl)}</span>
              ${akHoerKnopf(b.wort)}
              ${b.hinweis ? `<span class="ak-bsp-hinweis">${b.hinweis}</span>` : ""}
              ${akAktuelleSprache() === "de" ? kleineUebersetzung(b.wort) : ""}
            </div>`).join("")}
        </div>
        ${r.ausnahmen && (r.ausnahmen.text || (r.ausnahmen.woerter || []).length) ? `
          <div class="ak-ausnahme">
            <p class="ak-ausnahme-titel">⚠️ Ausnahmen</p>
            ${r.ausnahmen.text ? `<p>${r.ausnahmen.text}</p>` : ""}
            ${(r.ausnahmen.woerter || []).length ? `<p class="ak-ausnahme-woerter">${r.ausnahmen.woerter.map((w) => `<span class="ak-chip">${w}</span>`).join("")}</p>` : ""}
          </div>` : ""}
      </div>`).join("");
  }

  function akBuendelHtml() {
    const zeilen = akDaten("BUENDEL");
    const brecher = akDaten("ZUNGENBRECHER");
    const spr = akAktuelleSprache();
    const einleitung = spr === "it"
      ? "Auch im Italienischen stehen Konsonanten am Stück — und anders als im Deutschen bleibt das s dabei scharf: „la strada“, nicht „schtrada“."
      : "Im Arabischen, Türkischen, Persischen und Spanischen schiebt die Zunge von selbst einen kleinen Vokal zwischen zwei Konsonanten. Im Deutschen gibt es diesen Vokal nicht. Trick: von hinten aufbauen — „raße“, „traße“, „schtraße“.";
    return `
      <div class="question-card">
        <p class="eyebrow">KONSONANTEN AM STÜCK</p>
        <p class="empty-note" style="margin-bottom:12px;">${einleitung}</p>
        ${spr === "de" ? ((window.DMA_AUSSPRACHE.GRAFIK || {}).buendel || "") : ""}
        <div class="ak-liste">
          ${zeilen.map((z) => `
            <div class="ak-buendel">
              <div class="ak-verb-kopf">
                <span class="ak-verb-schrift">${z.schrift}</span>
                <span class="ak-verb-pfeil">→</span>
                <span class="ak-verb-laut">${z.gesprochen}</span>
              </div>
              <p class="ak-buendel-richtig">✅ ${akWort(z.bsp, z.syl)} ${akHoerKnopf(z.bsp)}</p>
              ${spr === "de" ? kleineUebersetzung(z.bsp) : ""}
              <p class="ak-buendel-falsch">❌ ${z.falsch}</p>
              <p class="ak-verb-bsp">${(z.weitere || []).map((w) => `<span class="ak-chip">${w} ${akHoerKnopf(w)}</span>`).join("")}</p>
            </div>`).join("")}
        </div>
      </div>
      <div class="question-card">
        <p class="eyebrow">ZUM LAUT SPRECHEN</p>
        <p class="empty-note" style="margin-bottom:12px;">Erst langsam, dann schneller. Jeder Satz übt genau eine Schwierigkeit.</p>
        <div class="ak-liste">
          ${brecher.map((b) => `
            <div class="ak-brecher">
              <p class="ak-brecher-satz">${b.satz} ${akHoerKnopf(b.satz)}</p>
              ${spr === "de" ? kleineSatzHilfeHtml(b.satz) : ""}
              <p class="ak-b-hinweis">übt: ${b.uebt}</p>
            </div>`).join("")}
        </div>
      </div>`;
  }

  function akTricksHtml() {
    const zeilen = akDaten("TRICKS");
    return zeilen.map((t) => `
      <div class="question-card ak-trick">
        <p class="eyebrow">${t.titel}</p>
        <p class="empty-note" style="margin-bottom:12px;">${t.worum}</p>
        ${t.svg || ""}
        <ol class="ak-schritte">
          ${(t.schritte || []).map((s) => `<li>${s}</li>`).join("")}
        </ol>
        ${t.svg2 || ""}
        <div class="ak-bsp-gitter">
          ${(t.beispiele || []).map((b) => `
            <div class="ak-bsp">
              <span class="ak-bsp-wort">${akWort(b.wort, b.syl)}</span>
              ${akHoerKnopf(b.wort)}
              ${b.hinweis ? `<span class="ak-bsp-hinweis">${b.hinweis}</span>` : ""}
            </div>`).join("")}
        </div>
        ${t.probe ? `<div class="ak-probe"><p>🎧 ${t.probe}</p></div>` : ""}
      </div>`).join("");
  }

  const AK_TEST_RUNDEN = 10;
  function neuerAkTest() {
    const pool = akDaten("TEST");
    akTest = {
      aufgaben: Core.shuffle(pool).slice(0, Math.min(AK_TEST_RUNDEN, pool.length)),
      index: 0, richtig: 0, beantwortet: null, optionen: null,
      sprache: akAktuelleSprache(),
    };
  }
  function akTestHtml() {
    const pool = akDaten("TEST");
    if (!akTest || akTest.sprache !== akAktuelleSprache()) {
      const teile = [...new Set(pool.map((t) => t.teil))];
      return `
        <div class="question-card">
          <p class="eyebrow">TEST</p>
          <p class="empty-note" style="margin-bottom:12px;">
            ${AK_TEST_RUNDEN} Fragen aus allem, was auf dieser Seite steht — Alphabet, Vokallänge,
            Konsonantenbündel, Betonung. Jede richtige Antwort zählt auf dein Punktekonto.
          </p>
          <p class="empty-note" style="margin-bottom:12px;">Bereiche: ${teile.join(" · ")} · ${pool.length} Fragen stehen bereit.</p>
          <button type="button" class="btn btn-coffee" id="akTestStart">▶ Test starten</button>
        </div>`;
    }
    const s = akTest;
    if (s.index >= s.aufgaben.length) return "";
    const a = s.aufgaben[s.index];
    const optionen = s.optionen || Core.shuffle([a.richtig, ...a.falsch]);
    s.optionen = optionen;
    return `
      <div class="question-card">
        <p class="eyebrow">TEST · FRAGE ${s.index + 1} / ${s.aufgaben.length} · ${a.teil}</p>
        ${fortschrittHtml(s.index, s.aufgaben.length)}
        <p class="question-prompt" style="margin:10px 0 14px;">${a.frage}</p>
        <div class="option-list">
          ${optionen.map((opt, i) => {
            const gewaehlt = s.beantwortet && s.beantwortet.gewaehlt === opt;
            const istRichtig = opt === a.richtig;
            const zustand = !s.beantwortet ? "" : istRichtig ? " option-correct" : gewaehlt ? " option-wrong" : "";
            return `<button type="button" class="option-btn ak-opt${zustand}" data-ak-opt="${i}" ${s.beantwortet ? "disabled" : ""}><span>${opt}</span></button>`;
          }).join("")}
        </div>
        ${s.beantwortet ? `
          <div class="witz-erklaerung" style="margin-top:12px;">
            <p style="margin:0;">${s.beantwortet.gewaehlt === a.richtig ? "✅ " : "❌ "}${a.erkl}</p>
          </div>
          <div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="akWeiter">Weiter ▸</button>
          </div>` : ""}
        ${miniBugReportBtnHtml("Aussprache-Kurs: " + a.frage)}
      </div>`;
  }

  async function renderAusspracheKurs() {
    autoWeiterAbbrechen();
    const area = document.getElementById("ausspracheKursArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "aussprachekurs_neu", "Aussprache-Kurs", "🗣️", false, true)) return;
    if (!window.DMA_AUSSPRACHE) {
      area.innerHTML = '<p class="empty-note">Der Aussprache-Kurs wird geladen …</p>';
      const ok = await ausspracheKursLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Der Aussprache-Kurs konnte nicht geladen werden.</p>'; return; }
    }
    if (akTeil === "test" && akTest && akTest.sprache === akAktuelleSprache()
        && akTest.index >= akTest.aufgaben.length) { renderAkTestErgebnis(); return; }

    let inhalt = "";
    if (akTeil === "alphabet") inhalt = akAlphabetHtml();
    else if (akTeil === "verbindungen") inhalt = akVerbindungenHtml();
    else if (akTeil === "regeln") inhalt = akRegelnHtml();
    else if (akTeil === "buendel") inhalt = akBuendelHtml();
    else if (akTeil === "tricks") inhalt = akTricksHtml();
    else if (akTeil === "test") inhalt = akTestHtml();
    area.innerHTML = akKopfHtml() + inhalt;
    akBinden(area);
    /* Die kleine Übersetzungszeile unter den Beispielwörtern zieht ihre
       Bedeutungen aus dem Wörterbuch. Das wird erst beim Wechsel nach
       „Lernen" geladen — ist es noch unterwegs, stände hier gar keine
       Übersetzung. Also nach dem Laden einmal neu zeichnen. */
    if (!akUebersNachgezogen && wortschatzNachziehen(() => {
      akUebersNachgezogen = true;
      if (document.getElementById("ausspracheKursArea") === area) renderAusspracheKurs();
    })) { /* wird nachgeholt */ }
  }
  let akUebersNachgezogen = false;

  function akBinden(area) {
    area.querySelectorAll(".ak-spr-btn").forEach((b) => b.addEventListener("click", () => {
      akSprache = b.dataset.akSpr; akTest = null; renderAusspracheKurs();
    }));
    area.querySelectorAll(".ak-teil-btn").forEach((b) => b.addEventListener("click", () => {
      akTeil = b.dataset.akTeil; renderAusspracheKurs();
      setTimeout(() => { area.scrollIntoView({ behavior: "smooth", block: "start" }); }, 40);
    }));
    // Ein Buchstabe: Name und Beispielwort nacheinander.
    area.querySelectorAll("[data-ak-buchstabe]").forEach((k) => k.addEventListener("click", (ev) => {
      if (ev.target.closest("[data-ak-sprich]")) return;
      const z = akDaten("ALPHABET")[Number(k.dataset.akBuchstabe)];
      if (!z) return;
      Core.speak(z.name, akAktuelleSprache());
      setTimeout(() => Core.speak(z.bsp, akAktuelleSprache()), 1100);
    }));
    document.getElementById("akTestStart")?.addEventListener("click", () => { neuerAkTest(); renderAusspracheKurs(); });
    const s = akTest;
    if (akTeil === "test" && s && s.index < s.aufgaben.length) {
      const a = s.aufgaben[s.index];
      area.querySelectorAll(".ak-opt").forEach((b) => b.addEventListener("click", () => {
        const opt = s.optionen[Number(b.dataset.akOpt)];
        const stimmt = opt === a.richtig;
        if (stimmt) { s.richtig += 1; Core.sound.correct(); } else Core.sound.wrong();
        spielNotiz(stimmt, `${a.frage} → ${a.richtig}`);
        s.beantwortet = { gewaehlt: opt };
        renderAusspracheKurs();
      }));
      const weiter = () => { s.index += 1; s.beantwortet = null; s.optionen = null; renderAusspracheKurs(); };
      document.getElementById("akWeiter")?.addEventListener("click", () => { autoWeiterAbbrechen(); weiter(); });
      if (s.beantwortet) autoWeiter(s.beantwortet.gewaehlt === a.richtig, weiter);
    }
    betonungsSchalterEinhaengen(area.closest(".subview") || undefined);
  }

  function renderAkTestErgebnis() {
    const area = document.getElementById("ausspracheKursArea");
    const s = akTest;
    const prozent = Math.round((s.richtig / s.aufgaben.length) * 100);
    const kategorie = s.sprache === "it" ? "it-aussprachekurs" : "aussprachekurs";
    area.innerHTML = akKopfHtml() + ergebnisSchirmHtml({
      punkte: s.richtig, prozent: prozent, tier: "Lautlotse",
      charakter: "Aussprache-Kurs",
      zeilen: [{ name: "🗣️ Richtig beantwortet", anteil: prozent, wert: s.richtig + "/" + s.aufgaben.length }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="akNochmal">🔄 Noch ein Test</button><button type="button" class="btn btn-ghost" id="akZurueck">Zurück zum Kurs</button>`,
    });
    saveResultAndCheck({
      categories: [kategorie], titelText: "Aussprache-Kurs",
      points: s.richtig, bonus: prozent === 100 ? 3 : 0, percent: prozent,
      character: "Lautlotse", badges: [], playedAt: new Date().toISOString(),
    });
    akBinden(area);
    document.getElementById("akNochmal")?.addEventListener("click", () => { neuerAkTest(); renderAusspracheKurs(); });
    document.getElementById("akZurueck")?.addEventListener("click", () => { akTest = null; akTeil = "alphabet"; renderAusspracheKurs(); });
  }

  /* Ein Klick auf ein Lautsprechersymbol — überall im Kurs derselbe Griff. */
  document.addEventListener("click", (ev) => {
    const knopf = ev.target.closest("[data-ak-sprich]");
    if (!knopf) return;
    ev.preventDefault();
    ev.stopPropagation();
    Core.speak(knopf.dataset.akSprich, knopf.dataset.akLang || akAktuelleSprache());
  });

  document.querySelector('#learnSubnav [data-sub="sub-alphabet"]')?.addEventListener("click", () => renderAusspracheKurs());

  /* ============================================================
     DIALOGE — formell und informell
     ------------------------------------------------------------
     GEWÜNSCHT: „Gibt es diese Formulare, wo man ausfüllt, wo man
     so eine Begrüßung durchspielt … dass man so einen Formular-
     Ablauf hat, wie man mit jemandem ins Gespräch kommt, locker,
     wie man das formell macht, wie man das informell macht."

     Drei Teile:
       Formular   — die Schritte eines Gesprächs, zu jedem Schritt
                    fertige Sätze in beiden Formen. Man tippt sich
                    sein eigenes Gespräch zusammen.
       Gespräche  — ausgespielte Situationen. Die andere Person
                    redet, man wählt selbst die Antwort. Falsche
                    Antworten sind nicht unverständlich, sondern
                    unpassend — und das wird erklärt.
       Du oder Sie — dieselbe Aussage in beiden Formen, dazu die
                    Regel, wann welche gilt.
     ============================================================ */
  let dialogeGeladen = null;
  function dialogeLaden() {
    if (window.DMA_DIALOGE) return Promise.resolve(true);
    if (dialogeGeladen) return dialogeGeladen;
    dialogeGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-dialoge.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { dialogeGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return dialogeGeladen;
  }

  const DLG_TEILE = { formular: "📋 Gesprächs-Formular", gespraeche: "💬 Gespräche", anrede: "🤝 Du oder Sie?" };
  let dlgTeil = "formular";
  let dlgRegister = "formell";
  let dlgMeins = [];          // die selbst zusammengestellten Sätze
  let dlgLauf = null;         // das gerade gespielte Gespräch

  function dlgSprache() { return imItalienischraum() ? "it" : "de"; }
  function dlgDaten(feld) {
    const D = window.DMA_DIALOGE || {};
    return (D[feld] && D[feld][dlgSprache()]) || [];
  }

  function dlgKopfHtml() {
    return `
      <div class="question-card">
        <p class="eyebrow">💬 GESPRÄCHE FÜHREN</p>
        <p class="empty-note" style="margin-bottom:10px;">
          Ein Gespräch hat immer dieselben Schritte: grüßen, sagen worum es geht, nachfragen,
          antworten, danken, sich verabschieden. Hier stehen die Sätze für jeden Schritt —
          einmal in der Sie-Form für Ämter, Ärzte und Fremde, einmal in der du-Form für
          Nachbarn, Kurs und Freunde. Und dann spielt man es durch.
        </p>
        <div class="trophy-case">
          ${Object.entries(DLG_TEILE).map(([k, name]) =>
            `<button type="button" class="trophy-chip dlg-teil-btn ${dlgTeil === k ? "selected" : ""}" data-dlg-teil="${k}">${name}</button>`).join("")}
        </div>
      </div>`;
  }

  function dlgFormularHtml() {
    const schritte = dlgDaten("SCHRITTE");
    const spr = dlgSprache();
    return `
      <div class="question-card">
        <p class="eyebrow">WELCHE FORM?</p>
        <div class="trophy-case" style="margin-bottom:10px;">
          <button type="button" class="trophy-chip dlg-reg-btn ${dlgRegister === "formell" ? "selected" : ""}" data-dlg-reg="formell">🎩 Sie — Amt, Arzt, Fremde</button>
          <button type="button" class="trophy-chip dlg-reg-btn ${dlgRegister === "informell" ? "selected" : ""}" data-dlg-reg="informell">👋 Du — Freunde, Kurs, Nachbarn</button>
        </div>
        <p class="empty-note" style="margin:0;">Tippe die Sätze an, die du brauchst. Unten entsteht daraus dein eigenes Gespräch, das du behalten kannst.</p>
      </div>
      ${schritte.map((s, si) => `
        <div class="question-card dlg-schritt">
          <p class="eyebrow">${s.name}</p>
          ${s.erklaerung ? `<p class="empty-note" style="margin-bottom:10px;">${s.erklaerung}</p>` : ""}
          <div class="dlg-satzliste">
            ${(s[dlgRegister] || []).map((satz, i) => `
              <div class="dlg-satz">
                <button type="button" class="dlg-satz-text" data-dlg-nimm="${si}:${i}">${satz}</button>
                ${sprichKnopfHtml(satz, spr)}
              </div>`).join("")}
          </div>
          ${s.hinweis ? `<p class="ak-b-hinweis">💡 ${s.hinweis}</p>` : ""}
        </div>`).join("")}
      <div class="question-card" id="dlgMeinsKarte">
        <p class="eyebrow">MEIN GESPRÄCH</p>
        ${dlgMeins.length ? `
          <ol class="dlg-meins sammel-text">
            ${dlgMeins.map((z, i) => `<li>${z} <button type="button" class="dlg-weg" data-dlg-weg="${i}" aria-label="entfernen">✕</button></li>`).join("")}
          </ol>
          <div class="quiz-actions" style="justify-content:flex-start; margin-top:10px;">
            <button type="button" class="btn btn-ghost" id="dlgVorlesen">🔊 Ganz vorlesen</button>
            ${textInListeKnopfHtml("Mein Gespräch")}
            <button type="button" class="btn btn-ghost" id="dlgLeeren">🗑️ Leeren</button>
          </div>` : `<p class="empty-note" style="margin:0;">Noch nichts ausgewählt. Tippe oben auf die Sätze, die du sagen würdest.</p>`}
      </div>`;
  }

  function dlgListeHtml() {
    const alle = dlgDaten("SITUATIONEN");
    return `
      <div class="question-card">
        <p class="eyebrow">GESPRÄCHE ZUM DURCHSPIELEN</p>
        <p class="empty-note" style="margin-bottom:12px;">
          Die andere Person fängt an, du wählst die Antwort. Was nicht passt, wird erklärt —
          nicht weil es falsch wäre, sondern weil es in dieser Situation anders klingt, als du es meinst.
        </p>
        <div class="dlg-kacheln">
          ${alle.map((s) => `
            <button type="button" class="dlg-kachel" data-dlg-start="${s.id}">
              <span class="dlg-kachel-titel">${s.titel}</span>
              <span class="dlg-kachel-ort">${s.ort}</span>
              <span class="dlg-kachel-zeile">
                <span class="dlg-reg-marke dlg-reg-${s.register}">${s.register === "formell" ? "🎩 Sie" : "👋 du"}</span>
                <span class="level-badge">${s.niveau}</span>
                <span class="dlg-kachel-anzahl">${s.zeilen.filter((z) => z.optionen).length} Entscheidungen</span>
              </span>
            </button>`).join("")}
        </div>
      </div>`;
  }

  function dlgSpielHtml() {
    const l = dlgLauf;
    const s = l.situation;
    const spr = dlgSprache();
    const bisher = l.verlauf.map((v) => `
      <div class="dlg-zeile ${v.ich ? "dlg-ich" : "dlg-andere"}">
        <span class="dlg-wer">${v.ich ? "Du" : s.gegenueber.split(",")[0]}</span>
        <span class="dlg-text">${v.text} ${sprichKnopfHtml(v.text, spr)}</span>
      </div>`).join("");
    if (l.index >= s.zeilen.length) return "";
    const z = s.zeilen[l.index];
    return `
      <div class="question-card">
        <p class="eyebrow">${s.titel}</p>
        <p class="empty-note" style="margin-bottom:6px;">📍 ${s.ort} · ${s.register === "formell" ? "🎩 Sie-Form" : "👋 du-Form"} · ${s.niveau}</p>
        <p class="empty-note" style="margin-bottom:12px;">${s.worum}</p>
        ${fortschrittHtml(l.gewaehlt, l.stellen)}
        <div class="dlg-verlauf">${bisher}</div>
        ${z.optionen ? `
          <p class="question-prompt" style="margin:12px 0 10px;">Was sagst du?</p>
          <div class="option-list">
            ${z.optionen.map((o, i) => {
              const g = l.versuche.indexOf(i) >= 0;
              const zustand = !g ? "" : o.ok ? " option-correct" : " option-wrong";
              return `<button type="button" class="option-btn dlg-opt${zustand}" data-dlg-opt="${i}" ${l.fertig || g ? "disabled" : ""}><span>${o.text}</span></button>`;
            }).join("")}
          </div>
          ${l.versuche.length ? `<div class="witz-erklaerung" style="margin-top:12px;">
            ${l.versuche.map((i) => `<p style="margin:0 0 6px;">${z.optionen[i].ok ? "✅ " : "❌ "}${z.optionen[i].warum}</p>`).join("")}
          </div>` : ""}
          ${l.fertig ? `<div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="dlgWeiter">Weiter ▸</button></div>` : ""}
        ` : `<div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="dlgWeiter">Weiter ▸</button></div>`}
        ${miniBugReportBtnHtml("Dialog: " + s.titel)}
      </div>
      <div class="quiz-actions" style="justify-content:flex-start; margin-top:10px;">
        <button type="button" class="btn btn-ghost" id="dlgAbbrechen">← Zurück zur Übersicht</button>
      </div>`;
  }

  function dlgAnredeHtml() {
    const D = window.DMA_DIALOGE || {};
    const paare = dlgDaten("REGISTER");
    const regeln = (D.ANREDE && D.ANREDE.de) || [];
    const anbieten = D.DU_ANBIETEN || {};
    const spr = dlgSprache();
    return `
      <div class="question-card">
        <p class="eyebrow">DIESELBE AUSSAGE, ZWEI FORMEN</p>
        <div class="dlg-paare">
          <div class="dlg-paar dlg-paar-kopf"><span>Wozu</span><span>🎩 Sie</span><span>👋 du</span></div>
          ${paare.map((p) => `
            <div class="dlg-paar">
              <span class="dlg-paar-was">${p.was}</span>
              <span class="dlg-paar-sie"><span class="dlg-paar-icon">🎩</span>${p.sie} ${sprichKnopfHtml(p.sie, spr)}</span>
              <span class="dlg-paar-du"><span class="dlg-paar-icon">👋</span>${p.du} ${sprichKnopfHtml(p.du, spr)}</span>
            </div>`).join("")}
        </div>
      </div>
      ${regeln.length ? `
      <div class="question-card">
        <p class="eyebrow">WANN DUZT MAN, WANN SIEZT MAN?</p>
        <div class="dlg-regeln">
          ${regeln.map((r) => `
            <div class="dlg-regel">
              <span class="dlg-reg-marke dlg-reg-${r.form === "Sie" ? "formell" : "informell"}">${r.form === "Sie" ? "🎩 Sie" : "👋 du"}</span>
              <span class="dlg-regel-wann">${r.wann}${r.warum ? `<span class="ak-b-hinweis">${r.warum}</span>` : ""}</span>
            </div>`).join("")}
        </div>
      </div>` : ""}
      ${anbieten.titel ? `
      <div class="question-card">
        <p class="eyebrow">${anbieten.titel}</p>
        <p class="empty-note" style="margin-bottom:10px;">${anbieten.text}</p>
        <div class="dlg-satzliste">
          ${(anbieten.saetze || []).map((s) => `
            <div class="dlg-satz"><span class="dlg-satz-text dlg-satz-fest">${s}</span>${sprichKnopfHtml(s, "de")}</div>`).join("")}
        </div>
        <p class="ak-b-hinweis">💡 ${anbieten.ablehnen}</p>
      </div>` : ""}`;
  }

  async function renderDialoge() {
    autoWeiterAbbrechen();
    const area = document.getElementById("dialogeArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "dialoge_neu", "Dialoge", "💬", false, true)) return;
    if (!window.DMA_DIALOGE) {
      area.innerHTML = '<p class="empty-note">Die Gespräche werden geladen …</p>';
      const ok = await dialogeLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Die Gespräche konnten nicht geladen werden.</p>'; return; }
    }
    if (dlgLauf && dlgLauf.index >= dlgLauf.situation.zeilen.length) { renderDialogErgebnis(); return; }
    let inhalt = "";
    if (dlgLauf) inhalt = dlgSpielHtml();
    else if (dlgTeil === "formular") inhalt = dlgFormularHtml();
    else if (dlgTeil === "gespraeche") inhalt = dlgListeHtml();
    else if (dlgTeil === "anrede") inhalt = dlgAnredeHtml();
    area.innerHTML = (dlgLauf ? "" : dlgKopfHtml()) + inhalt;
    dlgBinden(area);
  }

  function dlgStarten(id) {
    const s = dlgDaten("SITUATIONEN").find((x) => x.id === id);
    if (!s) return;
    dlgLauf = {
      situation: s, index: 0, verlauf: [], versuche: [], fertig: false,
      punkte: 0, gewaehlt: 0, ohneFehler: 0,
      stellen: s.zeilen.filter((z) => z.optionen).length,
    };
    // Alles, was vor der ersten Wahlstelle steht, gehört schon in den Verlauf.
    dlgVorspulen();
    renderDialoge();
  }
  /* Die Sätze der anderen Person laufen von selbst — stehen bleibt es
     erst, wenn man selbst dran ist. */
  function dlgVorspulen() {
    const l = dlgLauf;
    while (l.index < l.situation.zeilen.length && !l.situation.zeilen[l.index].optionen) {
      const z = l.situation.zeilen[l.index];
      l.verlauf.push({ ich: false, text: z.text });
      l.index += 1;
    }
  }

  function dlgBinden(area) {
    area.querySelectorAll(".dlg-teil-btn").forEach((b) => b.addEventListener("click", () => {
      dlgTeil = b.dataset.dlgTeil; renderDialoge();
    }));
    area.querySelectorAll(".dlg-reg-btn").forEach((b) => b.addEventListener("click", () => {
      dlgRegister = b.dataset.dlgReg; renderDialoge();
    }));
    area.querySelectorAll("[data-dlg-nimm]").forEach((b) => b.addEventListener("click", () => {
      const [si, i] = b.dataset.dlgNimm.split(":").map(Number);
      const satz = (dlgDaten("SCHRITTE")[si] || {})[dlgRegister][i];
      if (satz) { dlgMeins.push(satz); renderDialoge();
        setTimeout(() => document.getElementById("dlgMeinsKarte")?.scrollIntoView({ behavior: "smooth", block: "end" }), 60); }
    }));
    area.querySelectorAll("[data-dlg-weg]").forEach((b) => b.addEventListener("click", () => {
      dlgMeins.splice(Number(b.dataset.dlgWeg), 1); renderDialoge();
    }));
    document.getElementById("dlgLeeren")?.addEventListener("click", () => { dlgMeins = []; renderDialoge(); });
    document.getElementById("dlgVorlesen")?.addEventListener("click", () => {
      Core.speak(dlgMeins.join(". "), dlgSprache());
    });
    area.querySelectorAll("[data-dlg-start]").forEach((b) => b.addEventListener("click", () => dlgStarten(b.dataset.dlgStart)));
    document.getElementById("dlgAbbrechen")?.addEventListener("click", () => { dlgLauf = null; dlgTeil = "gespraeche"; renderDialoge(); });

    const l = dlgLauf;
    if (l && l.index < l.situation.zeilen.length) {
      const z = l.situation.zeilen[l.index];
      area.querySelectorAll(".dlg-opt").forEach((b) => b.addEventListener("click", () => {
        const i = Number(b.dataset.dlgOpt);
        if (l.versuche.indexOf(i) >= 0) return;
        const o = z.optionen[i];
        l.versuche.push(i);
        if (o.ok) {
          /* Punkt gibt es nur, wenn die passende Antwort im ersten
             Anlauf kam — sonst hätte Durchprobieren denselben Wert. */
          if (l.versuche.length === 1) { l.punkte += 1; l.ohneFehler += 1; }
          l.fertig = true;
          l.verlauf.push({ ich: true, text: o.text });
          Core.sound.correct();
        } else Core.sound.wrong();
        spielNotiz(Boolean(o.ok), `${l.situation.titel}: ${o.text}`);
        renderDialoge();
      }));
      document.getElementById("dlgWeiter")?.addEventListener("click", () => {
        if (z.optionen) l.gewaehlt += 1;
        l.index += 1; l.versuche = []; l.fertig = false;
        dlgVorspulen();
        renderDialoge();
      });
    }
    betonungsSchalterEinhaengen(area.closest(".subview") || undefined);
  }

  function renderDialogErgebnis() {
    const area = document.getElementById("dialogeArea");
    const l = dlgLauf;
    const s = l.situation;
    const spr = dlgSprache();
    const prozent = l.stellen ? Math.round((l.ohneFehler / l.stellen) * 100) : 100;
    area.innerHTML = ergebnisSchirmHtml({
      punkte: l.punkte, prozent: prozent, tier: "Gesprächspartner:in",
      charakter: "Dialoge",
      zeilen: [{ name: "💬 Auf Anhieb passend", anteil: prozent, wert: l.ohneFehler + "/" + l.stellen }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="dlgNochmal">🔄 Noch einmal</button><button type="button" class="btn btn-ghost" id="dlgAndere">Anderes Gespräch</button>`,
    }) + `
      <div class="question-card">
        <p class="eyebrow">DAS GANZE GESPRÄCH</p>
        <p class="empty-note" style="margin-bottom:10px;">So ist es gelaufen. Lies es einmal laut mit — beide Rollen.</p>
        <div class="dlg-verlauf">
          ${l.verlauf.map((v) => `
            <div class="dlg-zeile ${v.ich ? "dlg-ich" : "dlg-andere"}">
              <span class="dlg-wer">${v.ich ? "Du" : s.gegenueber.split(",")[0]}</span>
              <span class="dlg-text">${v.text} ${sprichKnopfHtml(v.text, spr)}</span>
            </div>`).join("")}
        </div>
        <div class="quiz-actions" style="justify-content:flex-start; margin-top:10px;">
          <button type="button" class="btn btn-ghost" id="dlgAllesHoeren">🔊 Ganzes Gespräch vorlesen</button>
        </div>
      </div>`;
    saveResultAndCheck({
      categories: [spr === "it" ? "it-dialoge" : "dialoge"], titelText: "Dialog: " + s.titel,
      points: l.punkte, bonus: prozent === 100 ? 3 : 0, percent: prozent,
      character: "Gesprächspartner:in", badges: [], playedAt: new Date().toISOString(),
    });
    dlgBinden(area);
    document.getElementById("dlgNochmal")?.addEventListener("click", () => dlgStarten(s.id));
    document.getElementById("dlgAndere")?.addEventListener("click", () => { dlgLauf = null; dlgTeil = "gespraeche"; renderDialoge(); });
    document.getElementById("dlgAllesHoeren")?.addEventListener("click", () => {
      Core.speak(l.verlauf.map((v) => v.text).join(" … "), spr);
    });
  }

  document.querySelector('#learnSubnav [data-sub="sub-dialoge"]')?.addEventListener("click", () => renderDialoge());

  /* ============================================================
     FESTE, FEIERTAGE UND KULTUR
     ------------------------------------------------------------
     GEWÜNSCHT: „Zu Festen und Feiertagen möchte ich auch noch
     irgendwas haben — ja, Weihnachten, Ostern und die wichtigsten
     Sachen zur deutschen Kultur."

     Drei Teile:
       Jahreslauf — jedes Fest mit Datum, Ablauf, Wörtern und den
                    Sätzen, die man an dem Tag braucht.
       Alltag     — das Ungeschriebene: Pünktlichkeit, Ruhezeiten,
                    Mülltrennung, Pfand, Behörden, Vereine.
       Test       — zählt aufs Punktekonto.
     ============================================================ */
  let festeGeladen = null;
  function festeLaden() {
    if (window.DMA_FESTE) return Promise.resolve(true);
    if (festeGeladen) return festeGeladen;
    festeGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-feste.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { festeGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return festeGeladen;
  }

  const FST_TEILE = { jahr: "🗓️ Das Jahr", alltag: "🏠 Alltag & Regeln", test: "✅ Test" };
  const FST_ART = {
    gesetzlich: { marke: "🔴 gesetzlicher Feiertag", erklaerung: "arbeitsfrei, Läden zu" },
    regional: { marke: "🟡 nur in manchen Bundesländern", erklaerung: "je nach Wohnort frei oder nicht" },
    brauch: { marke: "🟢 Brauch", erklaerung: "normaler Arbeitstag — aber alle machen mit" },
  };
  const FST_MONATE = ["", "Januar", "Februar", "März", "April", "Mai", "Juni",
    "Juli", "August", "September", "Oktober", "November", "Dezember"];
  let fstTeil = "jahr";
  let fstOffen = null;
  let fstTest = null;

  function fstSprache() { return imItalienischraum() ? "it" : "de"; }
  function fstDaten(feld) {
    const D = window.DMA_FESTE || {};
    return (D[feld] && D[feld][fstSprache()]) || [];
  }

  function fstKopfHtml() {
    const it = fstSprache() === "it";
    return `
      <div class="question-card">
        <p class="eyebrow">🎄 ${it ? "FESTE UND KULTUR IN ITALIEN" : "FESTE, FEIERTAGE UND KULTUR"}</p>
        <p class="empty-note" style="margin-bottom:10px;">
          ${it
            ? "Der italienische Jahreslauf — und die Dinge, die man wissen muss, ohne dass sie jemand erklärt."
            : "Wann hat alles zu, und warum? Was tut man an Ostern, was an Silvester, und wann gratuliert man auf keinen Fall? Dazu das Ungeschriebene: Ruhezeiten, Mülltrennung, Pfand, Behörden, Vereine. Nichts davon steht in einem Gesetz, das man liest — und alles davon merkt man, wenn man es falsch macht."}
        </p>
        <div class="trophy-case">
          ${Object.entries(FST_TEILE).map(([k, name]) =>
            `<button type="button" class="trophy-chip fst-teil-btn ${fstTeil === k ? "selected" : ""}" data-fst-teil="${k}">${name}</button>`).join("")}
        </div>
      </div>`;
  }

  function fstFestHtml(f, offen) {
    const spr = fstSprache();
    const art = FST_ART[f.art] || FST_ART.brauch;
    return `
      <div class="question-card fst-fest ${offen ? "fst-offen" : ""}">
        <button type="button" class="fst-fest-kopf" data-fst-fest="${f.id}">
          <span class="fst-fest-name">${betonungAnzeigen(f.syl) || f.name}</span>
          <span class="fst-fest-wann">${f.wann}</span>
          <span class="fst-art fst-art-${f.art}" title="${art.erklaerung}">${art.marke}</span>
          <span class="fst-pfeil">${offen ? "▾" : "▸"}</span>
        </button>
        ${offen ? `
          <p class="empty-note" style="margin:10px 0 12px;">${f.worum}</p>
          <ul class="fst-ablauf">
            ${f.ablauf.map((z) => `<li>${z}</li>`).join("")}
          </ul>
          <p class="eyebrow" style="margin-top:14px;">WÖRTER DAZU</p>
          <div class="ak-bsp-gitter">
            ${f.woerter.map((x) => `
              <div class="ak-bsp">
                <span class="ak-bsp-wort">${akWortFrei(x.wort, x.syl, spr)}</span>
                ${sprichKnopfHtml(x.wort, spr)}
                ${x.was ? `<span class="ak-bsp-hinweis">${x.was}</span>` : ""}
              </div>`).join("")}
          </div>
          <p class="eyebrow" style="margin-top:14px;">DAS SAGT MAN</p>
          <div class="dlg-satzliste">
            ${f.saetze.map((s) => `
              <div class="dlg-satz"><span class="dlg-satz-text dlg-satz-fest">${s}</span>${sprichKnopfHtml(s, spr)}</div>`).join("")}
          </div>
          ${f.hinweis ? `<div class="ak-probe"><p>💡 ${f.hinweis}</p></div>` : ""}
        ` : ""}
      </div>`;
  }

  /* Wie akWort, aber mit frei wählbarer Sprache — der Kulturbereich
     benutzt sie unabhängig vom Aussprache-Kurs. */
  function akWortFrei(wort, syl, sprache) {
    const text = String(wort);
    if (!syl) return text;
    let gezeigt = sprache === "it" ? Core.formatStressIt(syl) : Core.formatStress(syl);
    const artikel = text.match(/^(?:(?:der|die|das|il|lo|la|i|gli|le)\s|l['’])/i);
    const rest = artikel ? text.slice(artikel[0].length) : text;
    if (rest && rest[0] === rest[0].toLowerCase() && rest[0] !== rest[0].toUpperCase()) {
      gezeigt = akErsteKlein(gezeigt);
    }
    return (artikel ? artikel[0] : "") + gezeigt;
  }

  function fstJahrHtml() {
    const feste = fstDaten("FESTE");
    /* Nach Monaten sortiert, damit man den Jahreslauf sieht. Was kein
       festes Datum hat (Geburtstag), steht am Ende. */
    const sortiert = [...feste].sort((a, b) => (a.monat || 13) - (b.monat || 13));
    const heute = new Date().getMonth() + 1;
    const naechstes = sortiert.find((f) => f.monat >= heute) || sortiert[0];
    let letzterMonat = -1;
    return `
      <div class="question-card">
        <p class="eyebrow">DIE DREI ARTEN</p>
        <div class="fst-legende">
          ${Object.entries(FST_ART).map(([k, v]) =>
            `<span class="fst-art fst-art-${k}">${v.marke}</span><span class="ak-b-hinweis" style="margin:0 0 6px;">${v.erklaerung}</span>`).join("")}
        </div>
        ${naechstes ? `<p class="empty-note" style="margin:10px 0 0;">Als Nächstes im Jahr: <strong>${naechstes.name}</strong> — ${naechstes.wann}.</p>` : ""}
      </div>
      ${sortiert.map((f) => {
        let kopf = "";
        if (f.monat !== letzterMonat) {
          letzterMonat = f.monat;
          kopf = `<p class="fst-monat">${f.monat ? FST_MONATE[f.monat] : "Das ganze Jahr"}</p>`;
        }
        return kopf + fstFestHtml(f, fstOffen === f.id);
      }).join("")}`;
  }

  function fstAlltagHtml() {
    const spr = fstSprache();
    return fstDaten("ALLTAG").map((a) => `
      <div class="question-card fst-fest ${fstOffen === a.id ? "fst-offen" : ""}">
        <button type="button" class="fst-fest-kopf" data-fst-fest="${a.id}">
          <span class="fst-fest-name">${a.titel}</span>
          <span class="fst-fest-wann">${a.kurz}</span>
          <span class="fst-pfeil">${fstOffen === a.id ? "▾" : "▸"}</span>
        </button>
        ${fstOffen === a.id ? `
          <ul class="fst-ablauf">${a.punkte.map((p) => `<li>${p}</li>`).join("")}</ul>
          <p class="eyebrow" style="margin-top:14px;">WÖRTER DAZU</p>
          <div class="ak-bsp-gitter">
            ${a.woerter.map((x) => `
              <div class="ak-bsp">
                <span class="ak-bsp-wort">${akWortFrei(x.wort, x.syl, spr)}</span>
                ${sprichKnopfHtml(x.wort, spr)}
                ${x.was ? `<span class="ak-bsp-hinweis">${x.was}</span>` : ""}
              </div>`).join("")}
          </div>
          <p class="eyebrow" style="margin-top:14px;">DAS SAGT MAN</p>
          <div class="dlg-satzliste">
            ${a.saetze.map((s) => `
              <div class="dlg-satz"><span class="dlg-satz-text dlg-satz-fest">${s}</span>${sprichKnopfHtml(s, spr)}</div>`).join("")}
          </div>
          ${a.warnung ? `<div class="ak-ausnahme"><p class="ak-ausnahme-titel">⚠️ Wichtig</p><p>${a.warnung}</p></div>` : ""}
        ` : ""}
      </div>`).join("");
  }

  const FST_RUNDEN = 10;
  function neuerFstTest() {
    const pool = fstDaten("QUIZ");
    fstTest = {
      aufgaben: Core.shuffle(pool).slice(0, Math.min(FST_RUNDEN, pool.length)),
      index: 0, richtig: 0, beantwortet: null, optionen: null, sprache: fstSprache(),
    };
  }
  function fstTestHtml() {
    const pool = fstDaten("QUIZ");
    if (!fstTest || fstTest.sprache !== fstSprache()) {
      return `
        <div class="question-card">
          <p class="eyebrow">TEST</p>
          <p class="empty-note" style="margin-bottom:12px;">
            Fragen aus allem, was hier steht — Feiertage, Bräuche und die Regeln des Alltags.
            ${pool.length} Fragen stehen bereit, eine Runde geht über ${Math.min(FST_RUNDEN, pool.length)}.
          </p>
          <button type="button" class="btn btn-coffee" id="fstTestStart">▶ Test starten</button>
        </div>`;
    }
    const s = fstTest;
    if (s.index >= s.aufgaben.length) return "";
    const a = s.aufgaben[s.index];
    const optionen = s.optionen || Core.shuffle([a.richtig, ...a.falsch]);
    s.optionen = optionen;
    return `
      <div class="question-card">
        <p class="eyebrow">TEST · FRAGE ${s.index + 1} / ${s.aufgaben.length}</p>
        ${fortschrittHtml(s.index, s.aufgaben.length)}
        <p class="question-prompt" style="margin:10px 0 14px;">${a.frage}</p>
        <div class="option-list">
          ${optionen.map((opt, i) => {
            const gewaehlt = s.beantwortet && s.beantwortet.gewaehlt === opt;
            const istRichtig = opt === a.richtig;
            const zustand = !s.beantwortet ? "" : istRichtig ? " option-correct" : gewaehlt ? " option-wrong" : "";
            return `<button type="button" class="option-btn fst-opt${zustand}" data-fst-opt="${i}" ${s.beantwortet ? "disabled" : ""}><span>${opt}</span></button>`;
          }).join("")}
        </div>
        ${s.beantwortet ? `
          <div class="witz-erklaerung" style="margin-top:12px;">
            <p style="margin:0;">${s.beantwortet.gewaehlt === a.richtig ? "✅ " : "❌ "}${a.erkl}</p>
          </div>
          <div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="fstWeiter">Weiter ▸</button>
          </div>` : ""}
        ${miniBugReportBtnHtml("Feste & Kultur: " + a.frage)}
      </div>`;
  }

  async function renderFeste() {
    autoWeiterAbbrechen();
    const area = document.getElementById("festeArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "feste_kultur_neu", "Feste & Kultur", "🎄", false, true)) return;
    if (!window.DMA_FESTE) {
      area.innerHTML = '<p class="empty-note">Feste und Kultur werden geladen …</p>';
      const ok = await festeLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Der Bereich konnte nicht geladen werden.</p>'; return; }
    }
    if (fstTeil === "test" && fstTest && fstTest.sprache === fstSprache()
        && fstTest.index >= fstTest.aufgaben.length) { renderFstErgebnis(); return; }
    let inhalt = "";
    if (fstTeil === "jahr") inhalt = fstJahrHtml();
    else if (fstTeil === "alltag") inhalt = fstAlltagHtml();
    else if (fstTeil === "test") inhalt = fstTestHtml();
    area.innerHTML = fstKopfHtml() + inhalt;
    fstBinden(area);
  }

  function fstBinden(area) {
    area.querySelectorAll(".fst-teil-btn").forEach((b) => b.addEventListener("click", () => {
      fstTeil = b.dataset.fstTeil; fstOffen = null; renderFeste();
    }));
    area.querySelectorAll("[data-fst-fest]").forEach((b) => b.addEventListener("click", () => {
      const id = b.dataset.fstFest;
      fstOffen = fstOffen === id ? null : id;
      renderFeste();
      if (fstOffen) setTimeout(() => {
        document.querySelector(`[data-fst-fest="${id}"]`)?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 60);
    }));
    document.getElementById("fstTestStart")?.addEventListener("click", () => { neuerFstTest(); renderFeste(); });
    const s = fstTest;
    if (fstTeil === "test" && s && s.index < s.aufgaben.length) {
      const a = s.aufgaben[s.index];
      area.querySelectorAll(".fst-opt").forEach((b) => b.addEventListener("click", () => {
        const opt = s.optionen[Number(b.dataset.fstOpt)];
        const stimmt = opt === a.richtig;
        if (stimmt) { s.richtig += 1; Core.sound.correct(); } else Core.sound.wrong();
        spielNotiz(stimmt, `${a.frage} → ${a.richtig}`);
        s.beantwortet = { gewaehlt: opt };
        renderFeste();
      }));
      const weiter = () => { s.index += 1; s.beantwortet = null; s.optionen = null; renderFeste(); };
      document.getElementById("fstWeiter")?.addEventListener("click", () => { autoWeiterAbbrechen(); weiter(); });
      if (s.beantwortet) autoWeiter(s.beantwortet.gewaehlt === a.richtig, weiter);
    }
    betonungsSchalterEinhaengen(area.closest(".subview") || undefined);
  }

  function renderFstErgebnis() {
    const area = document.getElementById("festeArea");
    const s = fstTest;
    const prozent = Math.round((s.richtig / s.aufgaben.length) * 100);
    area.innerHTML = fstKopfHtml() + ergebnisSchirmHtml({
      punkte: s.richtig, prozent: prozent, tier: "Landeskundler:in",
      charakter: "Feste & Kultur",
      zeilen: [{ name: "🎄 Richtig beantwortet", anteil: prozent, wert: s.richtig + "/" + s.aufgaben.length }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="fstNochmal">🔄 Noch ein Test</button><button type="button" class="btn btn-ghost" id="fstZurueck">Zurück zum Jahr</button>`,
    });
    saveResultAndCheck({
      categories: [s.sprache === "it" ? "it-kultur" : "kultur"], titelText: "Feste & Kultur",
      points: s.richtig, bonus: prozent === 100 ? 3 : 0, percent: prozent,
      character: "Landeskundler:in", badges: [], playedAt: new Date().toISOString(),
    });
    fstBinden(area);
    document.getElementById("fstNochmal")?.addEventListener("click", () => { neuerFstTest(); renderFeste(); });
    document.getElementById("fstZurueck")?.addEventListener("click", () => { fstTest = null; fstTeil = "jahr"; renderFeste(); });
  }

  document.querySelector('#knowledgeSubnav [data-sub="sub-feste"]')?.addEventListener("click", () => renderFeste());
  document.querySelector('#learnSubnav [data-sub="sub-feste"]')?.addEventListener("click", () => renderFeste());

