  const UMZ_DAT = { der: "dem", die: "der", das: "dem" };
  // Nur die Verschmelzungen, die im normalen Deutsch die Regel sind.
  const UMZ_KURZ = { "in das": "ins", "an das": "ans", "in dem": "im", "an dem": "am" };

