  function neueZwillingSession() {
    zwillingLevel = applyDefaultCefrLevel(zwillingLevel, (v) => { zwillingLevel = v; }, "zwillinge");
    const passend = ZWILLINGE.filter((z) => z.lvl === zwillingLevel);
    /* Erst die Paare des gewählten Niveaus, und wenn davon weniger als
       zehn da sind, wird mit den übrigen aufgefüllt — eine Runde soll
       nicht kürzer sein, nur weil eine Stufe dünner besetzt ist. */
    const rest = Core.shuffle(ZWILLINGE.filter((z) => z.lvl !== zwillingLevel));
    const paare = Core.shuffle(passend).concat(rest).slice(0, ZWILLING_RUNDEN);
    zwillingSession = {
      aufgaben: paare.map((p) => {
        const wahl = p.s[Math.floor(Math.random() * p.s.length)];
        return { p, satz: wahl[0], loesung: wahl[1], links: Math.random() < 0.5 };
      }),
      runde: 0, richtig: 0, zustand: "warten", gewaehlt: null,
    };
  }
  function zwillingWortOhneArtikel(w) { return String(w).replace(/^(der|die|das)\s+/, ""); }
  function renderZwillinge() {
    const area = document.getElementById("zwillingeArea");
    if (!area) return;
    if (!zwillingSession) neueZwillingSession();
    const s = zwillingSession;
    if (s.runde >= s.aufgaben.length) { renderZwillingeErgebnis(); return; }
    const a = s.aufgaben[s.runde];
    const p = a.p;
    const paar = a.links ? ["a", "b"] : ["b", "a"];
    /* In die Lücke gehört das nackte Wort: „Meine ___ kommt" wird zu
       „Meine Mutter kommt" und nicht zu „Meine die Mutter kommt".
       Auf den Knöpfen bleibt der Artikel stehen — dort ist er die
       nützliche Zusatzinformation. */
    const luecke = s.zustand === "warten" ? "___" : zwillingWortOhneArtikel(p[a.loesung]);
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Die Zwillinge: " + p.a + " / " + p.b)}
        <p class="eyebrow">👂 DIE ZWILLINGE · PAAR ${s.runde + 1} / ${s.aufgaben.length}
          <span class="subnav-info-icon" data-info="Zwei Wörter, ein Laut Unterschied. Nur eines passt in den Satz. Mit dem Lautsprecher kannst du dir beide anhören.">ⓘ</span></p>
        ${fortschrittHtml(s.runde, s.aufgaben.length)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1"].map((lvl) => `<button type="button" class="trophy-chip zwilling-level-btn ${zwillingLevel === lvl ? "selected" : ""}" data-zwilling-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        <div class="zwilling-paar">
          ${paar.map((k) => `
            <div class="zwilling-seite ${s.zustand !== "warten" ? (k === a.loesung ? "zwilling-richtig" : (s.gewaehlt === k ? "zwilling-falsch" : "")) : ""}">
              <button type="button" class="zwilling-wort" data-zwilling-wahl="${k}" ${s.zustand === "warten" ? "" : "disabled"}>${p[k]}</button>
              <button type="button" class="zwilling-hoeren" data-zwilling-hoeren="${zwillingWortOhneArtikel(p[k]).replace(/"/g, "&quot;")}" aria-label="${zwillingWortOhneArtikel(p[k])} anhören">🔊</button>
            </div>`).join("")}
        </div>
        <p class="zwilling-unterschied">${p.u}</p>
        <p class="zwilling-satz">${a.satz.replace("___", `<span class="zwilling-luecke ${s.zustand === "warten" ? "" : "zwilling-luecke-voll"}">${luecke}</span>`)}</p>
        <p class="empty-note zwilling-hinweis" id="zwillingHinweis"></p>
      </div>`;
    area.querySelectorAll(".zwilling-level-btn").forEach((b) => b.addEventListener("click", () => {
      zwillingLevel = b.dataset.zwillingLevel; neueZwillingSession(); renderZwillinge();
    }));
    area.querySelectorAll("[data-zwilling-hoeren]").forEach((b) => b.addEventListener("click", (e) => {
      e.stopPropagation();
      Core.speak(b.dataset.zwillingHoeren);
    }));
    area.querySelectorAll("[data-zwilling-wahl]").forEach((b) => b.addEventListener("click", () => zwillingAntwort(b.dataset.zwillingWahl)));
  }
  function zwillingAntwort(k) {
    const s = zwillingSession;
    if (s.zustand !== "warten") return;
    const a = s.aufgaben[s.runde];
    const richtig = k === a.loesung;
    s.gewaehlt = k;
    s.zustand = "fertig";
    spielNotiz(richtig, a.satz.replace("___", zwillingWortOhneArtikel(a.p[a.loesung])));
    if (richtig) { s.richtig += 1; Core.sound.correct(); } else { Core.sound.wrong(); }
    renderZwillinge();
    const box = document.getElementById("zwillingHinweis");
    if (box) {
      box.innerHTML = (richtig ? "✅ " : "❌ ")
        + `Hier passt <strong>${a.p[a.loesung]}</strong>. Der Unterschied: ${a.p.u}.`;
    }
    setTimeout(() => Core.speak(zwillingWortOhneArtikel(a.p[a.loesung])), 200);
    s.runde += 1;
    setTimeout(() => { s.zustand = "warten"; s.gewaehlt = null; renderZwillinge(); }, richtig ? 2400 : 3400);
  }
  function renderZwillingeErgebnis() {
    const area = document.getElementById("zwillingeArea");
    const s = zwillingSession;
    const prozent = Math.round((s.richtig / Math.max(1, s.aufgaben.length)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.richtig * 2, prozent, tier: "Feines Gehör", charakter: "Die Zwillinge",
      zeilen: [{ name: "👂 Richtig unterschieden", anteil: prozent, wert: s.richtig + "/" + s.aufgaben.length }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="zwillingNochmal">🔄 Neue Runde</button>`,
    });
    document.getElementById("zwillingNochmal")?.addEventListener("click", () => { neueZwillingSession(); renderZwillinge(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["zwillinge"], points: s.richtig * 2, bonus: 0, percent: prozent, character: "Feines Gehör", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-zwillinge"]')?.addEventListener("click", () => renderZwillinge());













  /* ============================================================
     DIE FUCHSUHR — die Uhrzeit, in beide Richtungen
     ------------------------------------------------------------
     Eine Lücke, die beim Durchsehen der 40 Grammatikthemen und der
     23 Spiele auffiel: die Uhrzeit kommt in Aufgabentexten vor
     („Wir treffen uns um halb neun"), aber geübt wird sie nirgends.
     Dabei ist sie das erste, woran ein Termin scheitert — und das
     deutsche „halb vier" ist für alle, die aus dem Englischen oder
     dem Russischen kommen, eine echte Falle: es zeigt auf die
     NÄCHSTE Stunde, nicht auf die vergangene. Genau diese Falle ist
     hier in jeder Runde als falsche Antwort dabei.

     Das Spiel fragt in beide Richtungen, damit es kein Abfragen
     bleibt: mal steht die Uhr da und man sucht die Worte, mal steht
     der Satz da und man sucht unter drei Zifferblättern das
     richtige. Beides ist gezeichnet — auch hier kommt keine neue
     Bilddatei dazu, die von Hand hochgeladen werden müsste.

     Es wird nichts erfunden: die gesprochene Form wird gerechnet,
     nicht geraten, und zwar nur in Fünf-Minuten-Schritten — „siebzehn
     nach drei" sagt niemand. Für jede andere Minute fragt das Spiel
     die amtliche Form, die auf jedem Fahrplan steht.
     ============================================================ */
  let uhrLevel = null;
  let uhrSession = null;
  const UHR_RUNDEN = 10;
  const UHR_EINER = ["null", "eins", "zwei", "drei", "vier", "fünf", "sechs", "sieben", "acht", "neun",
    "zehn", "elf", "zwölf", "dreizehn", "vierzehn", "fünfzehn", "sechzehn", "siebzehn", "achtzehn", "neunzehn"];
  const UHR_ZEHNER = { 20: "zwanzig", 30: "dreißig", 40: "vierzig", 50: "fünfzig" };
  function uhrZahlWort(n) {
    if (n < 20) return UHR_EINER[n];
    const z = Math.floor(n / 10) * 10, e = n % 10;
    if (!e) return UHR_ZEHNER[z];
    return (e === 1 ? "ein" : UHR_EINER[e]) + "und" + UHR_ZEHNER[z];
  }
  // „ein Uhr", aber „halb eins": vor dem Wort „Uhr" steht die gekürzte Form.
  function uhrStundeWort(h24, vorUhr) {
    const h = ((h24 + 11) % 12) + 1;
    if (h === 1) return vorUhr ? "ein" : "eins";
    return UHR_EINER[h];
  }
  function uhrGesprochen(h, m) {
    const naechste = (h + 1) % 24;
    if (m === 0) return uhrStundeWort(h, true) + " Uhr";
    if (m === 15) return "Viertel nach " + uhrStundeWort(h);
    if (m === 30) return "halb " + uhrStundeWort(naechste);
    if (m === 45) return "Viertel vor " + uhrStundeWort(naechste);
    if (m === 25) return "fünf vor halb " + uhrStundeWort(naechste);
    if (m === 35) return "fünf nach halb " + uhrStundeWort(naechste);
    if (m < 30) return uhrZahlWort(m) + " nach " + uhrStundeWort(h);
    return uhrZahlWort(60 - m) + " vor " + uhrStundeWort(naechste);
  }
  function uhrAmtlich(h, m) {
    return (h === 1 ? "ein" : uhrZahlWort(h)) + " Uhr" + (m ? " " + uhrZahlWort(m) : "");
  }
  function uhrText(h, m, amtlich) { return amtlich ? uhrAmtlich(h, m) : uhrGesprochen(h, m); }
  function uhrZiffern(h, m) { return String(h).padStart(2, "0") + ":" + String(m).padStart(2, "0"); }
  /* Zur Auflösung passend anzeigen: neben „zehn nach vier" steht 4:10 und
     nicht 04:10 — sonst liest sich die Antwort so, als gälte sie nur
     morgens. Neben der amtlichen Form steht die amtliche Zählung. */
  function uhrZiffernAnzeige(a) {
    return a.amtlich ? uhrZiffern(a.h, a.m) : (((a.h + 11) % 12) + 1) + ":" + String(a.m).padStart(2, "0");
  }

  /* Die Stufen: erst volle und halbe Stunden, dann die Viertel, dann
     alle Fünf-Minuten-Schritte, und ganz oben zusätzlich die amtliche
     Form mit jeder beliebigen Minute. */
  const UHR_STUFEN = {
    A1: { minuten: [0, 30], amtlich: 0 },
    A2: { minuten: [0, 15, 30, 45], amtlich: 0 },
    B1: { minuten: [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55], amtlich: 0 },
    B2: { minuten: [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55], amtlich: 0.4 },
    C1: { minuten: "alle", amtlich: 0.7 },
    C2: { minuten: "alle", amtlich: 0.85 },
  };
  /* Die falschen Antworten sind keine Zufallszeiten, sondern die Fehler,
     die wirklich gemacht werden: die Stunde daneben, vor und nach
     vertauscht, und bei der halben Stunde die englische Lesart. */
  function uhrAblenker(h, m) {
    const raus = [];
    const dazu = (hh, mm) => {
      const g = ((hh % 24) + 24) % 24;
      if (g === h && mm === m) return;
      if (raus.some((x) => x[0] === g && x[1] === mm)) return;
      raus.push([g, mm]);
    };
    if (m === 30) dazu(h - 1, 30);              // „halb drei" für 15:30 — der Klassiker
    if (m === 15) dazu(h, 45);
    if (m === 45) dazu(h, 15);
    if (m && m !== 30) dazu(h, 60 - m);         // vor und nach vertauscht
    dazu(h + 1, m);
    dazu(h - 1, m);
    if (m % 5 === 0) { dazu(h, (m + 5) % 60); dazu(h, (m + 55) % 60); }
    else { dazu(h, (m + 10) % 60); dazu(h, (m + 50) % 60); }
    return Core.shuffle(raus);
  }
  function neueUhrSession() {
    uhrLevel = applyDefaultCefrLevel(uhrLevel, (v) => { uhrLevel = v; }, "fuchsuhr");
    uhrSession = { runde: 0, gesamt: UHR_RUNDEN, richtig: 0, zustand: "warten", aufgabe: null, gespielt: [] };
    neueUhrRunde();
  }
  function neueUhrRunde() {
    const stufe = UHR_STUFEN[uhrLevel] || UHR_STUFEN.B1;
    let h = 0, m = 0, versuche = 0;
    do {
      h = Math.floor(Math.random() * 24);
      m = stufe.minuten === "alle" ? Math.floor(Math.random() * 60)
        : stufe.minuten[Math.floor(Math.random() * stufe.minuten.length)];
      versuche += 1;
    } while (uhrSession.gespielt.includes(h * 60 + m) && versuche < 40);
    uhrSession.gespielt.push(h * 60 + m);
    // Die gesprochene Form gibt es nur im Fünf-Minuten-Takt — sonst
    // müsste das Spiel Sätze behaupten, die niemand sagt.
    const amtlich = m % 5 !== 0 ? true : Math.random() < stufe.amtlich;
    const richtung = Math.random() < 0.5 ? "lesen" : "stellen";
    const loesung = uhrText(h, m, amtlich);
    const andere = [];
    uhrAblenker(h, m).forEach((z) => {
      if (andere.length >= 2) return;
      if (!amtlich && z[1] % 5 !== 0) return;
      const t = uhrText(z[0], z[1], amtlich);
      if (t === loesung || andere.some((a) => uhrText(a[0], a[1], amtlich) === t)) return;
      andere.push(z);
    });
    uhrSession.aufgabe = {
      h, m, amtlich, richtung, loesung,
      wahl: Core.shuffle([[h, m]].concat(andere).map((z) => ({ h: z[0], m: z[1], ok: z[0] === h && z[1] === m }))),
    };
    uhrSession.zustand = "warten";
  }
  /* Der Merksatz zur Runde — er sagt nicht „richtig" oder „falsch",
     sondern WORAN man es beim nächsten Mal erkennt. */
  function uhrMerksatz(a) {
    if (a.amtlich) return "Auf dem Fahrplan und im Termin wird von 0 bis 23 Uhr durchgezählt — die Minute kommt einfach hinterher.";
    if (a.m === 30) return `Achtung: „halb ${uhrStundeWort((a.h + 1) % 24)}“ heißt halb DURCH die ${uhrStundeWort((a.h + 1) % 24)}. Also ${((a.h + 11) % 12) + 1}:30 — nicht ${((a.h + 12) % 12) + 1}:30.`;
    if (a.m === 45) return "„Viertel vor“ heißt: ein Viertel fehlt noch bis zur vollen Stunde.";
    if (a.m === 15) return "„Viertel nach“ heißt: ein Viertel ist seit der vollen Stunde vergangen.";
    if (a.m === 25 || a.m === 35) return "Rund um die halbe Stunde zählt man von „halb“ aus, nicht von der vollen Stunde.";
    if (a.m === 0) return "Die volle Stunde bekommt das Wort „Uhr“ dahinter.";
    return a.m < 30 ? "Bis zur halben Stunde zählt man NACH der vergangenen Stunde."
      : "Nach der halben Stunde zählt man VOR der kommenden Stunde.";
  }

  /* ------------------------------------------------------------
     Das Zifferblatt. Zwölf Zahlen, ein kurzer dicker Stundenzeiger
     und ein langer dünner Minutenzeiger — der Unterschied muss auf
     einen Blick zu sehen sein, sonst ist die Aufgabe nicht die
     Uhrzeit, sondern das Erkennen der Zeiger.
     ------------------------------------------------------------ */
  function uhrBlattSvg(h, m, opt) {
    const o = opt || {};
    const cx = 55, cy = 55, r = 46;
    const stundeWinkel = ((h % 12) + m / 60) * 30;
    const minuteWinkel = m * 6;
    const zeiger = (winkel, laenge, breite, farbe) => {
      const b = ((winkel - 90) * Math.PI) / 180;
      return `<line x1="${(cx - Math.cos(b) * 6).toFixed(1)}" y1="${(cy - Math.sin(b) * 6).toFixed(1)}"`
        + ` x2="${(cx + Math.cos(b) * laenge).toFixed(1)}" y2="${(cy + Math.sin(b) * laenge).toFixed(1)}"`
        + ` stroke="${farbe}" stroke-width="${breite}" stroke-linecap="round"/>`;
    };
    const zahlen = [];
    for (let n = 1; n <= 12; n++) {
      const b = ((n * 30 - 90) * Math.PI) / 180;
      zahlen.push(`<text x="${(cx + Math.cos(b) * 34).toFixed(1)}" y="${(cy + Math.sin(b) * 34 + 4).toFixed(1)}"`
        + ` text-anchor="middle" font-size="11" font-weight="800" fill="#4A3428">${n}</text>`);
    }
    const striche = [];
    for (let n = 0; n < 60; n++) {
      const b = ((n * 6 - 90) * Math.PI) / 180;
      const lang = n % 5 === 0;
      striche.push(`<line x1="${(cx + Math.cos(b) * (r - 3)).toFixed(1)}" y1="${(cy + Math.sin(b) * (r - 3)).toFixed(1)}"`
        + ` x2="${(cx + Math.cos(b) * (r - (lang ? 8 : 5))).toFixed(1)}" y2="${(cy + Math.sin(b) * (r - (lang ? 8 : 5))).toFixed(1)}"`
        + ` stroke="#B49B80" stroke-width="${lang ? 1.8 : 0.8}" stroke-linecap="round"/>`);
    }
    return `
      <circle cx="${cx}" cy="${cy}" r="${r + 4}" fill="#C8892F"/>
      <circle cx="${cx}" cy="${cy}" r="${r + 1}" fill="#F2B84B"/>
      <circle cx="${cx}" cy="${cy}" r="${r - 1}" fill="#FFFBF0"/>
      ${striche.join("")}
      ${zahlen.join("")}
      ${zeiger(stundeWinkel, 24, 6, "#4A3428")}
      ${zeiger(minuteWinkel, 36, 3.4, "#C64B3C")}
      <circle cx="${cx}" cy="${cy}" r="3.4" fill="#4A3428"/>
      ${o.ziffern ? `<text x="${cx}" y="${cy + 26}" text-anchor="middle" font-size="10" font-weight="800" fill="#8A7E6A">${uhrZiffern(h, m)}</text>` : ""}`;
  }
  /* Zwei Ansichten, je nach Frage. Beim Ablesen hängt die Uhr an der
     Wand und der Fuchs sitzt darunter. Beim Stellen sitzt er allein
     neben einem Zettel — und der Zettel ist bewusst HTML und nicht
     Teil der Zeichnung: ein Satz wie „dreiundzwanzig Uhr
     neunundfünfzig" bricht in SVG nicht um und stünde sonst quer
     über den halben Bildschirm hinaus. */
  function uhrWandSvg(a) {
    return `<svg class="uhr-szene" viewBox="0 0 230 138" role="img"
      aria-label="Eine Uhr an der Wand zeigt ${uhrZiffern(a.h, a.m)}.">
      <rect x="0" y="0" width="230" height="138" fill="#E7E0CE"/>
      <rect x="0" y="118" width="230" height="20" fill="#C6A87E"/>
      <path d="M0 118 h230" stroke="#A98A5F" stroke-width="2"/>
      <g transform="translate(102 6)">${uhrBlattSvg(a.h, a.m)}</g>
      <g transform="translate(44 118) scale(1.2)">${fuchsFigurSvg("sitzen")}</g>
    </svg>`;
  }
  function uhrFuchsSvg() {
    return `<svg class="uhr-fuchs" viewBox="0 0 80 76" aria-hidden="true">
      <g transform="translate(38 70) scale(1.5)">${fuchsFigurSvg("sitzen")}</g>
    </svg>`;
  }


  function renderFuchsuhr() {
    const area = document.getElementById("fuchsuhrArea");
    if (!area) return;
    if (!uhrSession) neueUhrSession();
    const s = uhrSession;
    if (s.runde >= s.gesamt) { renderFuchsuhrErgebnis(); return; }
    const a = s.aufgabe;
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Die Fuchsuhr: " + uhrZiffern(a.h, a.m))}
        <p class="eyebrow">🕰️ DIE FUCHSUHR · RUNDE ${s.runde + 1} / ${s.gesamt}
          <span class="subnav-info-icon" data-info="Mal zeigt die Uhr eine Zeit und du suchst die Worte, mal steht der Satz da und du suchst das passende Zifferblatt. Vorsicht bei „halb“: im Deutschen zeigt es auf die NÄCHSTE Stunde.">ⓘ</span></p>
        ${fortschrittHtml(s.runde, s.gesamt)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip uhr-level-btn ${uhrLevel === lvl ? "selected" : ""}" data-uhr-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        <p class="uhr-frage">${a.richtung === "lesen"
          ? (a.amtlich ? "Wie steht diese Zeit auf dem Fahrplan?" : "Wie spät ist es?")
          : "Welche Uhr zeigt das?"}</p>
        ${a.richtung === "lesen" ? uhrWandSvg(a) : `
          <div class="uhr-bote">
            ${uhrFuchsSvg()}
            <p class="uhr-zettel">${a.loesung}</p>
          </div>`}
        ${a.richtung === "lesen" ? `
          <div class="uhr-worte">
            ${a.wahl.map((w, i) => `<button type="button" class="uhr-wort" data-uhr-wahl="${i}">${uhrText(w.h, w.m, a.amtlich)}</button>`).join("")}
          </div>`
          : `<div class="uhr-blaetter">
            ${a.wahl.map((w, i) => `<button type="button" class="uhr-blatt" data-uhr-wahl="${i}" aria-label="${uhrZiffern(w.h, w.m)}">
              <svg viewBox="0 0 110 110" aria-hidden="true">${uhrBlattSvg(w.h, w.m)}</svg></button>`).join("")}
          </div>`}
        <p class="empty-note uhr-hinweis" id="uhrHinweis"></p>
      </div>`;
    area.querySelectorAll(".uhr-level-btn").forEach((b) => b.addEventListener("click", () => {
      uhrLevel = b.dataset.uhrLevel; neueUhrSession(); renderFuchsuhr();
    }));
    area.querySelectorAll("[data-uhr-wahl]").forEach((b) => b.addEventListener("click", () => uhrAntwort(Number(b.dataset.uhrWahl), b)));
  }

  function uhrAntwort(idx, knopf) {
    const s = uhrSession;
    if (s.zustand !== "warten") return;
    const a = s.aufgabe;
    const gewaehlt = a.wahl[idx];
    const richtig = gewaehlt.ok;
    s.zustand = richtig ? "richtig" : "falsch";
    spielNotiz(richtig, `${uhrZiffern(a.h, a.m)} — ${a.loesung}`);
    uhrKnoepfe().forEach((b) => { b.disabled = true; });
    uhrKnoepfe().forEach((b, i) => { if (a.wahl[i].ok) b.classList.add("uhr-treffer"); });
    if (!richtig) knopf.classList.add("uhr-daneben");
    const box = document.getElementById("uhrHinweis");
    if (box) {
      box.innerHTML = (richtig ? "✅ " : "❌ ")
        + `<strong>${uhrZiffernAnzeige(a)}</strong> — ${a.loesung}.<br>${uhrMerksatz(a)}`;
    }
    if (richtig) { s.richtig += 1; Core.sound.correct(); } else { Core.sound.wrong(); }
    s.runde += 1;
    setTimeout(() => { if (s.runde < s.gesamt) neueUhrRunde(); renderFuchsuhr(); }, richtig ? 2000 : 3200);
  }
  function uhrKnoepfe() {
    return [...document.querySelectorAll("#fuchsuhrArea [data-uhr-wahl]")];
  }

  function renderFuchsuhrErgebnis() {
    const area = document.getElementById("fuchsuhrArea");
    const s = uhrSession;
    const prozent = Math.round((s.richtig / Math.max(1, s.gesamt)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.richtig * 2, prozent, tier: "Uhrleser:in", charakter: "Die Fuchsuhr",
      zeilen: [{ name: "🕰️ Richtig abgelesen", anteil: prozent, wert: s.richtig + "/" + s.gesamt }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="uhrNochmal">🔄 Neue Runde</button>`,
    });
    document.getElementById("uhrNochmal")?.addEventListener("click", () => { neueUhrSession(); renderFuchsuhr(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["fuchsuhr"], points: s.richtig * 2, bonus: 0, percent: prozent, character: "Uhrleser:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-fuchsuhr"]')?.addEventListener("click", () => renderFuchsuhr());



  /* ============================================================
     WÖRTER-SORTIERER — Wortfelder statt Einzelvokabeln
     ------------------------------------------------------------
     Die Spiele bisher prüfen ein Wort für sich: Artikel, Betonung,
     Bedeutung. Was fehlte, war das Gefühl dafür, WOHIN ein Wort
     gehört — dass „die Kündigung“ ins Arbeitsleben gehört und „die
     Niederschlagsmenge“ zum Wetter. Genau das übt dieses Spiel.
     Die Wörter kommen aus dem Wörterbuch, gefiltert nach dem
     eingestellten Niveau: auf A1 sortiert man Brot und Bahnhof, auf
     C1 Rechtsbegriffe und Fachwörter. Damit hängt das Spiel wirklich
     an den Themen des jeweiligen Niveaus und nicht an einer festen
     kleinen Liste.
     ============================================================ */
  const SORT_RUNDEN = 12;      // so viele Wörter pro Runde
  const SORT_KOERBE = 3;       // so viele Themen stehen gleichzeitig zur Wahl
  let sortLevel = "";
  let sortSession = null;

  /* Themen, die sich im Alltagsverständnis überschneiden. Zwei davon
     stehen nie gleichzeitig als Körbe zur Wahl — sonst gäbe es Fragen,
     bei denen beide Antworten vertretbar sind. */
  const SORT_VERWANDT = [
    ["Stadt & Verkehr", "Reisen & Unterwegs"],
    ["Stadt & Verkehr", "Umwelt & Klima"],
    ["Stadt & Verkehr", "Technik & Erfindung"],
    ["Reisen & Unterwegs", "Freizeit & Sport"],
    ["Natur & Wetter", "Umwelt & Klima"],
    ["Natur & Wetter", "Freizeit & Sport"],
    ["Politik & Gesellschaft", "Recht & Verwaltung"],
    ["Politik & Gesellschaft", "Geschichte & Erinnerung"],
    ["Politik & Gesellschaft", "Wirtschaft & Arbeit"],
    ["Politik & Gesellschaft", "Medien & Öffentlichkeit"],
    ["Politik & Gesellschaft", "Umwelt & Klima"],
    ["Recht & Verwaltung", "Wirtschaft & Arbeit"],
    ["Sprache & Kommunikation", "Literatur & Schreiben"],
    ["Sprache & Kommunikation", "Medien & Öffentlichkeit"],
    ["Sprache & Kommunikation", "Grundwörter & Struktur"],
    ["Sprache & Kommunikation", "Denken & Argumentieren"],
    ["Literatur & Schreiben", "Kunst & Musik"],
    ["Literatur & Schreiben", "Medien & Öffentlichkeit"],
    ["Literatur & Schreiben", "Bildung & Lernen"],
    ["Literatur & Schreiben", "Geschichte & Erinnerung"],
    ["Kunst & Musik", "Medien & Öffentlichkeit"],
    ["Kunst & Musik", "Freizeit & Sport"],
    ["Denken & Argumentieren", "Wissenschaft & Forschung"],
    ["Denken & Argumentieren", "Bildung & Lernen"],
    ["Denken & Argumentieren", "Grundwörter & Struktur"],
    ["Wissenschaft & Forschung", "Bildung & Lernen"],
    ["Wissenschaft & Forschung", "Technik & Erfindung"],
    ["Wissenschaft & Forschung", "Umwelt & Klima"],
    ["Familie & Menschen", "Gefühle & Charakter"],
    ["Familie & Menschen", "Gesundheit & Körper"],
    ["Gefühle & Charakter", "Gesundheit & Körper"],
    ["Alltag & Zuhause", "Essen & Trinken"],
    ["Alltag & Zuhause", "Kleidung & Einkaufen"],
    ["Alltag & Zuhause", "Familie & Menschen"],
    ["Kleidung & Einkaufen", "Wirtschaft & Arbeit"],
    ["Essen & Trinken", "Gesundheit & Körper"],
    ["Zeit & Kalender", "Grundwörter & Struktur"],
    ["Zeit & Kalender", "Geschichte & Erinnerung"],
    ["Technik & Erfindung", "Medien & Öffentlichkeit"],
    ["Wirtschaft & Arbeit", "Bildung & Lernen"],
  ];
  let sortVerwandtSet = null;
  function sortSindVerwandt(a, b) {
    if (!sortVerwandtSet) {
      sortVerwandtSet = new Set();
      SORT_VERWANDT.forEach(([x, y]) => { sortVerwandtSet.add(x + "||" + y); sortVerwandtSet.add(y + "||" + x); });
    }
    return sortVerwandtSet.has(a + "||" + b);
  }

  /* Der Eindeutigkeits-Index: zu jedem Lemma und zu jedem
     Bestimmungswort die Themen, unter denen es im Wortschatz auftaucht.
     Wird einmal gebaut und an der Wortzahl gemessen zwischengespeichert. */
  let sortIndex = null;
  function sortEindeutigIndex() {
    const woerter = VocabData.WORDS || [];
    if (sortIndex && sortIndex.stand === woerter.length) return sortIndex;
    const ohneArtikel = (w) => String(w).replace(/^(der|die|das)\s+/i, "").toLowerCase();
    const nomen = new Set();
    const lemma = new Map();
    woerter.forEach((w) => {
      if (!w.word || !w.theme) return;
      const k = ohneArtikel(w.word);
      if (/^(der|die|das)\s/i.test(w.word)) nomen.add(k);
      if (!lemma.has(k)) lemma.set(k, new Set());
      lemma.get(k).add(w.theme);
    });
    /* Bestimmungswort = das längste bekannte NOMEN, das am Wortanfang
       steht und mindestens vier Buchstaben Rest übrig lässt. Die
       Nomen-Bedingung ist wichtig: sonst gälte „ver-", „unter-" oder
       „nach-" als Bestimmungswort und fast jedes zweite Wort wäre
       plötzlich mehrdeutig. */
    const stammVon = (wort) => {
      const k = ohneArtikel(wort);
      for (let len = Math.min(k.length - 4, 16); len >= 4; len--) {
        const st = k.slice(0, len);
        if (nomen.has(st)) return st;
      }
      return null;
    };
    const stamm = new Map();
    woerter.forEach((w) => {
      if (!w.word || !w.theme) return;
      const st = stammVon(w.word);
      if (!st) return;
      if (!stamm.has(st)) stamm.set(st, new Set());
      stamm.get(st).add(w.theme);
    });
    sortIndex = { stand: woerter.length, ohneArtikel, lemma, stamm, stammVon };
    return sortIndex;
  }

  /* Darf dieses Wort in einer Runde mit genau diesen Körbern gefragt
     werden, ohne dass eine zweite Antwort genauso vertretbar wäre? */
  function sortWortIstEindeutig(w, koerbe) {
    const ix = sortEindeutigIndex();
    const themenDesLemmas = ix.lemma.get(ix.ohneArtikel(w.word));
    if (themenDesLemmas && themenDesLemmas.size > 1) return false;
    const st = ix.stammVon(w.word);
    if (!st) return true;
    const themenDesStamms = ix.stamm.get(st);
    if (!themenDesStamms) return true;
    for (const t of themenDesStamms) if (t !== w.theme && koerbe.indexOf(t) >= 0) return false;
    return true;
  }

  /* ============================================================
     DIE FEINKATEGORIEN IM SORTIERSPIEL
     ------------------------------------------------------------
     GEMELDET: „Der Fahrradsattel könnte auch im Bereich Freizeit und
     Sport sein … Das darf nicht sein."

     Das Sortierspiel zog seine Körbe bisher aus den 26 großen Themen
     des Wörterbuchs. Die sind fürs Nachschlagen richtig, fürs
     Sortieren aber zu weit: „Natur & Wetter" enthält Tiere UND
     Wolken, „Freizeit & Sport" auch Fahrradteile. Ein Filter versuchte
     die Zweideutigkeiten herauszurechnen — eine Notlösung.

     Jetzt gibt es data-wortkategorien.js: 5.067 Wörter, jedes mit
     GENAU EINER Feinkategorie (Tiere, Körperteile, Obst, Gemüse,
     Werkzeuge, Möbel, Geld, Feiertage …), ermittelt aus der Erklärung,
     die im Wörterbuch ohnehin bei jedem Wort steht. Wörter ohne
     eindeutige Zuordnung stehen absichtlich nicht drin. Damit lassen
     sich Körbe bilden, bei denen es kein „könnte auch" gibt.
     ============================================================ */
  let wortKatGeladen = null;
  function wortKategorienLaden() {
    if (wortKatGeladen) return wortKatGeladen;
    if (window.DMA_WORTKATEGORIEN) { wortKatGeladen = Promise.resolve(true); return wortKatGeladen; }
    wortKatGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-wortkategorien.js?v=" + (window.DMA_VERSION || "1");
      s.async = true;
      s.onload = () => fertig(true);
      s.onerror = () => { wortKatGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return wortKatGeladen;
  }
  /* Körbe aus den Feinkategorien: Name des Korbs, dann die Wörter des
     gewählten Niveaus, die eindeutig dazugehören. */
  function sortFeinfelder(level) {
    const k = window.DMA_WORTKATEGORIEN;
    if (!k) { wortKategorienLaden(); return []; }
    const nachWort = new Map();
    (VocabData.WORDS || []).forEach((w) => { if (w.word) nachWort.set(w.word, w); });
    const felder = [];
    Object.entries(k.woerter || {}).forEach(([kat, woerter]) => {
      const liste = woerter
        .map((x) => nachWort.get(x))
        .filter((w) => w && w.level === level);
      if (liste.length >= 6) felder.push([k.namen[kat] || kat, liste]);
    });
    return felder;
  }

  /* Drei Körbe ziehen, die nichts miteinander zu tun haben — und in
     denen nach der Eindeutigkeits-Prüfung noch genug Wörter übrig sind. */
  function sortKoerbeZiehen(felder, proKorb) {
    for (let versuch = 0; versuch < 60; versuch++) {
      const misch = Core.shuffle(felder.slice());
      const gewaehlt = [];
      for (const eintrag of misch) {
        if (gewaehlt.some(([t]) => sortSindVerwandt(t, eintrag[0]))) continue;
        gewaehlt.push(eintrag);
        if (gewaehlt.length === SORT_KOERBE) break;
      }
      if (gewaehlt.length < SORT_KOERBE) continue;
      const namen = gewaehlt.map(([t]) => t);
      const gefiltert = gewaehlt.map(([thema, liste]) => [thema, liste.filter((w) => sortWortIstEindeutig(w, namen))]);
      if (gefiltert.every(([, liste]) => liste.length >= proKorb)) return gefiltert;
    }
    return null;
  }

  // Alle Wörter des Niveaus, nach Thema gebündelt — nur Themen mit genug
  // Material, sonst wiederholen sich dieselben zwei Wörter.
  function sortWortfelder(level) {
    const nach = {};
    (VocabData.WORDS || []).forEach((w) => {
      if (w.level !== level || !w.theme || !w.word) return;
      (nach[w.theme] = nach[w.theme] || []).push(w);
    });
    return Object.entries(nach).filter(([, liste]) => liste.length >= 6);
  }

  function neueSortSession() {
    /* Zuerst die Feinkategorien versuchen — sie sind eindeutig. Erst
       wenn für dieses Niveau zu wenige davon Material haben, treten die
       großen Themen wie bisher an ihre Stelle. */
    const fein = sortFeinfelder(sortLevel);
    const felder = fein.length >= SORT_KOERBE ? fein : sortWortfelder(sortLevel);
    if (felder.length < SORT_KOERBE) { sortSession = { leer: true }; return; }
    // Aus jedem Feld gleich viele Wörter, damit kein Korb erkennbar häufiger stimmt.
    const proKorb = Math.ceil(SORT_RUNDEN / SORT_KOERBE);
    const gewaehlt = sortKoerbeZiehen(felder, proKorb);
    if (!gewaehlt) { sortSession = { leer: true }; return; }
    const karten = [];
    gewaehlt.forEach(([thema, liste]) => {
      Core.shuffle(liste).slice(0, proKorb).forEach((w) => karten.push({ wort: w.word, thema, bedeutung: w.de || "", beispiel: w.example || "", syl: w.syl || "" }));
    });
    sortSession = {
      koerbe: gewaehlt.map(([thema]) => thema),
      karten: Core.shuffle(karten).slice(0, SORT_RUNDEN),
      index: 0, richtig: 0, serie: 0, besteSerie: 0,
      letzte: null, fehler: [],
    };
  }

  function sortAntwort(thema) {
    const s = sortSession;
    const karte = s.karten[s.index];
    const korrekt = thema === karte.thema;
    spielNotiz(korrekt, `${karte.wort || karte.text || ""} → ${karte.thema}`);
    if (korrekt) {
      s.richtig += 1;
      s.serie += 1;
      s.besteSerie = Math.max(s.besteSerie, s.serie);
      Core.sound.correct();
    } else {
      s.serie = 0;
      s.fehler.push(karte);
      Core.sound.wrong();
    }
    s.letzte = { karte, gewaehlt: thema, korrekt };
    s.index += 1;
    renderSortierer();
  }

  function renderSortierer() {
    const area = document.getElementById("sortiererArea");
    if (!area) return;
    if (!window.DMA_WORTKATEGORIEN) {
      wortKategorienLaden().then((ok) => { if (ok && sortSession && sortSession.leer) { sortSession = null; renderSortierer(); } });
    }
    if (!renderComingSoonGate(area, "sortierer_neu", "Wörter-Sortierer", "🧺")) return;
    sortLevel = applyDefaultCefrLevel(sortLevel, (v) => { sortLevel = v; }, "sortierer");
    if (!sortSession) neueSortSession();
    const s = sortSession;

    const niveauReihe = `
      <div class="baustein-reihe" style="margin-bottom:12px;">
        ${CEFR_LEVELS.map((l) => `<button type="button" class="trophy-chip sort-level-btn ${l === sortLevel ? "selected" : ""}" data-sort-level="${l}">${l}</button>`).join("")}
      </div>`;

    if (s.leer) {
      area.innerHTML = niveauReihe + `<p class="empty-note">Für ${sortLevel} sind noch nicht genug Wortfelder im Wörterbuch. Wähl ein anderes Niveau.</p>`;
      area.querySelectorAll("[data-sort-level]").forEach((b) => b.addEventListener("click", () => {
        sortLevel = b.dataset.sortLevel; autoCefrLevel.sortierer = null; sortSession = null; renderSortierer();
      }));
      return;
    }
    if (s.index >= s.karten.length) { renderSortiererErgebnis(); return; }

    const karte = s.karten[s.index];
    const rueckmeldung = s.letzte
      ? `<p class="empty-note" style="margin:8px 0 0; color:${s.letzte.korrekt ? "var(--teal-400)" : "#c0392b"};">
           ${s.letzte.korrekt ? "✅" : "❌"} „${s.letzte.karte.wort}“ gehört zu <strong>${s.letzte.karte.thema}</strong>${s.letzte.karte.bedeutung ? " — " + s.letzte.karte.bedeutung : ""}
         </p>` : "";

    area.innerHTML = `
      <p class="empty-note" style="margin-bottom:10px;">🧺 <strong>Wörter-Sortierer</strong> — in welches Wortfeld gehört das Wort? Die Wörter kommen aus dem Wörterbuch und richten sich nach deinem Niveau.</p>
      ${niveauReihe}
      ${fortschrittHtml(s.index, s.karten.length)}
      <div class="question-card">
        ${miniBugReportBtnHtml("Wörter-Sortierer: " + karte.wort)}
        <div class="question-meta"><span class="cat-tag">🧺 Wort ${s.index + 1} / ${s.karten.length}</span> · Serie: ${s.serie}${s.serie >= 3 ? " 🔥" : ""}</div>
        <div class="question-prompt" style="text-align:center; font-size:1.35rem; margin:14px 0;">${karte.wort}</div>
        ${karte.syl && isStressModeOn() ? `<div class="vocab-syl" style="text-align:center; margin:-8px 0 12px;">${betonungAnzeigen(karte.syl)}</div>` : ""}
        <div class="option-list">
          ${s.koerbe.map((t) => `<button type="button" class="option-btn sort-korb" data-sort-korb="${t.replace(/"/g, "&quot;")}"><span>${t}</span></button>`).join("")}
        </div>
        ${rueckmeldung}
      </div>`;

    area.querySelectorAll("[data-sort-korb]").forEach((b) => b.addEventListener("click", () => sortAntwort(b.dataset.sortKorb)));
    area.querySelectorAll("[data-sort-level]").forEach((b) => b.addEventListener("click", () => {
      sortLevel = b.dataset.sortLevel; autoCefrLevel.sortierer = null; sortSession = null; renderSortierer();
    }));
  }

  function renderSortiererErgebnis() {
    const area = document.getElementById("sortiererArea");
    const s = sortSession;
    const prozent = Math.round((s.richtig / Math.max(1, s.karten.length)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.richtig * 2, prozent: prozent, tier: "Sortierprofi",
      charakter: "Wörter-Sortierer", zeilen: [{ name: "🧺 Richtig einsortiert", anteil: prozent, wert: s.richtig + "/" + s.karten.length }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="sortNochmal">🔄 Neue Runde</button>`,
    });
    document.getElementById("sortNochmal").addEventListener("click", () => { sortSession = null; renderSortierer(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["sortierer"], points: s.richtig * 2, bonus: s.besteSerie >= 6 ? 5 : 0,
        percent: prozent, character: "Wortfeld-Kenner:in", badges: [], playedAt: new Date().toISOString() });
    }
  }

